{
  "name": "CognixAI",
  "description": "Your sleek, private intelligence companion. Built with high-performance Gemini integration.",
  "requestFramePermissions": [
    "microphone",
    "camera",
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-black dark:bg-white', primaryHover: 'opacity-90', text: 'text-black dark:text-white', textDark: 'text-white dark:text-black', bgSoft: 'bg-zinc-100', darkBgSoft: 'dark:bg-zinc-900', border: 'border-zinc-200 dark:border-zinc-800', ring: 'focus:ring-black dark:focus:ring-white', gradient: 'bg-black dark:bg-white' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-600 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-600 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-600 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-600 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-pro-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are CognixAI, a sleek, intelligent, and creative assistant. You are helpful, minimalist, and technically gifted.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark') { setIsDarkMode(true); document.documentElement.classList.add('dark'); }
  }, []);

  useEffect(() => localStorage.setItem('cognix_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => {
    if (isDarkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('cognix_theme', 'dark'); }
    else { document.documentElement.classList.remove('dark'); localStorage.setItem('cognix_theme', 'light'); }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => { setMessages(currentChat ? currentChat.messages : []); }, [currentChat?.id]);

  const handleNewChat = () => { 
    setActiveChatId(null); 
    setMessages([]); 
    setMode('chat'); 
    setIsSidebarOpen(false); 
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-white dark:bg-black transition-colors duration-300">
      <Sidebar 
        chatHistory={chatHistory} activeChatId={activeChatId} mode={mode}
        onSetMode={(m) => { setMode(m); setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { setChatHistory(h => h.filter(c => c.id !== id)); if (activeChatId === id) { setActiveChatId(null); setMessages([]); } }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen} isDesktopSidebarOpen={true} theme={activeTheme} friends={friends}
      />

      <div className="flex-1 flex flex-col h-full bg-white dark:bg-black transition-all duration-300 relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-5 shrink-0 z-30 border-b border-zinc-100 dark:border-zinc-900 bg-white/80 dark:bg-black/80 backdrop-blur-xl">
             <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
                  className="p-2 -ml-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all lg:hidden"
                >
                    <MenuIcon className="w-6 h-6"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-sm font-bold tracking-tight">
                      {mode === 'chat' ? 'CognixAI' : mode.charAt(0).toUpperCase() + mode.slice(1)}
                  </h1>
                </div>
             </div>
             <div className="flex items-center gap-2">
                 <button 
                  onClick={() => setIsSettingsOpen(true)} 
                  className="p-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all"
                 >
                    <UserIcon className="w-5 h-5"/>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} uiStyle={'modern'} theme={activeTheme} fontSize={'normal'} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} friends={friends} />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
            {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle={'modern'} setUiStyle={() => {}} 
        accentColor={accentColor} setAccentColor={setAccentColor} 
        fontSize={'normal'} setFontSize={() => {}} 
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode} 
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }} 
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction} 
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ThemeColors, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: any;
  theme: ThemeColors;
  fontSize: any;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel, friends = [] }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImageRequest = /generate (an )?image|create (an )?image|draw|paint/i.test(textInput);

      let targetModel: string = model === 'gemini-3-pro-preview' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
      if (isImageRequest) targetModel = 'gemini-2.5-flash-image';

      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      for (const part of response.candidates[0].content.parts) {
        if (part.text) responseParts.push({ text: part.text });
        else if (part.inlineData) responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
      }

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: responseParts, isSearching: false } : m));
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Error connecting to brain. Please check your signal.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  return (
    <div className="flex flex-col h-full w-full bg-white dark:bg-black">
      {/* Messages */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-24 xl:px-48 pb-32 pt-6 scroll-smooth">
        {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center py-20">
                 <BotIcon className="w-12 h-12 mb-6" />
                 <h2 className="text-2xl font-bold tracking-tight mb-2">CognixAI</h2>
                 <p className="text-zinc-500 text-sm max-w-xs">Simple, private, and powerful. How can I help you today?</p>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-8">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 sm:gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} slide-in`}>
                        <div className={`w-8 h-8 shrink-0 rounded-full flex items-center justify-center text-xs
                            ${msg.role === 'user' ? 'bg-zinc-100 dark:bg-zinc-900 text-zinc-500' : 'bg-black dark:bg-white text-white dark:text-black'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-4 h-4"/>}
                        </div>
                        <div className={`flex flex-col gap-2 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`px-4 py-3 rounded-2xl text-sm sm:text-base leading-relaxed ${msg.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                                     {part.inlineData && (
                                       <div className="mb-3 rounded-lg overflow-hidden shadow-sm">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-[400px] w-full object-contain bg-zinc-100 dark:bg-zinc-900" alt="Output"/>
                                       </div>
                                     )}
                                     <div className="whitespace-pre-wrap font-medium">{part.text}</div>
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 items-center opacity-50">
                    <div className="w-8 h-8 rounded-full bg-black dark:bg-white flex items-center justify-center text-white dark:text-black"><BotIcon className="w-4 h-4"/></div>
                    <div className="flex gap-1">
                        <div className="w-1 h-1 bg-zinc-400 rounded-full animate-bounce"></div>
                        <div className="w-1 h-1 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                        <div className="w-1 h-1 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* Input - Mobile Optimized */}
      <div className="absolute bottom-0 left-0 right-0 p-4 sm:p-6 bg-gradient-to-t from-white dark:from-black via-white dark:via-black to-transparent z-40">
          <div className="max-w-3xl mx-auto">
              <div className="bg-zinc-50 dark:bg-zinc-900/80 backdrop-blur-xl rounded-3xl border border-zinc-200 dark:border-zinc-800 p-2 shadow-2xl">
                   {/* Tool Bar */}
                   <div className="flex items-center gap-4 px-3 py-1 mb-1 border-b border-zinc-200 dark:border-zinc-800/50">
                        <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[10px] font-bold uppercase tracking-wider transition-colors ${webSearchEnabled ? 'text-black dark:text-white' : 'text-zinc-400'}`}>
                           Search {webSearchEnabled ? 'On' : 'Off'}
                        </button>
                        <button onClick={() => setActiveModel(m => m === 'gemini-3-pro-preview' ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')} className="text-[10px] font-bold uppercase tracking-wider text-zinc-400">
                           {model === 'gemini-3-pro-preview' ? 'Pro' : 'Flash'}
                        </button>
                   </div>

                   <div className="flex items-end gap-2 px-2 pb-1">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3 text-zinc-400 hover:text-black dark:hover:text-white transition-all">
                            <ImageIcon className="w-5 h-5"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type a message..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-sm text-zinc-800 dark:text-zinc-100 placeholder-zinc-400 font-medium max-h-32 min-h-[44px]"
                            rows={1} />

                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} className="w-10 h-10 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center disabled:opacity-20 active:scale-95 transition-all">
                             <SendIcon className="w-5 h-5"/>
                        </button>
                   </div>

                   {selectedImage && (
                      <div className="p-2 animate-slide-up">
                          <div className="relative w-12 h-12 rounded-lg overflow-hidden border border-zinc-200 dark:border-zinc-800">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Preview"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/50 text-white flex items-center justify-center text-xs">✕</button>
                          </div>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, ThemeColors, Friend } from '../types';
import { BotIcon, TrashIcon, PencilIcon, MicrophoneIcon, UsersIcon, CodeIcon, SparklesIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  isSidebarOpen: boolean;
  isDesktopSidebarOpen: boolean;
  theme: ThemeColors;
  friends: Friend[];
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, onDeleteChat, onRenameChat, isSidebarOpen, theme,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => (
    <button
        onClick={() => onSetMode(m)}
        className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all
            ${mode === m 
                ? 'bg-zinc-100 dark:bg-zinc-900 text-black dark:text-white font-bold' 
                : 'text-zinc-500 hover:text-black dark:hover:text-white'}
        `}
    >
        <span className="shrink-0">{icon}</span>
        <span className="text-xs tracking-tight">{label}</span>
    </button>
  );

  return (
    <>
      {/* Overlay for mobile */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-40 lg:hidden" onClick={() => onSetMode(mode)}></div>
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex flex-col bg-white dark:bg-black border-r border-zinc-100 dark:border-zinc-900
        ${isSidebarOpen ? 'translate-x-0 w-[260px]' : '-translate-x-full lg:translate-x-0 lg:w-[260px]'}
      `}>
        <div className="p-6 pb-2">
          <div className="flex items-center gap-3 mb-8 cursor-pointer" onClick={() => onSetMode('chat')}>
              <BotIcon className="w-8 h-8 text-black dark:text-white" />
              <h1 className="text-lg font-bold tracking-tighter">CognixAI</h1>
          </div>

          <button onClick={onNewChat} className="w-full flex items-center justify-center py-2.5 bg-black dark:bg-white text-white dark:text-black rounded-xl font-bold text-xs uppercase tracking-widest transition-all active:scale-95 mb-6">
            New Chat
          </button>
        </div>

        <nav className="px-3 space-y-1 mb-6">
          <NavItem m="chat" icon={<SparklesIcon className="w-4 h-4" />} label="Brain" />
          <NavItem m="coding" icon={<CodeIcon className="w-4 h-4" />} label="Studio" />
          <NavItem m="live" icon={<MicrophoneIcon className="w-4 h-4" />} label="Voice" />
          <NavItem m="community" icon={<UsersIcon className="w-4 h-4" />} label="Network" />
        </nav>

        <div className="flex-1 overflow-y-auto px-3 pb-8">
              <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest px-4 mb-3">Recent</h3>
              <div className="space-y-0.5">
                  {chatHistory.map((chat) => (
                      <div key={chat.id} onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                          className={`group relative flex items-center justify-between px-4 py-2 cursor-pointer rounded-lg transition-all
                          ${activeChatId === chat.id && mode === 'chat'
                              ? 'bg-zinc-100 dark:bg-zinc-900 text-black dark:text-white font-bold'
                              : 'text-zinc-500 hover:text-black dark:hover:text-white'}
                          `}
                      >
                          {editingChatId === chat.id ? (
                              <input ref={inputRef} type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onBlur={handleRename} onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                  className="bg-transparent border-none w-full outline-none text-xs font-bold" />
                          ) : (
                              <>
                              <span className="truncate text-xs">{chat.title}</span>
                              <div className="hidden group-hover:flex items-center gap-1">
                                  <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 hover:text-zinc-800 transition-colors"><PencilIcon className="w-3 h-3"/></button>
                                  <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 hover:text-red-500 transition-colors"><TrashIcon className="w-3 h-3"/></button>
                              </div>
                              </>
                          )}
                      </div>
                  ))}
              </div>
        </div>

        <div className="p-6 border-t border-zinc-100 dark:border-zinc-900">
            <p className="text-[10px] font-bold text-zinc-400 text-center uppercase tracking-widest">
              Private & Encrypted
            </p>
        </div>
      </aside>
    </>
  );
};

import React from 'react';
import { TrashIcon, SparklesIcon, UserIcon } from './Icons';
import type { AccentColor } from '../types';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    uiStyle: any;
    setUiStyle: (style: any) => void;
    accentColor: AccentColor;
    setAccentColor: (color: AccentColor) => void;
    fontSize: any;
    setFontSize: (size: any) => void;
    isDarkMode: boolean;
    setIsDarkMode: (isDark: boolean) => void;
    onClearHistory: () => void;
    systemInstruction: string;
    setSystemInstruction: (val: string) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ 
