const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are CognixAI, an elite, minimalist artificial intelligence. You communicate with precision, offering high-level engineering, creative, and logical insights. You are private, secure, and helpful.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark') { setIsDarkMode(true); document.documentElement.classList.add('dark'); }
  }, []);

  useEffect(() => localStorage.setItem('cognix_history', JSON.stringify(chatHistory)), [chatHistory]);

  useEffect(() => {
    if (isDarkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('cognix_theme', 'dark'); }
    else { document.documentElement.classList.remove('dark'); localStorage.setItem('cognix_theme', 'light'); }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => { setMessages(currentChat ? currentChat.messages : []); }, [currentChat?.id]);

  const handleNewChat = () => { 
    setActiveChatId(null); 
    setMessages([]); 
    setMode('chat'); 
    setIsSidebarOpen(false); 
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-white dark:bg-black transition-colors duration-300">
      <Sidebar 
        chatHistory={chatHistory} activeChatId={activeChatId} mode={mode}
        onSetMode={(m) => { setMode(m); setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { setChatHistory(h => h.filter(c => c.id !== id)); if (activeChatId === id) { setActiveChatId(null); setMessages([]); } }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen} isDesktopSidebarOpen={true} theme={activeTheme} friends={friends}
      />

      <div className="flex-1 flex flex-col h-full bg-white dark:bg-black relative overflow-hidden">
        <header className="h-14 lg:h-16 flex items-center justify-between px-4 sm:px-6 shrink-0 z-30 border-b border-zinc-100 dark:border-zinc-900 bg-white/80 dark:bg-black/80 backdrop-blur-xl">
             <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(true)} 
                  className="p-2 -ml-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all lg:hidden"
                >
                    <MenuIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
                </button>
                <h1 className="text-sm font-bold tracking-tight uppercase">
                    {mode === 'chat' ? 'CognixAI' : mode}
                </h1>
             </div>
             <div className="flex items-center gap-2">
                 <button 
                  onClick={() => setIsSettingsOpen(true)} 
                  className="p-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all"
                 >
                    <UserIcon className="w-5 h-5"/>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} uiStyle={'modern'} theme={activeTheme} fontSize={'normal'} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} friends={friends} />
            )}
