import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ThemeColors, ModelType, Friend } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon, SearchIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: any;
  theme: ThemeColors;
  fontSize: any;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  friends?: Friend[];
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImageRequest = /generate (an )?image|create (an )?image|draw|paint/i.test(textInput);

      let targetModel: string = model === 'gemini-3-pro-preview' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
      if (isImageRequest) targetModel = 'gemini-2.5-flash-image';

      const history = messages.slice(-10).map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      for (const part of response.candidates[0].content.parts) {
        if (part.text) responseParts.push({ text: part.text });
        else if (part.inlineData) responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
      }

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: responseParts, isSearching: false } : m));
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Connection disrupted. Please retry.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  return (
    <div className="flex flex-col h-full w-full bg-white dark:bg-black">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-24 xl:px-48 pb-32 pt-6 scroll-smooth">
        {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center py-10 opacity-60">
                 <BotIcon className="w-14 h-14 mb-6 grayscale dark:invert" />
                 <h2 className="text-xl font-bold tracking-widest uppercase mb-2">CognixAI</h2>
                 <p className="text-zinc-500 text-xs max-w-xs">Elite intelligence ready for instructions.</p>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-10">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                        <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-full flex items-center justify-center
                            ${msg.role === 'user' ? 'bg-zinc-100 dark:bg-zinc-900' : 'bg-black dark:bg-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5 text-zinc-500"/> : <BotIcon className="w-5 h-5 text-white dark:text-black"/>}
                        </div>
                        <div className={`flex flex-col gap-2 max-w-[85%] sm:max-w-[80%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`px-4 py-3 sm:px-5 sm:py-4 rounded-2xl sm:rounded-3xl text-sm sm:text-base leading-relaxed ${msg.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot shadow-sm'}`}>
                                     {part.inlineData && (
                                       <div className="mb-3 rounded-xl overflow-hidden shadow-md">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-[300px] sm:max-h-[450px] w-full object-contain bg-zinc-100 dark:bg-zinc-900" alt="Result"/>
                                       </div>
                                     )}
                                     {part.text && <div className="whitespace-pre-wrap font-medium">{part.text}</div>}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 items-center opacity-30">
                    <div className="w-8 h-8 rounded-full bg-black dark:bg-white flex items-center justify-center"><BotIcon className="w-4 h-4 text-white dark:text-black"/></div>
                    <div className="flex gap-1.5">
                        <div className="w-1.5 h-1.5 bg-zinc-400 rounded-full animate-bounce"></div>
                        <div className="w-1.5 h-1.5 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                        <div className="w-1.5 h-1.5 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 sm:p-6 lg:pl-72 bg-gradient-to-t from-white dark:from-black via-white/95 dark:via-black/95 to-transparent z-40">
          <div className="max-w-3xl mx-auto">
              <div className="bg-zinc-50/50 dark:bg-zinc-900/50 backdrop-blur-2xl rounded-3xl border border-zinc-200/50 dark:border-zinc-800/50 p-2 shadow-2xl flex flex-col gap-1">
                   <div className="flex items-center gap-4 px-4 py-1.5 border-b border-zinc-200/20 dark:border-zinc-800/20">
                        <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[9px] font-bold uppercase tracking-widest transition-all ${webSearchEnabled ? 'text-sky-500' : 'text-zinc-400'}`}>
                           Search {webSearchEnabled ? 'Active' : 'Offline'}
                        </button>
                        <button onClick={() => setActiveModel(m => m === 'gemini-3-pro-preview' ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')} className="text-[9px] font-bold uppercase tracking-widest text-zinc-400 hover:text-black dark:hover:text-white transition-all">
                           Engine: {model.split('-')[2].toUpperCase()}
                        </button>
                   </div>

                   <div className="flex items-end gap-1 px-1">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3.5 text-zinc-400 hover:text-black dark:hover:text-white active:scale-90 transition-all">
                            <ImageIcon className="w-5 h-5"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Instruction..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-1 text-sm sm:text-base text-zinc-800 dark:text-zinc-100 placeholder-zinc-400 font-medium max-h-40 min-h-[46px]"
                            rows={1} />

                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                          className="w-11 h-11 shrink-0 bg-black dark:bg-white text-white dark:text-black rounded-2xl flex items-center justify-center disabled:opacity-10 active:scale-90 transition-all shadow-lg">
                             <SendIcon className="w-5 h-5"/>
                        </button>
                   </div>

                   {selectedImage && (
                      <div className="px-3 pb-3 pt-1 animate-slide-up">
                          <div className="relative w-14 h-14 rounded-xl overflow-hidden border border-zinc-200 dark:border-zinc-800 shadow-lg group">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Selected"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/40 text-white flex items-center justify-center text-xs opacity-0 group-hover:opacity-100 transition-opacity">✕</button>
                          </div>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

