                 <BotIcon className="w-16 h-16 mb-6 grayscale dark:invert" />
                 <h2 className="text-xl font-bold tracking-widest uppercase mb-2">CognixAI</h2>
                 <p className="text-zinc-500 text-xs max-w-xs">Awaiting instructions. Secure and private brain link active.</p>
