                        <div className="w-1.5 h-1.5 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                        <div className="w-1.5 h-1.5 bg-zinc-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-3 sm:p-6 lg:pl-[260px] bg-gradient-to-t from-white dark:from-black via-white/95 dark:via-black/95 to-transparent z-40 pb-safe">
          <div className="max-w-3xl mx-auto">
              <div className="bg-zinc-50 dark:bg-zinc-900/80 backdrop-blur-3xl rounded-[2rem] border border-zinc-200 dark:border-zinc-800 p-2 shadow-2xl flex flex-col gap-1">
                   <div className="flex items-center gap-4 px-4 py-1.5 border-b border-zinc-200/30 dark:border-zinc-800/30">
                        <button onClick={() => setWebSearchEnabled(!webSearchEnabled)} className={`text-[9px] font-bold uppercase tracking-[0.2em] transition-all ${webSearchEnabled ? 'text-sky-500' : 'text-zinc-400'}`}>
                           Search: {webSearchEnabled ? 'On' : 'Off'}
