                        <button onClick={() => setActiveModel(m => m === 'gemini-3-pro-preview' ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')} className="text-[9px] font-bold uppercase tracking-[0.2em] text-zinc-400 hover:text-black dark:hover:text-white transition-all">
                           Engine: {model.includes('pro') ? 'PRO' : 'FLASH'}
                        </button>
                   </div>

                   <div className="flex items-end gap-1 px-1">
                        <button onClick={() => fileInputRef.current?.click()} className="p-3 text-zinc-400 hover:text-black dark:hover:text-white active:scale-90 transition-all">
                            <ImageIcon className="w-5 h-5"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Type instruction..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-1 text-sm sm:text-base text-zinc-800 dark:text-zinc-100 placeholder-zinc-400 font-medium max-h-40 min-h-[46px]"
                            rows={1} />

                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                          className="w-11 h-11 shrink-0 bg-black dark:bg-white text-white dark:text-black rounded-2xl flex items-center justify-center disabled:opacity-10 active:scale-95 transition-all shadow-lg">
