                   {selectedImage && (
                      <div className="px-3 pb-3 pt-1 animate-slide-up">
                          <div className="relative w-14 h-14 rounded-xl overflow-hidden border border-zinc-200 dark:border-zinc-800 shadow-md">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Pulse Upload"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/40 text-white flex items-center justify-center text-xs font-bold transition-opacity">✕</button>
                          </div>
                      </div>
                   )}
              </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { MenuIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-black dark:bg-white', primaryHover: 'opacity-90', text: 'text-black dark:text-white', textDark: 'text-white dark:text-black', bgSoft: 'bg-zinc-100', darkBgSoft: 'dark:bg-zinc-900', border: 'border-zinc-200 dark:border-zinc-800', ring: 'focus:ring-black dark:focus:ring-white', gradient: 'bg-black dark:bg-white' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-600 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-600 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-600 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-600 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are CognixAI, an elite minimalist intelligence. Your purpose is to provide high-precision engineering, logic, and creative pulse outputs. You are private, secure, and communicate with absolute clarity.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark') { setIsDarkMode(true); document.documentElement.classList.add('dark'); }
  }, []);

  useEffect(() => localStorage.setItem('cognix_history', JSON.stringify(chatHistory)), [chatHistory]);

  useEffect(() => {
    if (isDarkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('cognix_theme', 'dark'); }
    else { document.documentElement.classList.remove('dark'); localStorage.setItem('cognix_theme', 'light'); }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => { setMessages(currentChat ? currentChat.messages : []); }, [currentChat?.id]);

  const handleNewChat = () => { 
    setActiveChatId(null); 
    setMessages([]); 
    setMode('chat'); 
    setIsSidebarOpen(false); 
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-white dark:bg-black transition-colors duration-300">
      <Sidebar 
        chatHistory={chatHistory} activeChatId={activeChatId} mode={mode}
        onSetMode={(m) => { setMode(m); setIsSidebarOpen(false); }}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); setIsSidebarOpen(false); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { setChatHistory(h => h.filter(c => c.id !== id)); if (activeChatId === id) { setActiveChatId(null); setMessages([]); } }}
        onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
        onOpenSettings={() => setIsSettingsOpen(true)}
        isSidebarOpen={isSidebarOpen} isDesktopSidebarOpen={true} theme={activeTheme} friends={friends}
      />

      <div className="flex-1 flex flex-col h-full bg-white dark:bg-black relative overflow-hidden">
        <header className="h-14 lg:h-16 flex items-center justify-between px-4 sm:px-6 shrink-0 z-30 border-b border-zinc-100 dark:border-zinc-900 bg-white/80 dark:bg-black/80 backdrop-blur-xl">
             <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(true)} 
                  className="p-2 -ml-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all lg:hidden"
                >
                    <MenuIcon className="w-6 h-6"/>
                </button>
                <h1 className="text-xs font-black tracking-[0.2em] uppercase text-zinc-400">
                    {mode === 'chat' ? 'CognixAI' : mode}
                </h1>
             </div>
             <div className="flex items-center gap-2">
                 <button 
                  onClick={() => setIsSettingsOpen(true)} 
                  className="p-2 text-zinc-500 hover:text-black dark:hover:text-white transition-all"
                 >
                    <UserIcon className="w-5 h-5"/>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} uiStyle={'modern'} theme={activeTheme} fontSize={'normal'} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} friends={friends} />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
            {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle={'modern'} setUiStyle={() => {}} 
        accentColor={accentColor} setAccentColor={setAccentColor} 
        fontSize={'normal'} setFontSize={() => {}} 
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode} 
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }} 
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction} 
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ThemeColors, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { BotIcon, SendIcon, UserIcon, ImageIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  theme: ThemeColors;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, theme, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [webSearchEnabled, setWebSearchEnabled] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholderId = `msg-${Date.now() + 1}`;
    const modelPlaceholder: ChatMessage = { id: modelPlaceholderId, role: 'model', parts: [{ text: '' }], isSearching: webSearchEnabled };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImageRequest = /generate|create|draw|paint|make an image/i.test(textInput);

      let targetModel: string = model.includes('pro') ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
      if (isImageRequest) targetModel = 'gemini-2.5-flash-image';

      const history = messages.slice(-12).map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      const response = await ai.models.generateContent({
          model: targetModel,
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { 
            systemInstruction: systemInstruction,
            tools: !isImageRequest && webSearchEnabled ? [{ googleSearch: {} }] : [] 
          },
      });

      let responseParts: ChatPart[] = [];
      const parts = response.candidates?.[0]?.content?.parts || [];
      for (const part of parts) {
        if (part.text) responseParts.push({ text: part.text });
        else if (part.inlineData) responseParts.push({ inlineData: { mimeType: part.inlineData.mimeType, data: part.inlineData.data } });
      }

      if (responseParts.length === 0) responseParts = [{ text: "Analysis complete. System ready." }];

      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: responseParts, isSearching: false } : m));
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholderId ? { ...m, parts: [{ text: `Engine disruption detected. Please restart link.` }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction, model, webSearchEnabled, setMessages]);

  return (
    <div className="flex flex-col h-full w-full bg-white dark:bg-black transition-colors duration-500">
      {/* Messages Layer */}
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-48 pt-10 scroll-smooth">
        {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center animate-spring-up">
                 <div className="relative mb-10 group">
                    <div className="absolute -inset-4 bg-brand-500/20 rounded-full blur-2xl group-hover:bg-brand-500/30 transition-all duration-700 animate-pulse-slow"></div>
                    <BotIcon className="w-20 h-20 relative grayscale dark:invert brightness-125 animate-float" />
                 </div>
                 <h2 className="text-3xl font-black tracking-tighter uppercase mb-3 bg-gradient-to-b from-slate-900 to-slate-500 dark:from-white dark:to-slate-600 bg-clip-text text-transparent">
                    CognixAI
                 </h2>
                 <p className="text-slate-400 dark:text-slate-500 text-xs font-mono tracking-[0.3em] uppercase max-w-xs">
                    Universal Logic Engine Active
                 </p>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-12">
                {messages.map((msg) => (
                    <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-spring-up`}>
                        <div className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center shadow-lg
                            ${msg.role === 'user' ? 'bg-slate-100 dark:bg-slate-800' : 'bg-black dark:bg-white'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5 text-slate-500"/> : <BotIcon className="w-5 h-5 text-white dark:text-black"/>}
                        </div>
                        <div className={`flex flex-col gap-2 max-w-[90%] sm:max-w-[75%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`px-5 py-4 text-sm sm:text-[15px] leading-relaxed transition-all duration-300 shadow-sm border border-transparent dark:border-white/5 ${msg.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                                     {part.inlineData && (
                                       <div className="mb-4 rounded-xl overflow-hidden shadow-2xl bg-black">
                                          <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-h-[350px] sm:max-h-[500px] w-full object-contain" alt="Cognix Render"/>
                                       </div>
                                     )}
                                     {typeof part.text === 'string' && part.text && (
                                        <div className="whitespace-pre-wrap font-medium tracking-tight">{part.text}</div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex gap-4 items-center opacity-40">
                    <div className="w-10 h-10 rounded-full bg-black dark:bg-white flex items-center justify-center animate-pulse"><BotIcon className="w-5 h-5 text-white dark:text-black"/></div>
                    <div className="flex gap-2">
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
            </div>
        )}
      </div>

      {/* The Neural Dock - Floating Input */}
      <div className="fixed bottom-0 left-0 right-0 p-4 sm:p-8 lg:pl-[300px] pointer-events-none z-50 safe-pb">
          <div className="max-w-3xl mx-auto pointer-events-auto">
              <div className="glass rounded-[2.5rem] border border-slate-200/50 dark:border-white/10 p-3 shadow-2xl shadow-black/10 dark:shadow-white/5 flex flex-col gap-2">

                   {/* Preview Area */}
                   {selectedImage && (
                      <div className="px-3 pt-2 animate-spring-up flex items-center gap-3">
                          <div className="relative w-16 h-16 rounded-2xl overflow-hidden border border-white/20 shadow-xl group">
                              <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="Upload"/>
                              <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center text-xs font-bold transition-opacity group-hover:opacity-100">✕</button>
                          </div>
                          <div className="flex flex-col">
                              <span className="text-[10px] font-bold text-brand-500 uppercase tracking-widest">Image Loaded</span>
                              <span className="text-[9px] text-slate-400 font-mono">Ready for multimodal analysis</span>
                          </div>
                      </div>
                   )}

                   <div className="flex items-center gap-2">
                        <button onClick={() => fileInputRef.current?.click()} className="w-12 h-12 flex items-center justify-center text-slate-400 hover:text-black dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5 rounded-full transition-all active:scale-90">
                            <ImageIcon className="w-6 h-6"/>
                            <input type="file" ref={fileInputRef} onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                    const reader = new FileReader();
                                    reader.onloadend = () => setSelectedImage({ data: (reader.result as string).split(',')[1], mimeType: file.type });
                                    reader.readAsDataURL(file);
                                }
                            }} accept="image/*" className="hidden" />
                        </button>

                        <textarea ref={textareaRef} value={input} onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                            placeholder="Send a command..."
                            className="flex-1 bg-transparent border-none outline-none resize-none py-3.5 px-2 text-base text-slate-800 dark:text-white placeholder-slate-400 dark:placeholder-slate-600 font-medium max-h-40 min-h-[50px] custom-scrollbar"
                            rows={1} />

                        <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                          className="w-12 h-12 shrink-0 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center disabled:opacity-10 active:scale-90 transition-all shadow-xl">
                             <SendIcon className="w-6 h-6"/>
                        </button>
                   </div>

