import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, ThemeColors, Friend } from '../types';
import { BotIcon, TrashIcon, PencilIcon, MicrophoneIcon, UsersIcon, CodeIcon, SparklesIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  isSidebarOpen: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, onDeleteChat, onRenameChat, isSidebarOpen,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => (
    <button
        onClick={() => onSetMode(m)}
        className={`w-full flex items-center gap-4 px-5 py-3 rounded-2xl transition-all duration-300
            ${mode === m 
                ? 'bg-slate-100 dark:bg-white/10 text-black dark:text-white font-bold shadow-sm scale-[1.02]' 
                : 'text-slate-500 hover:text-black dark:hover:text-white hover:bg-slate-50 dark:hover:bg-white/5'}
        `}
    >
        <span className="shrink-0">{icon}</span>
        <span className="text-[13px] font-semibold tracking-tight">{label}</span>
    </button>
  );

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-40 lg:hidden transition-all duration-500" onClick={() => onSetMode(mode)}></div>
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-50 transition-all duration-500 ease-out h-full shrink-0 flex flex-col bg-white dark:bg-[#050505] border-r border-slate-100 dark:border-white/5 shadow-2xl lg:shadow-none
        ${isSidebarOpen ? 'translate-x-0 w-[280px]' : '-translate-x-full lg:translate-x-0 lg:w-[280px]'}
      `}>
        <div className="p-8">
          <div className="flex items-center gap-4 mb-12 cursor-pointer group" onClick={() => onSetMode('chat')}>
              <BotIcon className="w-10 h-10 transition-transform duration-500 group-hover:rotate-12 dark:invert" />
              <div className="flex flex-col">
                  <h1 className="text-xl font-black tracking-tighter leading-none">COGNIX</h1>
                  <span className="text-[9px] font-black text-brand-500 uppercase tracking-widest mt-1">Intelligence</span>
