          </div>

          <button onClick={onNewChat} className="w-full flex items-center justify-center py-4 bg-black dark:bg-white text-white dark:text-black rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl hover:opacity-90">
            Initialise New
