        </div>

        <nav className="px-4 space-y-2 mb-8">
          <NavItem m="chat" icon={<SparklesIcon className="w-5 h-5" />} label="Neural Core" />
          <NavItem m="coding" icon={<CodeIcon className="w-5 h-5" />} label="Dev Studio" />
          <NavItem m="live" icon={<MicrophoneIcon className="w-5 h-5" />} label="Voice Stream" />
          <NavItem m="community" icon={<UsersIcon className="w-5 h-5" />} label="Neural Hub" />
        </nav>

        <div className="flex-1 overflow-y-auto px-4 pb-8 custom-scrollbar">
              <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-widest px-5 mb-4">Pulse History</h3>
              <div className="space-y-1">
                  {chatHistory.map((chat) => (
                      <div key={chat.id} onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                          className={`group relative flex items-center justify-between px-5 py-3 cursor-pointer rounded-xl transition-all duration-300
                          ${activeChatId === chat.id && mode === 'chat'
                              ? 'bg-slate-50 dark:bg-white/5 text-black dark:text-white font-bold'
                              : 'text-slate-500 hover:text-black dark:hover:text-white'}
                          `}
                      >
                          {editingChatId === chat.id ? (
                              <input ref={inputRef} type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onBlur={handleRename} onKeyDown={(e) => e.key === 'Enter' && handleRename()}
                                  className="bg-transparent border-none w-full outline-none text-xs font-bold" />
                          ) : (
                              <>
                              <span className="truncate text-xs tracking-tight">{chat.title}</span>
                              <div className="hidden group-hover:flex items-center gap-1">
                                  <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 hover:text-brand-500 transition-colors"><PencilIcon className="w-3.5 h-3.5"/></button>
                                  <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 hover:text-red-500 transition-colors"><TrashIcon className="w-3.5 h-3.5"/></button>
                              </div>
                              </>
                          )}
                      </div>
                  ))}
              </div>
        </div>

        <div className="p-8 border-t border-slate-100 dark:border-white/5">
            <div className="flex items-center justify-center gap-2 text-[9px] font-black text-slate-400 uppercase tracking-widest">
              <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
              Neural Link Encrypted
            </div>
        </div>
      </aside>
    </>
  );
};

