  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_history_v2');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
    const savedTheme = localStorage.getItem('cognix_theme_v2');
    if (savedTheme === 'dark') { setIsDarkMode(true); document.documentElement.classList.add('dark'); }
  }, []);

  useEffect(() => localStorage.setItem('cognix_history_v2', JSON.stringify(chatHistory)), [chatHistory]);

  useEffect(() => {
    if (isDarkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('cognix_theme_v2', 'dark'); }
    else { document.documentElement.classList.remove('dark'); localStorage.setItem('cognix_theme_v2', 'light'); }
