             <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(true)} 
                  className="p-2 -ml-2 text-slate-400 hover:text-black dark:hover:text-white transition-all lg:hidden"
                >
                    <MenuIcon className="w-6 h-6"/>
                </button>
                <div className="flex flex-col">
                  <h1 className="text-[10px] font-black tracking-[0.4em] uppercase text-brand-500">
                      {mode} Mode
