             <div className="flex items-center gap-3">
                 <button 
                  onClick={() => setIsSettingsOpen(true)} 
                  className="w-10 h-10 flex items-center justify-center text-slate-400 hover:text-black dark:hover:text-white bg-slate-100 dark:bg-white/5 rounded-full transition-all"
                 >
                    <UserIcon className="w-5 h-5"/>
                 </button>
             </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
            {mode === 'chat' && (
                <ChatView messages={messages} setMessages={setMessages} theme={activeTheme} systemInstruction={systemInstruction} model={activeModel} setActiveModel={setActiveModel} />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
            {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
            {mode === 'community' && <CommunityView theme={activeTheme} model={activeModel} />}
            {mode === 'coding' && <CodingView theme={activeTheme} model={activeModel} />}
            {mode === 'memory' && <MemoryView theme={activeTheme} />}
            {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle={'modern'} setUiStyle={() => {}} 
        accentColor={accentColor} setAccentColor={setAccentColor} 
        fontSize={'normal'} setFontSize={() => {}} 
        isDarkMode={isDarkMode} setIsDarkMode={setIsDarkMode} 
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }} 
        systemInstruction={systemInstruction} setSystemInstruction={setSystemInstruction} 
      />
    </div>
  );
}

export default App;

