import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    if ((!input.trim() && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (input.trim()) parts.push({ text: input.trim() });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(input);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { systemInstruction }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => 
        p.text ? { text: p.text } : { inlineData: { mimeType: p.inlineData!.mimeType, data: p.inlineData!.data } }
      ) || [{ text: "System parity maintained. No output." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Engine Fault. Re-establish neural link." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, setMessages]);

  return (
    <div className="h-full flex flex-col">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-24 lg:px-48 pb-40 pt-4 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-spring">
             <div className="w-24 h-24 relative mb-12">
                <div className="absolute inset-0 bg-white/20 rounded-full blur-3xl animate-pulse-fast"></div>
                <BotIcon className="w-full h-full relative brightness-200" />
             </div>
             <h2 className="text-4xl font-black tracking-[-0.05em] mb-4">COGNIX</h2>
             <p className="text-white/30 text-[10px] font-mono tracking-[0.5em] uppercase">Neural Engine Online</p>
          </div>
        ) : (
          <div className="max-w-2xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-spring`}>
                <div className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center shadow-2xl ${m.role === 'user' ? 'bg-white text-black' : 'void-glass text-white'}`}>
                   {m.role === 'user' ? 'U' : 'C'}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-6 py-4 text-sm leading-relaxed ${m.role === 'user' ? 'msg-user' : 'msg-bot'}`}>
                      {p.inlineData && (
                        <img 
                          src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} 
                          className="rounded-xl mb-4 max-h-80 w-auto shadow-2xl border border-white/10" 
                          alt="Render" 
                        />
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-medium">{p.text}</div>}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 items-center opacity-30 animate-pulse">
                <div className="w-10 h-10 rounded-full void-glass flex items-center justify-center">C</div>
                <div className="flex gap-2">
                   <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                   <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                   <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="fixed bottom-10 left-0 right-0 px-6 sm:px-12 z-50 pointer-events-none">
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="void-glass neural-dock rounded-[2.5rem] p-3 shadow-2xl flex flex-col gap-1">

             {selectedImage && (
               <div className="px-4 pt-2 pb-2 flex items-center gap-4">
                  <div className="relative w-12 h-12 rounded-xl overflow-hidden border border-white/20">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center text-xs">✕</button>
                  </div>
                  <div className="text-[10px] font-bold text-accent uppercase tracking-widest">Multimodal Locked</div>
               </div>
             )}

             <div className="flex items-end gap-2 px-1">
                <button 
                  onClick={() => fileRef.current?.click()}
                  className="w-12 h-12 flex items-center justify-center text-white/30 hover:text-white hover:bg-white/5 rounded-full transition-all"
                >
                  <ImageIcon className="w-5 h-5" />
                  <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) {
                      const r = new FileReader();
                      r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                      r.readAsDataURL(f);
                    }
                  }} />
                </button>

                <textarea 
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Enter Command..."
                  className="flex-1 bg-transparent border-none outline-none resize-none py-3.5 px-3 text-base text-white placeholder-white/20 font-medium max-h-40 min-h-[52px]"
                  rows={1}
                />

                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className="w-12 h-12 shrink-0 bg-white text-black rounded-full flex items-center justify-center disabled:opacity-5 active:scale-90 transition-all"
                >
                  <SendIcon className="w-5 h-5" />
                </button>
             </div>

             <div className="flex items-center justify-between px-6 pb-2 pt-1 border-t border-white/5">
                <button 
                   onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                   className="text-[8px] font-black uppercase tracking-[0.3em] text-white/30 hover:text-white transition-all"
                >
                   {model.includes('pro') ? 'Core: Pro' : 'Core: Flash'}
                </button>
                <div className="flex gap-4">
                  <span className="text-[8px] font-mono text-white/10 uppercase tracking-widest">Secure Link 4.1</span>
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500/50 mt-1"></div>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

