    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-xl z-[60] lg:hidden" onClick={onClose} />
      )}
      <aside className={`fixed inset-y-0 left-0 z-[70] transition-all duration-500 ease-out h-full void-glass border-r-0 lg:border-r border-white/5
        ${isSidebarOpen ? 'translate-x-0 w-[320px]' : '-translate-x-full lg:translate-x-0 lg:w-[280px]'}
      `}>
        <div className="p-10 flex flex-col h-full">
           <div className="flex items-center gap-4 mb-16 select-none">
              <BotIcon className="w-10 h-10 brightness-200" />
              <div className="flex flex-col">
                 <h2 className="text-xl font-black tracking-tighter leading-none">COGNIX</h2>
                 <span className="text-[8px] font-black uppercase tracking-[0.4em] text-white/20 mt-1">Synthetic Agent</span>
              </div>
           </div>

           <button 
             onClick={onNewChat}
             className="w-full flex items-center justify-center py-4 bg-white text-black rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-2xl hover:bg-white/90 mb-12"
