import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    if ((!input.trim() && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (input.trim()) parts.push({ text: input.trim() });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(input);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { systemInstruction }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => 
        p.text ? { text: p.text } : { inlineData: { mimeType: p.inlineData!.mimeType, data: p.inlineData!.data } }
      ) || [{ text: "Analysis complete." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Link error. Please retry." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, setMessages]);

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-300">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-24 pb-48 pt-8 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-fade-in">
             <div className="w-20 h-20 mb-6 text-cognix-500">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight mb-2">CognixAI</h2>
             <p className="text-slate-500 dark:text-slate-400 text-sm max-w-sm font-medium">How can I assist your workflow today?</p>
             <div className="grid grid-cols-2 gap-3 mt-10 max-w-md mx-auto">
                {[
                  { icon: <SparklesIcon className="w-4 h-4"/>, label: 'Generate UI Concept' },
                  { icon: <ImageIcon className="w-4 h-4"/>, label: 'Create App Icon' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-xs font-bold text-slate-600 dark:text-slate-300 hover:border-cognix-500 transition-all flex items-center justify-center gap-2">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-fade-in`}>
                <div className={`w-9 h-9 shrink-0 rounded-full flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-cognix-500 text-white' : 'bg-slate-100 dark:bg-slate-800 text-cognix-500'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3.5 text-sm leading-relaxed ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-xl overflow-hidden shadow-sm bg-slate-200 dark:bg-slate-700">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-96 w-auto object-contain" alt="Render" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-medium">{p.text}</div>}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 items-center animate-pulse">
                <div className="w-9 h-9 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-cognix-500"><BotIcon className="w-6 h-6"/></div>
                <div className="flex gap-1.5 px-1">
                   <div className="w-1.5 h-1.5 bg-cognix-500 rounded-full"></div>
                   <div className="w-1.5 h-1.5 bg-cognix-500 rounded-full opacity-50"></div>
                   <div className="w-1.5 h-1.5 bg-cognix-500 rounded-full opacity-25"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 sm:p-6 lg:pl-72 bg-gradient-to-t from-white dark:from-slate-900 via-white dark:via-slate-900 to-transparent z-40 safe-pb">
        <div className="max-w-3xl mx-auto">
          <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 p-2 shadow-2xl shadow-cognix-500/5 flex flex-col gap-2">

             {selectedImage && (
               <div className="px-3 pt-2 pb-1 flex items-center gap-3">
                  <div className="relative w-14 h-14 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-600 shadow-sm">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute top-1 right-1 bg-black/60 text-white rounded-full w-5 h-5 flex items-center justify-center text-[10px]">✕</button>
                  </div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-cognix-500">Image Loaded</span>
               </div>
             )}

             <div className="flex items-end gap-1">
                <button 
                  onClick={() => fileRef.current?.click()}
                  className="p-3 text-slate-400 hover:text-cognix-500 transition-all rounded-full hover:bg-slate-100 dark:hover:bg-slate-700"
                >
                  <ImageIcon className="w-5 h-5" />
                  <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) {
                      const r = new FileReader();
                      r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                      r.readAsDataURL(f);
                    }
                  }} />
                </button>

                <textarea 
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Type your instruction..."
                  className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-2 text-[15px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-40 min-h-[48px]"
                  rows={1}
                />

                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className="w-12 h-12 shrink-0 bg-cognix-500 text-white rounded-2xl flex items-center justify-center disabled:opacity-20 active:scale-95 transition-all shadow-lg shadow-cognix-500/20"
                >
                  <SendIcon className="w-5 h-5" />
                </button>
             </div>

             <div className="flex items-center justify-between px-4 pb-1 border-t border-slate-50 dark:border-slate-700/50 pt-1.5">
                <button 
                   onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                   className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-cognix-500 transition-all"
                >
                   Core: {model.includes('pro') ? 'Pro (Reasoning)' : 'Flash (Agile)'}
                </button>
                <div className="flex gap-3">
                  <span className="text-[9px] font-mono text-slate-300 dark:text-slate-600 uppercase tracking-widest">Cognix_OS_4.5</span>
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500 mt-1 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

