             className="w-full flex items-center justify-center py-4 bg-white dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 hover:bg-slate-50 dark:hover:bg-slate-700 mb-8 shadow-sm"
           >
             + New Neural Link
           </button>

           <nav className="space-y-1.5 mb-10">
              <NavItem m="chat" icon={<SparklesIcon className="w-5 h-5" />} label="Hub" />
              <NavItem m="community" icon={<UsersIcon className="w-5 h-5" />} label="Collective" />
              <NavItem m="friends" icon={<UsersIcon className="w-5 h-5" />} label="Cognates" />
              <NavItem m="coding" icon={<CodeIcon className="w-5 h-5" />} label="Studio" />
              <NavItem m="live" icon={<MicrophoneIcon className="w-5 h-5" />} label="LiveTalk" />
              <NavItem m="memory" icon={<BotIcon className="w-5 h-5" />} label="Vault" />
           </nav>

           <div className="flex-1 flex flex-col min-h-0">
              <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest px-6 mb-4">Neural Fragments</h3>
              <div className="flex-1 overflow-y-auto space-y-1 custom-scrollbar pr-2 pb-4">
                {chatHistory.length === 0 ? (
                  <div className="px-6 py-8 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-3xl">
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest leading-relaxed">Pulse Archive<br/>Empty</p>
                  </div>
                ) : (
                  chatHistory.map((chat) => (
                    <div key={chat.id} className="group relative">
                      <button 
                        onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                        className={`w-full text-left px-6 py-3.5 rounded-2xl transition-all flex items-center justify-between
                          ${activeChatId === chat.id && mode === 'chat' 
                            ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white font-bold' 
                            : 'text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800/50'}
                        `}
                      >
                        <span className="text-xs truncate w-full tracking-tight">{chat.title || 'Untitled Pulse'}</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }}
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-2 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all bg-white dark:bg-slate-800 rounded-lg shadow-sm"
                      >
                        <TrashIcon className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  ))
                )}
              </div>
           </div>

           <div className="pt-6 border-t border-slate-100 dark:border-slate-800 mt-auto">
              <div className="flex items-center gap-3 px-2">
                <div className="w-2.5 h-2.5 rounded-full bg-green-500 animate-pulse shadow-[0_0_10px_rgba(34,197,94,0.5)]"></div>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Node Online & Secure</p>
              </div>
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => 
        p.text ? { text: p.text } : { inlineData: { mimeType: p.inlineData!.mimeType, data: p.inlineData!.data } }
      ) || [{ text: "Neural link established. Protocol complete." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural Uplink Interrupted. Re-sync necessary for secure communication." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 dark:bg-slate-900 transition-colors duration-500">
      {/* Dynamic Header */}
      <div className="hidden lg:flex items-center justify-between px-10 py-5 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md border-b border-slate-100 dark:border-slate-800 sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Hub</span>
          <span className="text-slate-200 dark:text-slate-800">/</span>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-cognix-500">Cognix.V3.Pro</span>
          <div className="w-2 h-2 rounded-full bg-cognix-500 animate-pulse ml-1"></div>
        </div>
      </div>

      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-12 lg:px-24 xl:px-48 pb-56 pt-10 scroll-smooth custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-xl mx-auto">
             <div className="w-24 h-24 mb-8 text-cognix-500 p-5 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-cognix-500/10">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tight mb-4 uppercase">Cognix Intelligence</h2>
             <p className="text-slate-500 dark:text-slate-400 text-base font-medium leading-relaxed">
               Welcome back. Your neural node is active. I'm ready to architect logic, visualize concepts, or assist in complex analysis.
             </p>
             <div className="flex flex-wrap justify-center gap-3 mt-12">
                {[
                  { icon: <SparklesIcon className="w-4 h-4"/>, label: 'Design a high-end dashboard' },
                  { icon: <CodeIcon className="w-4 h-4"/>, label: 'Debug this React component' },
                  { icon: <ImageIcon className="w-4 h-4"/>, label: 'Create a neon cityscape icon' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-5 py-3 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[11px] font-black uppercase tracking-wider text-slate-600 dark:text-slate-300 hover:border-cognix-500 hover:shadow-lg transition-all flex items-center gap-3">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-5 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-md transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-white text-slate-400' : 'bg-cognix-500 text-white'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[88%] lg:max-w-[80%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-sm sm:text-base leading-relaxed ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden shadow-2xl bg-black/5 group relative">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain transition-transform duration-700 hover:scale-[1.02]" alt="Cognix Render" />
                          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-medium tracking-tight text-slate-800 dark:text-slate-100">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/50">
                        <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">Consulting Live Web Nodes</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-5 items-center animate-pulse">
                <div className="w-10 h-10 rounded-2xl bg-cognix-500 flex items-center justify-center text-white"><BotIcon className="w-6 h-6"/></div>
                <div className="flex gap-2 px-2">
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Floating Neural Dock */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="glass border border-white/50 dark:border-slate-800 rounded-[2.5rem] p-3 shadow-premium transition-all duration-500">

             {/* Preview Area */}
             {selectedImage && (
               <div className="px-4 py-3 flex items-center gap-4 animate-slide-up">
                  <div className="relative w-16 h-16 rounded-2xl overflow-hidden border-2 border-cognix-500/50 shadow-lg group">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                        <span className="text-xs font-black">✕</span>
                     </button>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[11px] font-black uppercase tracking-widest text-cognix-500">Visual Context Loaded</span>
                    <span className="text-[9px] text-slate-400 font-mono">multimodal_enabled: true</span>
                  </div>
               </div>
             )}

             <div className="flex flex-col gap-2">
                {/* Controls Bar */}
                <div className="flex items-center justify-between px-4 py-1.5 border-b border-slate-100 dark:border-slate-800/50 mb-1">
                   <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                        className="flex items-center gap-2 group"
                      >
                         <span className="text-[10px] font-black uppercase tracking-[0.1em] text-slate-400 group-hover:text-cognix-500 transition-colors">
                           {model.includes('pro') ? 'Gemini 3.0 Pro' : 'Gemini 3.0 Flash'}
                         </span>
                         <svg className="w-3 h-3 text-slate-300 group-hover:text-cognix-500 transition-colors" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                      </button>
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 group px-2 py-1 rounded-lg transition-all ${isSearchEnabled ? 'bg-cognix-50 dark:bg-cognix-900/20' : ''}`}
                      >
                         <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-cognix-500 shadow-[0_0_8px_rgba(14,165,233,0.5)]' : 'bg-slate-300'}`}></div>
                         <span className={`text-[10px] font-black uppercase tracking-[0.1em] transition-colors ${isSearchEnabled ? 'text-cognix-500' : 'text-slate-400 group-hover:text-slate-600'}`}>Neural Search</span>
                      </button>
                      <button className="flex items-center gap-2 group px-2 py-1 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 transition-all">
                         <UsersIcon className="w-3.5 h-3.5 text-slate-400 group-hover:text-slate-600" />
                         <span className="text-[10px] font-black uppercase tracking-[0.1em] text-slate-400 group-hover:text-slate-600">Invite People</span>
                      </button>
                   </div>
                </div>

                {/* Input Area */}
                <div className="flex items-end gap-3 px-1">
                   <button 
                     onClick={() => fileRef.current?.click()}
                     className="w-14 h-14 shrink-0 flex items-center justify-center bg-slate-50 dark:bg-slate-800/50 text-slate-400 hover:text-cognix-500 hover:bg-cognix-50 dark:hover:bg-cognix-900/20 rounded-[1.5rem] transition-all group"
                   >
                     <ImageIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                     <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) {
                         const r = new FileReader();
                         r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                         r.readAsDataURL(f);
                       }
                     }} />
                   </button>

                   <div className="flex-1 relative flex items-center">
                     <textarea 
                       ref={textareaRef}
                       value={input}
                       onChange={onTextChange}
                       onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                       placeholder="Ask Cognix anything..."
                       className="w-full bg-transparent border-none outline-none resize-none py-4 px-4 text-base text-slate-800 dark:text-slate-100 placeholder-slate-400 font-semibold max-h-[300px] min-h-[56px] leading-relaxed"
                       rows={1}
                     />
                   </div>

                   <button 
                     onClick={handleSend}
                     disabled={isLoading || (!input.trim() && !selectedImage)}
                     className="w-14 h-14 shrink-0 bg-cognix-500 text-white rounded-[1.5rem] flex items-center justify-center disabled:opacity-20 active:scale-95 transition-all shadow-xl shadow-cognix-500/20 hover:bg-cognix-600 group"
                   >
                     <SendIcon className="w-6 h-6 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                   </button>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-cognix-500',
    primaryHover: 'hover:bg-cognix-600',
    text: 'text-cognix-600',
    textDark: 'text-cognix-400',
    bgSoft: 'bg-cognix-50',
    darkBgSoft: 'dark:bg-cognix-900/20',
    border: 'border-cognix-200 dark:border-cognix-800',
    ring: 'focus:ring-cognix-500',
    gradient: 'bg-gradient-to-r from-cognix-500 to-blue-600'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are COGNIX, an elite digital intelligence with a sleek, minimalist soul. You provide precision engineering logic, high-fidelity creative outputs, and absolute clarity. Maintain a professional, crisp, and high-performance persona.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v6_history');
    if (saved) setChatHistory(JSON.parse(saved));
    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v6_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Pulse';
        setChatHistory([{ id: newId, title, messages: next }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  return (
    <div className="h-full w-full flex bg-slate-50 dark:bg-slate-950 transition-colors duration-500 overflow-hidden">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden transition-all duration-500">
        {/* Mobile-First Header */}
        <header className="h-16 lg:hidden flex items-center justify-between px-6 z-50 glass border-b border-slate-100 dark:border-slate-800">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 hover:text-cognix-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="flex items-center gap-2">
              <BotIcon className="w-6 h-6 text-cognix-500" />
              <h1 className="text-sm font-black tracking-tight uppercase">CognixAI</h1>
            </div>
          </div>

          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="w-10 h-10 flex items-center justify-center bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-500 transition-all active:scale-90"
          >
            <UserIcon className="w-5 h-5" />
          </button>
        </header>

        {/* Dynamic Nav Indicator for Desktop Header */}
        <div className="hidden lg:flex absolute top-5 right-10 z-50 items-center gap-3">
           <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-12 h-12 flex items-center justify-center glass rounded-[1.25rem] text-slate-400 hover:text-cognix-500 hover:scale-110 transition-all shadow-xl shadow-black/5"
           >
              <UserIcon className="w-5 h-5" />
           </button>
        </div>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'memory' && <MemoryView theme={THEME} />}
           {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v6_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
// Fixed: Added missing imports for CodeIcon and UsersIcon.
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      // Create a new instance right before making an API call to ensure it uses the most up-to-date API key.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      // Fixed: Extract generated parts correctly and handle search grounding chunks for URLs.
      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Neural link established. Protocol complete." }];

      // Extract search grounding metadata if available and search is enabled.
      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');

          if (links) {
            resParts.push({ text: `\n\n**Sources:**\n${links}` });
          }
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural Uplink Interrupted. Re-sync necessary for secure communication." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 dark:bg-slate-900 transition-colors duration-500">
      {/* Dynamic Header */}
      <div className="hidden lg:flex items-center justify-between px-10 py-5 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md border-b border-slate-100 dark:border-slate-800 sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Hub</span>
          <span className="text-slate-200 dark:text-slate-800">/</span>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-cognix-500">Cognix.V3.Pro</span>
          <div className="w-2 h-2 rounded-full bg-cognix-500 animate-pulse ml-1"></div>
        </div>
      </div>

      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-12 lg:px-24 xl:px-48 pb-56 pt-10 scroll-smooth custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-xl mx-auto">
             <div className="w-24 h-24 mb-8 text-cognix-500 p-5 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-cognix-500/10">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tight mb-4 uppercase">Cognix Intelligence</h2>
             <p className="text-slate-500 dark:text-slate-400 text-base font-medium leading-relaxed">
               Welcome back. Your neural node is active. I'm ready to architect logic, visualize concepts, or assist in complex analysis.
             </p>
             <div className="flex flex-wrap justify-center gap-3 mt-12">
                {[
                  { icon: <SparklesIcon className="w-4 h-4"/>, label: 'Design a high-end dashboard' },
                  { icon: <CodeIcon className="w-4 h-4"/>, label: 'Debug this React component' },
                  { icon: <ImageIcon className="w-4 h-4"/>, label: 'Create a neon cityscape icon' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-5 py-3 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[11px] font-black uppercase tracking-wider text-slate-600 dark:text-slate-300 hover:border-cognix-500 hover:shadow-lg transition-all flex items-center gap-3">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-5 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-md transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-white text-slate-400' : 'bg-cognix-500 text-white'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[88%] lg:max-w-[80%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-sm sm:text-base leading-relaxed ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden shadow-2xl bg-black/5 group relative">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain transition-transform duration-700 hover:scale-[1.02]" alt="Cognix Render" />
                          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-medium tracking-tight text-slate-800 dark:text-slate-100">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/50">
                        <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">Consulting Live Web Nodes</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-5 items-center animate-pulse">
                <div className="w-10 h-10 rounded-2xl bg-cognix-500 flex items-center justify-center text-white"><BotIcon className="w-6 h-6"/></div>
                <div className="flex gap-2 px-2">
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Floating Neural Dock */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="glass border border-white/50 dark:border-slate-800 rounded-[2.5rem] p-3 shadow-premium transition-all duration-500">

             {/* Preview Area */}
             {selectedImage && (
               <div className="px-4 py-3 flex items-center gap-4 animate-slide-up">
                  <div className="relative w-16 h-16 rounded-2xl overflow-hidden border-2 border-cognix-500/50 shadow-lg group">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                        <span className="text-xs font-black">✕</span>
                     </button>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[11px] font-black uppercase tracking-widest text-cognix-500">Visual Context Loaded</span>
                    <span className="text-[9px] text-slate-400 font-mono">multimodal_enabled: true</span>
                  </div>
               </div>
             )}

             <div className="flex flex-col gap-2">
                {/* Controls Bar */}
                <div className="flex items-center justify-between px-4 py-1.5 border-b border-slate-100 dark:border-slate-800/50 mb-1">
                   <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                        className="flex items-center gap-2 group"
                      >
                         <span className="text-[10px] font-black uppercase tracking-[0.1em] text-slate-400 group-hover:text-cognix-500 transition-colors">
                           {model.includes('pro') ? 'Gemini 3.0 Pro' : 'Gemini 3.0 Flash'}
                         </span>
                         <svg className="w-3 h-3 text-slate-300 group-hover:text-cognix-500 transition-colors" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                      </button>
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 group px-2 py-1 rounded-lg transition-all ${isSearchEnabled ? 'bg-cognix-50 dark:bg-cognix-900/20' : ''}`}
                      >
                         <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-cognix-500 shadow-[0_0_8px_rgba(14,165,233,0.5)]' : 'bg-slate-300'}`}></div>
                         <span className={`text-[10px] font-black uppercase tracking-[0.1em] transition-colors ${isSearchEnabled ? 'text-cognix-500' : 'text-slate-400 group-hover:text-slate-600'}`}>Neural Search</span>
                      </button>
                      <button className="flex items-center gap-2 group px-2 py-1 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 transition-all">
                         <UsersIcon className="w-3.5 h-3.5 text-slate-400 group-hover:text-slate-600" />
                         <span className="text-[10px] font-black uppercase tracking-[0.1em] text-slate-400 group-hover:text-slate-600">Invite People</span>
                      </button>
                   </div>
                </div>

                {/* Input Area */}
                <div className="flex items-end gap-3 px-1">
                   <button 
                     onClick={() => fileRef.current?.click()}
                     className="w-14 h-14 shrink-0 flex items-center justify-center bg-slate-50 dark:bg-slate-800/50 text-slate-400 hover:text-cognix-500 hover:bg-cognix-50 dark:hover:bg-cognix-900/20 rounded-[1.5rem] transition-all group"
                   >
                     <ImageIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                     <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) {
                         const r = new FileReader();
                         r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                         r.readAsDataURL(f);
                       }
                     }} />
                   </button>

                   <div className="flex-1 relative flex items-center">
                     <textarea 
                       ref={textareaRef}
                       value={input}
                       onChange={onTextChange}
                       onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                       placeholder="Ask Cognix anything..."
                       className="w-full bg-transparent border-none outline-none resize-none py-4 px-4 text-base text-slate-800 dark:text-slate-100 placeholder-slate-400 font-semibold max-h-[300px] min-h-[56px] leading-relaxed"
                       rows={1}
                     />
                   </div>

                   <button 
