import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Analysis confirmed." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural uplink interrupted. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-20 lg:px-32 xl:px-48 pb-64 pt-10 scroll-smooth custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-xl mx-auto">
             <div className="w-20 h-20 mb-10 text-slate-900 dark:text-white p-5 bg-slate-50 dark:bg-slate-800 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter mb-4 uppercase">Neural Hub</h2>
             <p className="text-slate-500 dark:text-slate-400 text-sm font-medium leading-relaxed mb-12">
               How can I assist your workflow today? I'm optimized for precision logic and advanced multimodal analysis.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-lg">
                {[
                  { icon: <SparklesIcon className="w-4 h-4"/>, label: 'Design landing page architecture' },
                  { icon: <CodeIcon className="w-4 h-4"/>, label: 'Debug authentication logic' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-6 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 hover:border-slate-900 dark:hover:border-white transition-all flex items-center gap-3">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-6 h-6"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-sm sm:text-base leading-relaxed ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-2xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Render" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-medium tracking-tight">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black uppercase tracking-widest text-slate-600">Consulting external nodes</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 items-center animate-pulse">
                <div className="w-10 h-10 rounded-xl bg-slate-900 flex items-center justify-center text-white"><BotIcon className="w-6 h-6"/></div>
                <div className="flex gap-1.5 px-2">
                   <div className="w-1.5 h-1.5 bg-slate-900 rounded-full"></div>
                   <div className="w-1.5 h-1.5 bg-slate-900 rounded-full opacity-50"></div>
                   <div className="w-1.5 h-1.5 bg-slate-900 rounded-full opacity-20"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Floating Neural Dock */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-3xl p-3 shadow-premium transition-all">
             {selectedImage && (
               <div className="px-4 py-3 flex items-center gap-4 animate-slide-up border-b border-slate-50 dark:border-slate-700/50 mb-2">
                  <div className="relative w-14 h-14 rounded-xl overflow-hidden border border-slate-200 shadow-sm group">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">✕</button>
                  </div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Multimodal attachment locked</span>
               </div>
             )}

             <div className="flex flex-col gap-2">
                <div className="flex items-end gap-2 px-1">
                   <button 
                     onClick={() => fileRef.current?.click()}
                     className="w-12 h-12 shrink-0 flex items-center justify-center bg-slate-50 dark:bg-slate-700 text-slate-400 hover:text-slate-900 transition-all rounded-xl"
                   >
                     <ImageIcon className="w-5 h-5" />
                     <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) {
                         const r = new FileReader();
                         r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                         r.readAsDataURL(f);
                       }
                     }} />
                   </button>

                   <textarea 
                     ref={textareaRef}
                     value={input}
                     onChange={onTextChange}
                     onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                     placeholder="Type your command..."
                     className="flex-1 bg-transparent border-none outline-none resize-none py-3.5 px-3 text-sm sm:text-base text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[250px] min-h-[48px] leading-relaxed"
                     rows={1}
                   />

                   <button 
                     onClick={handleSend}
                     disabled={isLoading || (!input.trim() && !selectedImage)}
                     className="w-12 h-12 shrink-0 bg-slate-900 text-white rounded-xl flex items-center justify-center disabled:opacity-20 active:scale-95 transition-all shadow-lg"
                   >
                     <SendIcon className="w-5 h-5" />
                   </button>
                </div>

                <div className="flex items-center justify-between px-4 pb-1 border-t border-slate-50 dark:border-slate-700/50 pt-2 mt-1">
                   <div className="flex items-center gap-4">
                      <button 
                        onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                        className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors"
                      >
                         Engine: {model.includes('pro') ? 'Pro (High Logic)' : 'Flash (Agile)'}
                      </button>
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1.5 px-2 py-0.5 rounded transition-all ${isSearchEnabled ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:text-slate-900'}`}
                      >
                         <div className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-sm' : 'bg-slate-300'}`}></div>
                         <span className="text-[9px] font-black uppercase tracking-widest">Neural Search</span>
                      </button>
                   </div>
                   <div className="flex gap-3">
                      <span className="text-[9px] font-mono text-slate-300 dark:text-slate-600 uppercase tracking-widest">Node_Pulse_7.1</span>
                      <div className="w-1.5 h-1.5 rounded-full bg-green-500 mt-0.5"></div>
                   </div>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

