import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Neural handshake confirmed." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Neural Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural uplink interrupted. Protocol reset recommended." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-20 lg:px-32 xl:px-48 pb-64 pt-12 scroll-smooth custom-scrollbar">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-xl mx-auto">
             <div className="w-24 h-24 mb-10 text-cognix-500 p-6 bg-cognix-50 dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-cognix-500/10 border border-cognix-100 dark:border-slate-800 transition-transform hover:scale-105">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter mb-4 uppercase">Interface Hub</h2>
             <p className="text-slate-500 dark:text-slate-400 text-base font-medium leading-relaxed mb-12">
               Welcome to your neural core. Optimized for high-precision multimodal analysis and creative synthesis.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-cognix-500"/>, label: 'Design app architecture' },
                  { icon: <CodeIcon className="w-4 h-4 text-cognix-500"/>, label: 'Debug logic stream' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-6 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[11px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 hover:border-cognix-500 hover:shadow-lg transition-all flex items-center justify-center gap-3">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12 pb-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-11 h-11 shrink-0 rounded-2xl flex items-center justify-center shadow-md transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-white dark:bg-slate-800 text-slate-400' : 'bg-cognix-500 text-white shadow-cognix-500/20'}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-8 h-8"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-sm sm:text-base leading-relaxed ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-xl shadow-black/5">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Analysis" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap font-semibold tracking-tight leading-loose">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-cognix-50 dark:bg-cognix-900/20 rounded-full border border-cognix-100 dark:border-cognix-800/50">
                        <div className="w-1.5 h-1.5 bg-cognix-500 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-cognix-600">Syncing live web nodes</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 items-center animate-pulse">
                <div className="w-11 h-11 rounded-2xl bg-cognix-500 flex items-center justify-center text-white"><BotIcon className="w-8 h-8"/></div>
                <div className="flex gap-2 px-2">
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-cognix-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="bg-white/80 dark:bg-slate-800/80 backdrop-blur-2xl border border-white/50 dark:border-slate-700/50 rounded-[2.5rem] p-3 shadow-premium transition-all">
             {selectedImage && (
               <div className="px-4 py-4 flex items-center gap-4 animate-slide-up border-b border-slate-50 dark:border-slate-700/50 mb-3">
                  <div className="relative w-16 h-16 rounded-2xl overflow-hidden border-2 border-cognix-500 shadow-lg group">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">✕</button>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[11px] font-black uppercase tracking-widest text-cognix-600">Visual handshake active</span>
                    <span className="text-[9px] font-mono text-slate-400 mt-1 uppercase">Ready for analysis</span>
                  </div>
               </div>
             )}

             <div className="flex flex-col gap-2">
                <div className="flex items-end gap-3 px-1">
                   <button 
                     onClick={() => fileRef.current?.click()}
                     className="w-14 h-14 shrink-0 flex items-center justify-center bg-slate-50 dark:bg-slate-700 text-slate-400 hover:text-cognix-600 hover:bg-cognix-50 transition-all rounded-2xl group"
                   >
                     <ImageIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                     <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) {
                         const r = new FileReader();
                         r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                         r.readAsDataURL(f);
                       }
                     }} />
                   </button>

                   <textarea 
                     ref={textareaRef}
                     value={input}
                     onChange={onTextChange}
                     onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                     placeholder="Inject neural directive..."
                     className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-3 text-[15px] sm:text-base text-slate-800 dark:text-slate-100 placeholder-slate-400 font-bold max-h-[250px] min-h-[56px] leading-relaxed"
                     rows={1}
                   />

                   <button 
                     onClick={handleSend}
                     disabled={isLoading || (!input.trim() && !selectedImage)}
                     className="w-14 h-14 shrink-0 bg-cognix-500 text-white rounded-2xl flex items-center justify-center disabled:opacity-20 active:scale-95 transition-all shadow-xl shadow-cognix-500/20 hover:bg-cognix-600 group"
                   >
                     <SendIcon className="w-6 h-6 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                   </button>
                </div>

                <div className="flex items-center justify-between px-5 pb-1 border-t border-slate-50 dark:border-slate-700/50 pt-3 mt-1">
                   <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                        className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-cognix-600 transition-colors"
                      >
                         Engine: {model.includes('pro') ? 'Pro (High Logic)' : 'Flash (Agile)'}
                      </button>
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 px-3 py-1 rounded-lg transition-all ${isSearchEnabled ? 'bg-cognix-50 text-cognix-600' : 'text-slate-400 hover:text-slate-900'}`}
                      >
                         <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-cognix-500 shadow-[0_0_8px_rgba(14,165,233,0.5)]' : 'bg-slate-300'}`}></div>
                         <span className="text-[10px] font-black uppercase tracking-widest">Neural Search</span>
                      </button>
                   </div>
                   <div className="flex gap-4">
                      <span className="text-[9px] font-mono text-slate-300 dark:text-slate-600 uppercase tracking-widest">Cognix_Core_8.5</span>
                      <div className="w-1.5 h-1.5 rounded-full bg-green-500 mt-1 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>
                   </div>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

