import React from 'react';
import type { ChatSession, Mode } from '../types';
import { BotIcon, TrashIcon, SparklesIcon, CodeIcon, MicrophoneIcon, UsersIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  isSidebarOpen: boolean;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, onDeleteChat, isSidebarOpen, onClose 
}) => {

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => {
    const isActive = mode === m;
    return (
      <button
          onClick={() => { onSetMode(m); if(window.innerWidth < 1024) onClose(); }}
          className={`w-full flex items-center gap-3 px-3 py-2 rounded-xl transition-all duration-200 group
              ${isActive 
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-500/10' 
                  : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100 dark:text-slate-400 dark:hover:text-white dark:hover:bg-slate-800/60'}
          `}
      >
          <span className={`shrink-0 transition-transform ${isActive ? 'scale-100' : 'group-hover:scale-110 opacity-70 group-hover:opacity-100'}`}>
            {React.cloneElement(icon as React.ReactElement, { className: 'w-4 h-4' })}
          </span>
          <span className="text-[11px] font-bold tracking-tight uppercase">{label}</span>
      </button>
    );
  };

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] lg:hidden transition-opacity duration-300" onClick={onClose} />
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-500 cubic-bezier(0.16, 1, 0.3, 1) h-full w-[280px] bg-white dark:bg-[#0b0f1a] border-r border-slate-100 dark:border-slate-800/60 flex flex-col
        ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="p-6 flex flex-col h-full">
           {/* Logo Section */}
           <div className="flex items-center gap-3 mb-10 select-none group cursor-pointer px-1" onClick={onNewChat}>
              <BotIcon className="w-10 h-10 shadow-lg rounded-full transition-all group-hover:scale-105" />
              <div className="flex flex-col">
                 <h2 className="text-xl font-black tracking-tighter text-slate-900 dark:text-white leading-none uppercase italic">Cognix</h2>
                 <span className="text-[8px] font-black uppercase tracking-[0.3em] text-blue-600 mt-1.5 opacity-80">Intelligence Hub</span>
              </div>
           </div>

           {/* Core Navigation */}
           <div className="space-y-6 mb-10">
              <div>
                <h3 className="text-[9px] font-bold text-slate-400 uppercase tracking-widest px-3 mb-3">Workspaces</h3>
                <nav className="space-y-1">
                  <NavItem m="chat" icon={<SparklesIcon />} label="Neural Hub" />
                  <NavItem m="coding" icon={<CodeIcon />} label="Lab Studio" />
                  <NavItem m="live" icon={<MicrophoneIcon />} label="Live Link" />
                  <NavItem m="community" icon={<UsersIcon />} label="Collective" />
                </nav>
              </div>
           </div>

           {/* Action Section */}
           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className="w-full flex items-center justify-between px-5 py-3.5 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-[0.98] hover:bg-slate-800 dark:hover:bg-white mb-8 shadow-sm group"
           >
             <span>New Neural Pulse</span>
             <span className="opacity-40 group-hover:opacity-100 transition-opacity">⌘ N</span>
           </button>

           {/* History Section */}
           <div className="flex-1 flex flex-col min-h-0">
              <div className="flex items-center justify-between px-3 mb-4">
                <h3 className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Recent Fragments</h3>
                <div className="h-[1px] flex-1 bg-slate-100 dark:bg-slate-800 ml-4 opacity-50"></div>
              </div>
              <div className="flex-1 overflow-y-auto space-y-1 pr-2 -mr-2 scrollbar-hide pb-8">
                {chatHistory.length === 0 ? (
                  <div className="px-6 py-12 text-center border border-dashed border-slate-100 dark:border-slate-800 rounded-3xl opacity-50">
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest leading-relaxed">No Memory<br/>Nodes Detected</p>
                  </div>
                ) : (
                  chatHistory.map((chat) => (
                    <div key={chat.id} className="group relative px-1">
                      <button 
                        onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                        className={`w-full text-left px-4 py-3 rounded-xl transition-all flex items-center justify-between
                          ${activeChatId === chat.id && mode === 'chat' 
                            ? 'bg-slate-50 dark:bg-slate-800 text-blue-600 dark:text-blue-400 border-l-2 border-blue-600 pl-4' 
                            : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50/80 dark:hover:bg-slate-800/40'}
