import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-cognix-500',
    primaryHover: 'hover:bg-cognix-600',
    text: 'text-cognix-600',
    textDark: 'text-cognix-100',
    bgSoft: 'bg-cognix-50',
    darkBgSoft: 'dark:bg-cognix-900/40',
    border: 'border-cognix-200 dark:border-cognix-800',
    ring: 'focus:ring-cognix-500',
    gradient: 'bg-gradient-to-r from-cognix-500 to-cognix-600'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("You are COGNIX, an elite intelligence system. Your identity is defined by clarity, high-contrast professional design, and vibrant energy. You provide precise, authority-driven responses with maximum efficiency.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));
    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Link';
        setChatHistory([{ id: newId, title, messages: next }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Live Talk';
      case 'community': return 'Community';
      case 'friends': return 'Contacts';
      case 'memory': return 'Vault';
      case 'toolbox': return 'Tools';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="hidden lg:flex items-center gap-3">
              <BotIcon className="w-8 h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700"></div>
              <span className="text-sm font-bold text-slate-600 dark:text-slate-300">{getModeLabel(mode)}</span>
            </div>
            <div className="lg:hidden flex items-center gap-2">
              <BotIcon className="w-7 h-7" />
              <h1 className="text-sm font-bold tracking-tight">{getModeLabel(mode)}</h1>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'friends' && <FriendsView friends={friends} setFriends={setFriends} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'memory' && <MemoryView theme={THEME} />}
           {mode === 'about' && <AboutUs />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Analysis confirmed. Neural path established." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Neural Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural uplink interrupted. Protocol reset recommended." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-64 pt-12 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-2xl mx-auto">
             <div className="w-20 h-20 mb-8 shadow-2xl rounded-full transition-transform hover:rotate-6 duration-500">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight mb-3">Hello, I'm Cognix</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-10 max-w-md">
               How can I help you today? I can help with research, coding, or even generate images.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-600"/>, label: 'Write a creative story' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-600"/>, label: 'Generate a futuristic city image' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-600"/>, label: 'Explain how React hooks work' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-600"/>, label: 'Suggest weekend activities' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-5 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[12px] font-bold text-slate-700 dark:text-slate-300 hover:border-blue-600 hover:shadow-lg transition-all flex items-center gap-3 text-left">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-11 h-11 shrink-0 rounded-2xl flex items-center justify-center shadow-lg transition-transform hover:scale-110 ${m.role === 'user' ? 'bg-white dark:bg-slate-800 text-slate-400' : ''}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-full h-full"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[88%] lg:max-w-[80%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-[15px] sm:text-[16px] leading-relaxed font-medium tracking-tight ${m.role === 'user' ? 'message-bubble-user' : 'message-bubble-bot'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Image" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-5 py-2.5 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/50 mt-1">
                        <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-sm"></div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">Searching the web...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 items-center animate-pulse">
                <div className="w-11 h-11 rounded-2xl overflow-hidden"><BotIcon className="w-full h-full"/></div>
                <div className="flex gap-2.5 px-3">
                   <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Redesigned Input Dock */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-3xl border border-white/40 dark:border-slate-700/40 rounded-[2.5rem] p-2 shadow-2xl transition-all ring-1 ring-black/5 dark:ring-white/5">

             {selectedImage && (
               <div className="px-6 py-4 flex items-center gap-5 animate-slide-up border-b border-slate-100/50 dark:border-slate-700/50 mb-2">
                  <div className="relative w-20 h-20 rounded-2xl overflow-hidden ring-4 ring-blue-600/10 shadow-xl group">
                     <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                     <button 
                       onClick={() => setSelectedImage(null)} 
                       className="absolute inset-0 bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-sm"
                     >
                       <span className="font-bold text-sm uppercase">Remove</span>
                     </button>
                  </div>
                  <div className="flex flex-col gap-1">
                    <span className="text-[12px] font-bold text-blue-600 uppercase tracking-widest">Image Loaded</span>
                    <span className="text-[10px] font-medium text-slate-400 dark:text-slate-500">Analyzing pixels for neural processing...</span>
                  </div>
               </div>
             )}

             <div className="flex flex-col">
                <div className="flex items-end gap-2 pr-2">
                   {/* Context Button (Image) */}
                   <button 
                     onClick={() => fileRef.current?.click()}
                     className="w-12 h-12 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-all rounded-full group mb-1.5 ml-2"
                     title="Attach Image"
                   >
                     <ImageIcon className="w-5 h-5 transition-transform group-hover:scale-110" />
                     <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                       const f = e.target.files?.[0];
                       if (f) {
                         const r = new FileReader();
                         r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                         r.readAsDataURL(f);
                       }
                     }} />
                   </button>

                   <textarea 
                     ref={textareaRef}
                     value={input}
                     onChange={onTextChange}
                     onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                     placeholder="Message Cognix..."
                     className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-3 text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400/80 font-medium max-h-[300px] min-h-[56px] leading-relaxed"
                     rows={1}
                   />

                   {/* Send Button */}
                   <button 
                     onClick={handleSend}
                     disabled={isLoading || (!input.trim() && !selectedImage)}
                     className="w-12 h-12 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-200 dark:disabled:bg-slate-800 disabled:text-slate-400 dark:disabled:text-slate-600 active:scale-95 transition-all shadow-lg shadow-blue-500/20 hover:bg-blue-700 group mb-1.5"
                   >
                     <SendIcon className="w-5 h-5 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                   </button>
                </div>

                {/* Meta Settings Row */}
                <div className="flex items-center justify-between px-5 pb-2 pt-1">
                   <div className="flex items-center gap-4">
                      {/* Model Selector */}
                      <button 
                        onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                        className={`text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-full border transition-all flex items-center gap-2 
                          ${model.includes('pro') 
                            ? 'bg-blue-600 border-blue-600 text-white shadow-md' 
                            : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-400 dark:text-slate-500 hover:border-blue-600'}`}
                      >
                         <SparklesIcon className="w-2.5 h-2.5" />
                         {model.includes('pro') ? 'Gemini 3 Pro' : 'Gemini 3 Flash'}
                      </button>

                      {/* Search Toggle */}
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 px-3 py-1.5 rounded-full transition-all border
                          ${isSearchEnabled 
                            ? 'bg-emerald-600/10 border-emerald-600 text-emerald-600' 
                            : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
                      >
                         <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-emerald-600 animate-pulse' : 'bg-slate-300 dark:bg-slate-600'}`}></div>
                         <span className="text-[9px] font-black uppercase tracking-widest">Search Web</span>
                      </button>
                   </div>

                   <div className="flex items-center gap-2">
                      <span className="text-[8px] font-bold text-slate-300 dark:text-slate-600 uppercase tracking-tighter">End-to-End Neural Privacy</span>
                   </div>
                </div>
             </div>
          </div>
          <p className="text-center text-[9px] text-slate-400 dark:text-slate-600 mt-4 font-medium uppercase tracking-[0.2em] opacity-60">Cognix AI may produce inaccurate results. Verify critical information.</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  // FRIENDLY PERSONALITY UPDATE
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix, a super friendly, creative, and supportive AI sidekick. Don't sound like a computer—talk like a smart, helpful human who genuinely wants to help their friend. Be encouraging, clear, and personality-driven. Use a bit of warmth in your tone.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));
    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Chat';
        setChatHistory([{ id: newId, title, messages: next }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Live Talk';
      case 'community': return 'Community';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="hidden lg:flex items-center gap-3">
              <BotIcon className="w-8 h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700"></div>
              <span className="text-sm font-bold text-slate-600 dark:text-slate-300">{getModeLabel(mode)}</span>
            </div>
            <div className="lg:hidden flex items-center gap-2">
              <BotIcon className="w-7 h-7" />
              <h1 className="text-sm font-bold tracking-tight">{getModeLabel(mode)}</h1>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Got it! I've processed that for you." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Friendly Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Oops! My brain hit a snag. Can we try that again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-64 pt-12 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-2xl mx-auto">
             <div className="w-20 h-20 mb-8 shadow-2xl rounded-full transition-transform hover:scale-110 duration-500">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight mb-3 italic">Hey there! I'm Cognix.</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-10 max-w-md">
               What's on your mind today? I can help you write, code, or just chat about life.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-600"/>, label: 'Tell me a funny story' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-600"/>, label: 'Draw a cozy cabin in the woods' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-600"/>, label: 'Teach me something cool' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-600"/>, label: 'Help me plan my day' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-5 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[13px] font-bold text-slate-700 dark:text-slate-300 hover:border-blue-600 hover:shadow-lg transition-all flex items-center gap-3 text-left group">
                    <span className="group-hover:scale-125 transition-transform">{hint.icon}</span> {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-11 h-11 shrink-0 rounded-full flex items-center justify-center shadow-lg transition-transform hover:scale-110 ${m.role === 'user' ? 'bg-blue-50 dark:bg-slate-800 text-blue-500 border border-blue-100 dark:border-slate-700' : ''}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-full h-full"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[88%] lg:max-w-[80%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-[15px] sm:text-[16px] leading-relaxed font-medium tracking-tight ${m.role === 'user' ? 'message-bubble-user rounded-[2rem] rounded-tr-sm' : 'message-bubble-bot rounded-[2rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Creation" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-5 py-2.5 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/50 mt-1">
                        <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">Quickly checking the web...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 items-center animate-pulse">
                <div className="w-11 h-11 rounded-full overflow-hidden"><BotIcon className="w-full h-full"/></div>
                <div className="flex gap-2.5 px-3">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* NEW MESSAGE COGNIX DESIGN: THE BLUE PULSE DOCK */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Glow Effect Background */}
            <div className="absolute -inset-1 bg-gradient-to-r from-blue-600/20 to-cyan-600/20 rounded-[3rem] blur-xl opacity-0 group-hover:opacity-100 transition duration-1000"></div>

            <div className="relative bg-white/90 dark:bg-slate-900/95 backdrop-blur-3xl border border-blue-100/50 dark:border-blue-900/50 rounded-[3rem] p-2 shadow-[0_20px_60px_-15px_rgba(37,99,235,0.15)] ring-1 ring-blue-500/10">

              {selectedImage && (
                <div className="px-6 py-4 flex items-center gap-5 animate-slide-up border-b border-blue-50 dark:border-blue-900/30 mb-2">
                    <div className="relative w-20 h-20 rounded-2xl overflow-hidden ring-4 ring-blue-500/20 shadow-xl group">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button 
                        onClick={() => setSelectedImage(null)} 
                        className="absolute inset-0 bg-blue-600/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-sm"
                      >
                        <span className="font-bold text-sm uppercase">Ditch it</span>
                      </button>
                    </div>
                    <div className="flex flex-col gap-1">
                      <span className="text-[12px] font-bold text-blue-600 uppercase tracking-widest">Image Ready!</span>
                      <span className="text-[10px] font-medium text-slate-400 dark:text-slate-500 italic">I'm ready to look at this for you.</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-2 pr-2">
                    {/* Attachment Button */}
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-12 h-12 shrink-0 flex items-center justify-center text-blue-500 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-800 transition-all rounded-full group ml-2"
                      title="Share an image"
                    >
                      <ImageIcon className="w-5 h-5 transition-transform group-hover:scale-110 group-active:scale-90" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={onTextChange}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Message Cognix..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-3 text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[300px] min-h-[56px] leading-relaxed"
                      rows={1}
                    />

                    {/* NEW BLUE SEND BUTTON */}
                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-14 h-14 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 dark:disabled:text-slate-600 active:scale-95 transition-all shadow-[0_10px_20px_-5px_rgba(37,99,235,0.4)] hover:bg-blue-500 group"
                    >
                      <SendIcon className="w-6 h-6 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </button>
                  </div>

                  {/* BOTTOM ROW SETTINGS */}
                  <div className="flex items-center justify-between px-6 pb-2 pt-1 border-t border-blue-50/50 dark:border-blue-900/20 mt-1">
                    <div className="flex items-center gap-3">
                        <button 
                          onClick={() => setActiveModel(m => m.includes('pro') ? 'gemini-3-flash-preview' : 'gemini-3-pro-preview')}
                          className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all
                            ${model.includes('pro') 
                              ? 'bg-blue-600 text-white shadow-lg' 
                              : 'bg-blue-50 dark:bg-slate-800 text-blue-600 dark:text-blue-400 hover:bg-blue-100'}`}
                        >
                          <SparklesIcon className="w-2.5 h-2.5" />
                          {model.includes('pro') ? 'Gemini 3 Pro' : 'Gemini 3 Flash'}
                        </button>

                        <button 
                          onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                          className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all
                            ${isSearchEnabled 
                              ? 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-400 border border-blue-200 dark:border-blue-800' 
                              : 'bg-transparent text-slate-400 hover:text-slate-900 dark:hover:text-white'}`}
                        >
                          <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-[0_0_8px_rgba(37,99,235,0.6)]' : 'bg-slate-300'}`}></div>
                          Search Web
                        </button>
                    </div>

                    <div className="hidden sm:flex items-center gap-2">
                      <span className="text-[9px] font-bold text-blue-600/40 dark:text-blue-400/30 uppercase tracking-[0.2em] italic">Cognix Secure Link</span>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[10px] text-slate-400 mt-4 font-medium italic opacity-60">Cognix can make mistakes, so double check the important stuff! ❤️</p>
        </div>
      </div>
    </div>
  );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'clora-rv1' // Default fast/friendly
  | 'clorea-v1' // Coding specialized
  | 'gemini-3-pro-preview' 
  | 'gemini-3-flash-preview'
  | 'gemini-flash-lite-latest'
  | 'gemini-2.5-flash-image';

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants?: string[];
}

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  // DEFAULT MODEL: CloraRv1
  const [activeModel, setActiveModel] = useState<ModelType>('clora-rv1');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your friendly AI buddy. I talk like a real person—warm, helpful, and down-to-earth. I'm here to help you build, learn, or just vibe with you. Let's keep things chill and productive!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));
    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Chat';
        setChatHistory([{ id: newId, title, messages: next }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Live Talk';
      case 'community': return 'Community';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="hidden lg:flex items-center gap-3">
              <BotIcon className="w-8 h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700"></div>
              <span className="text-sm font-semibold text-slate-600 dark:text-slate-300 tracking-tight">{getModeLabel(mode)}</span>
            </div>
            <div className="lg:hidden flex items-center gap-2">
              <BotIcon className="w-7 h-7" />
              <h1 className="text-sm font-semibold tracking-tight">{getModeLabel(mode)}</h1>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, systemInstruction, model, setActiveModel }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);

      // MODEL MAPPING:
      // CloraRv1 -> Flash (Fast/Default)
      // CloreaV1 -> Pro (Code/Deep)
      let targetModel: string = 'gemini-3-flash-preview';
      if (isImg) targetModel = 'gemini-2.5-flash-image';
      else if (model === 'clorea-v1') targetModel = 'gemini-3-pro-preview';
      else if (model === 'clora-rv1') targetModel = 'gemini-3-flash-preview';

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Got it! Hope this helps." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Here's what I found online:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "My bad! I ran into an issue. Mind trying that again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-64 pt-12 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-2xl mx-auto">
             <div className="w-16 h-16 mb-8 shadow-xl rounded-2xl transition-transform hover:scale-105 duration-300">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight mb-2">Hey friend, I'm Cognix!</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-10 max-w-sm">
               How can I make your day easier? I can help you with anything you're working on.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-500"/>, label: 'Write a warm greeting' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-500"/>, label: 'Design a simple website icon' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-500"/>, label: 'Explain code like a friend' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-500"/>, label: 'Let\'s brainstorm some ideas' }
                ].map((hint, i) => (
                  <button key={i} onClick={() => setInput(hint.label)} className="px-5 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[14px] font-semibold text-slate-600 dark:text-slate-300 hover:border-blue-500 hover:shadow-pill transition-all flex items-center gap-3 text-left">
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-5 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center shadow-sm transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-blue-50 dark:bg-slate-800 text-blue-500' : ''}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-full h-full"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-6 py-4 text-[15px] sm:text-[16px] leading-relaxed font-medium ${m.role === 'user' ? 'message-bubble-user rounded-[1.5rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.5rem] rounded-tl-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-2xl overflow-hidden border border-slate-50 dark:border-slate-800 shadow-lg bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Creation" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
                        <span className="text-[11px] font-bold text-blue-600">Searching for you...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-5 items-center">
                <div className="w-10 h-10 rounded-xl overflow-hidden"><BotIcon className="w-full h-full"/></div>
                <div className="flex gap-2">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* REFINED MESSAGE COGNIX DOCK: PILL SHAPE & BLUE ACCENTS */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Soft Outer Glow */}
            <div className="absolute -inset-1 bg-blue-500/10 rounded-[2.5rem] blur-xl opacity-0 group-hover:opacity-100 transition duration-500"></div>

            <div className="relative bg-white/95 dark:bg-slate-900/95 backdrop-blur-2xl border border-blue-100/50 dark:border-blue-900/50 rounded-[2.5rem] p-2 shadow-premium ring-1 ring-blue-500/5 transition-all">

              {selectedImage && (
                <div className="px-6 py-4 flex items-center gap-4 animate-slide-up border-b border-blue-50/50 dark:border-blue-900/20 mb-2">
                    <div className="relative w-16 h-16 rounded-xl overflow-hidden ring-2 ring-blue-500/10 shadow-md group/img">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button 
                        onClick={() => setSelectedImage(null)} 
                        className="absolute inset-0 bg-blue-600/60 text-white flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity"
                      >
                        <span className="font-bold text-xs">Remove</span>
                      </button>
                    </div>
                    <div className="flex flex-col gap-0.5">
                      <span className="text-[13px] font-bold text-blue-600">Photo Attached</span>
                      <span className="text-[11px] font-medium text-slate-400">Ready to chat about this!</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-2 pr-2">
                    {/* Image Upload */}
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-11 h-11 shrink-0 flex items-center justify-center text-blue-500 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-all rounded-full group/btn ml-2"
                      title="Send a picture"
                    >
                      <ImageIcon className="w-5 h-5 transition-transform group-hover/btn:scale-110" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={onTextChange}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Message Cognix..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-3 text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[250px] min-h-[52px] leading-relaxed"
                      rows={1}
                    />

                    {/* SEND BUTTON: ICONIC BLUE PILL */}
                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-12 h-12 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-lg shadow-blue-500/20 hover:bg-blue-700 group/send"
                    >
                      <SendIcon className="w-5 h-5 transition-transform group-hover/send:translate-x-0.5 group-hover/send:-translate-y-0.5" />
                    </button>
                  </div>

                  {/* SMART SETTINGS ROW */}
                  <div className="flex items-center justify-between px-6 pb-2 pt-1 border-t border-blue-50/50 dark:border-blue-900/20 mt-1">
                    <div className="flex items-center gap-2.5">
                        {/* CloraRv1 - Default Toggle */}
                        <button 
                          onClick={() => setActiveModel('clora-rv1')}
                          className={`px-3.5 py-1.5 rounded-full text-[11px] font-bold transition-all
                            ${model === 'clora-rv1' 
                              ? 'bg-blue-600 text-white shadow-md' 
                              : 'bg-transparent text-slate-400 hover:text-blue-500'}`}
                        >
                          CloraRv1
                        </button>

                        {/* CloreaV1 - Code Toggle */}
                        <button 
                          onClick={() => setActiveModel('clorea-v1')}
                          className={`px-3.5 py-1.5 rounded-full text-[11px] font-bold transition-all flex items-center gap-1.5
                            ${model === 'clorea-v1' 
                              ? 'bg-blue-600 text-white shadow-md' 
                              : 'bg-transparent text-slate-400 hover:text-blue-500'}`}
                        >
                          <CodeIcon className="w-3 h-3" />
                          CloreaV1
                        </button>

                        <div className="w-[1px] h-3 bg-slate-200 dark:bg-slate-800 mx-1"></div>

                        {/* Search Toggle */}
                        <button 
                          onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                          className={`flex items-center gap-2 px-3.5 py-1.5 rounded-full text-[11px] font-bold transition-all
                            ${isSearchEnabled 
                              ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' 
                              : 'text-slate-400 hover:text-slate-600 dark:hover:text-white'}`}
                        >
                          <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-300'}`}></div>
                          Search Web
                        </button>
                    </div>

                    <div className="hidden sm:flex items-center gap-2">
                      <span className="text-[10px] font-semibold text-slate-300 dark:text-slate-600 tracking-wide uppercase">Private Link</span>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[11px] text-slate-400 mt-4 font-medium opacity-60">I'm still learning, so double check my answers! ❤️</p>
        </div>
      </div>
    </div>
  );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'clora-rv1'           // Default (Gemini 3 Flash)
  | 'clorea-v1'           // Advanced (Gemini 3 Pro)
  | 'clora-lite'         // Lite (Gemini Flash Lite)
  | 'clora-image';        // Creative (Gemini 2.5 Image)

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; // Track up to 5 people
}

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('clora-rv1');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your friendly AI buddy. I talk like a real person—warm, helpful, and down-to-earth. I'm here to help you build, learn, or just vibe with you. Let's keep things chill and productive!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Collaboration state
  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat?.participants || ['You'];

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    // Check for shared chat link
    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const decoded = JSON.parse(atob(sharedData));
        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Chat',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared chat", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Chat';
        setChatHistory([{ id: newId, title, messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Live Talk';
      case 'community': return 'Community';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="hidden lg:flex items-center gap-3">
              <BotIcon className="w-8 h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700"></div>
              <span className="text-sm font-semibold text-slate-600 dark:text-slate-300 tracking-tight">{getModeLabel(mode)}</span>
            </div>

            {activeChatId && mode === 'chat' && (
              <div className="flex items-center -space-x-2 ml-4">
                {participants.map((p, i) => (
                  <div key={i} title={p} className="w-7 h-7 rounded-full bg-blue-100 dark:bg-blue-900/40 border-2 border-white dark:border-slate-900 flex items-center justify-center text-[10px] font-bold text-blue-600">
                    {p[0]}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (activeChatId && participants.length < 5) {
                    setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // 4-MODEL MAPPING SYSTEM
      let targetModel: string;
      switch(model) {
        case 'clorea-v1': targetModel = 'gemini-3-pro-preview'; break;
        case 'clora-lite': targetModel = 'gemini-flash-lite-latest'; break;
        case 'clora-image': targetModel = 'gemini-2.5-flash-image'; break;
        default: targetModel = 'gemini-3-flash-preview';
      }

      // Special case: if user asks for image, force creative model
      const isImgRequest = /draw|image|create|generate/i.test(trimmedInput);
      if (isImgRequest) targetModel = 'gemini-2.5-flash-image';

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImgRequest ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done! Let me know if you need anything else." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Friendly Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Ouch! My brain had a little glitch. Let's try that again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const onTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  const generateShareLink = () => {
    if (!currentChat) return;
    const shareObj = {
      title: currentChat.title,
      messages: currentChat.messages,
      participants: currentChat.participants
    };
    const encoded = btoa(JSON.stringify(shareObj));
    const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    // Simulation: Add a person after sharing
    if (participants.length < 5) {
      onAddParticipant(`Friend ${participants.length + 1}`);
    }
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500 relative">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-64 pt-12 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-2xl mx-auto">
             <div className="w-16 h-16 mb-8 shadow-xl rounded-2xl transition-transform hover:scale-105 duration-300">
                <BotIcon className="w-full h-full" />
             </div>
             <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight mb-2">Hey friend, I'm Cognix!</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-10 max-w-sm">
               What's on your mind? I'm ready to help you create, learn, or brainstorm!
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-500"/>, label: 'Write a warm greeting' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-500"/>, label: 'Design a simple website icon' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-500"/>, label: 'Explain code like a friend' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-500"/>, label: 'Invite friends to this chat' }
                ].map((hint, i) => (
                  <button 
                    key={i} 
                    onClick={() => hint.label.includes('Invite') ? setShowShareModal(true) : setInput(hint.label)} 
                    className="px-5 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[14px] font-semibold text-slate-600 dark:text-slate-300 hover:border-blue-500 hover:shadow-pill transition-all flex items-center gap-3 text-left"
                  >
                    {hint.icon} {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-5 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center shadow-sm transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-blue-50 dark:bg-slate-800 text-blue-500' : ''}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-full h-full"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-6 py-4 text-[15px] sm:text-[16px] leading-relaxed font-medium ${m.role === 'user' ? 'message-bubble-user rounded-[1.5rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.5rem] rounded-tl-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-2xl overflow-hidden border border-slate-50 dark:border-slate-800 shadow-lg bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Creation" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
                        <span className="text-[11px] font-bold text-blue-600">Quick search...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-5 items-center">
                <div className="w-10 h-10 rounded-xl overflow-hidden"><BotIcon className="w-full h-full"/></div>
                <div className="flex gap-2">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* REFINED MESSAGE COGNIX DOCK */}
      <div className="fixed bottom-0 left-0 right-0 p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Glowing Blue Background Pill */}
            <div className="absolute -inset-1 bg-gradient-to-r from-blue-600/10 to-blue-400/10 rounded-[2.5rem] blur-xl opacity-100 transition duration-500"></div>

            <div className="relative bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl border border-blue-100 dark:border-blue-800/80 rounded-[2.5rem] p-2 shadow-premium ring-1 ring-blue-500/10 transition-all">

              {selectedImage && (
                <div className="px-6 py-4 flex items-center gap-4 animate-slide-up border-b border-blue-50 dark:border-blue-900/30 mb-2">
                    <div className="relative w-16 h-16 rounded-xl overflow-hidden ring-2 ring-blue-500/20 shadow-md group/img">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button 
                        onClick={() => setSelectedImage(null)} 
                        className="absolute inset-0 bg-blue-600/80 text-white flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity"
                      >
                        <span className="font-bold text-xs uppercase">Remove</span>
                      </button>
                    </div>
                    <div className="flex flex-col gap-0.5">
                      <span className="text-[12px] font-bold text-blue-600 uppercase tracking-widest">Image Loaded!</span>
                      <span className="text-[10px] font-medium text-slate-400">Ready to discuss this with you.</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-1 pr-2">
                    {/* Image Attachment Button */}
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-11 h-11 shrink-0 flex items-center justify-center text-blue-500 bg-blue-50 dark:bg-blue-900/40 hover:bg-blue-100 dark:hover:bg-blue-800 transition-all rounded-full group/btn ml-2"
                    >
                      <ImageIcon className="w-5 h-5 transition-transform group-hover/btn:scale-110" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={onTextChange}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Message Cognix..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-3 text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[250px] min-h-[52px] leading-relaxed"
                      rows={1}
                    />

                    {/* SEND BUTTON - Blue & Powerful */}
                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-12 h-12 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-lg shadow-blue-500/20 hover:bg-blue-700 group/send"
                    >
                      <SendIcon className="w-5 h-5 transition-transform group-hover/send:translate-x-0.5 group-hover/send:-translate-y-0.5" />
                    </button>
                  </div>

                  {/* 4-MODEL SWITCHER & TOOLS */}
                  <div className="flex flex-wrap items-center gap-2 px-6 pb-2 pt-1 border-t border-blue-50/50 dark:border-blue-900/20 mt-1">
                    <div className="flex items-center gap-2">
                        {[
                          { id: 'clora-rv1', label: 'Flash 3.0' },
                          { id: 'clorea-v1', label: 'Pro 3.0' },
                          { id: 'clora-lite', label: 'Lite' },
                          { id: 'clora-image', label: 'Creative' }
                        ].map(m => (
                          <button 
                            key={m.id}
                            onClick={() => setActiveModel(m.id as ModelType)}
                            className={`px-3 py-1 rounded-full text-[10px] font-bold transition-all uppercase tracking-tight
                              ${model === m.id 
                                ? 'bg-blue-600 text-white shadow-md' 
                                : 'bg-transparent text-slate-400 hover:text-blue-500'}`}
                          >
                            {m.label}
                          </button>
                        ))}
                    </div>

                    <div className="h-3 w-[1px] bg-slate-200 dark:bg-slate-800 mx-1"></div>

                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold transition-all
                          ${isSearchEnabled 
                            ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/40' 
                            : 'text-slate-400 hover:text-slate-600 dark:hover:text-white'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-300'}`}></div>
                        Search Web
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold text-slate-400 hover:text-blue-600 transition-all"
                        title="Add people"
                      >
                        <UsersIcon className="w-3 h-3" />
                        Add People
                      </button>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[10px] text-slate-400 mt-4 font-medium opacity-60">Cognix can make mistakes, so verify important info! ❤️</p>
        </div>
      </div>

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2rem] p-8 shadow-2xl border border-blue-50 dark:border-blue-900/50" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-6">
              <UsersIcon className="w-6 h-6 text-blue-600" />
              <h3 className="text-lg font-bold">Invite to Chat</h3>
            </div>
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 leading-relaxed">
              Share this link with up to 5 people to let them join this conversation session!
            </p>
            <div className="flex gap-2">
              <button 
                onClick={generateShareLink}
                className="flex-1 bg-blue-600 text-white py-3 rounded-2xl font-bold text-sm shadow-lg shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <CopyIcon className="w-4 h-4" />
                {copied ? 'Copied!' : 'Copy Share Link'}
              </button>
            </div>
            <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800">
               <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Active Link: 1/5 Users</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

