                <BotIcon className="w-14 h-14" />
             </div>
             <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight mb-3">Hey! I'm Cognix.</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-12 max-w-sm">
               Your friendly neighborhood AI. I can help you with code, art, research, or just hanging out.
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-500"/>, label: 'Write a warm message' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-500"/>, label: 'Draw a sunset over the city' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-500"/>, label: 'Help me debug my project' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-500"/>, label: 'Invite my friends to chat' }
