                <div className={`w-11 h-11 shrink-0 rounded-2xl flex items-center justify-center shadow-premium transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
