};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('clora-rv1');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your friendly AI buddy. I talk like a real person—warm, helpful, and down-to-earth. I'm here to help you build, learn, or just vibe with you. Let's keep things chill and productive!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Collaboration state
  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat?.participants || ['You'];

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    // Check for shared chat link
    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const decoded = JSON.parse(atob(sharedData));
        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Chat',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared chat", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Chat';
        setChatHistory([{ id: newId, title, messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Live Talk';
      case 'community': return 'Community';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-6 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="hidden lg:flex items-center gap-3">
              <BotIcon className="w-8 h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700"></div>
              <span className="text-sm font-semibold text-slate-600 dark:text-slate-300 tracking-tight">{getModeLabel(mode)}</span>
            </div>

            {activeChatId && mode === 'chat' && (
              <div className="flex items-center -space-x-2 ml-4">
                {participants.slice(0, 5).map((p, i) => (
                  <div key={i} title={p} className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/40 border-2 border-white dark:border-slate-900 flex items-center justify-center text-[11px] font-black text-blue-600 shadow-sm">
                    {p[0]}
                  </div>
                ))}
                {participants.length > 5 && (
                  <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 border-2 border-white dark:border-slate-900 flex items-center justify-center text-[10px] font-bold text-slate-500">
                    +{participants.length - 5}
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (activeChatId && participants.length < 5) {
                    setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'gemini-3-flash-preview' // Gemini 3.0 Flash
  | 'gemini-3-pro-preview'   // Gemini 3.0 Pro
  | 'gemini-flash-lite-latest' // Flash Lite
  | 'gemini-2.5-flash-image';   // Creative Image

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; // Up to 5 people
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon, CopyIcon, StopIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done! Let me know if you need anything else." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Found some info for you:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "My bad, something tripped me up. Can we try again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    const shareObj = { title: currentChat.title, messages: currentChat.messages, participants: currentChat.participants };
    const encoded = btoa(JSON.stringify(shareObj));
    const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    if (participants.length < 5) onAddParticipant(`Guest ${participants.length + 1}`);
  };

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'Gemini 3.0 Flash', desc: 'Lightweight & Instant', color: 'bg-blue-500' },
    { id: 'gemini-3-pro-preview', label: 'Gemini 3.0 Pro', desc: 'Heavyweight Intelligence', color: 'bg-indigo-600' },
    { id: 'gemini-flash-lite-latest', label: 'Gemini Lite', desc: 'The Swift Specialist', color: 'bg-cyan-500' },
    { id: 'gemini-2.5-flash-image', label: 'Gemini Creative', desc: 'Art & Design Expert', color: 'bg-pink-500' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500 relative">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-64 pb-72 pt-12 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-2xl mx-auto">
             <div className="w-24 h-24 mb-10 shadow-premium rounded-[2.5rem] bg-blue-600 flex items-center justify-center transition-transform hover:scale-110 duration-500">
                <BotIcon className="w-16 h-16" />
             </div>
             <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight mb-3">Hey bruh! I'm Cognix.</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg font-medium leading-relaxed mb-12 max-w-sm">
               Your smart AI sidekick. What should we build, write, or brainstorm today?
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-500"/>, label: 'Write a funny email' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-500"/>, label: 'Draw a cool robot skater' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-500"/>, label: 'Help me with some code' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-500"/>, label: 'Invite friends to chat' }
                ].map((hint, i) => (
                  <button 
                    key={i} 
                    onClick={() => hint.label.includes('Invite') ? setShowShareModal(true) : setInput(hint.label)} 
                    className="px-6 py-5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-3xl text-[14px] font-bold text-slate-600 dark:text-slate-300 hover:border-blue-500 hover:shadow-pill transition-all flex items-center gap-4 text-left group"
                  >
                    <span className="p-2.5 bg-blue-50 dark:bg-blue-900/20 rounded-xl group-hover:scale-110 transition-transform">{hint.icon}</span> 
                    {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-12 h-12 shrink-0 rounded-2xl flex items-center justify-center shadow-premium transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-full h-full p-2.5"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-7 py-5 text-[15px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[2rem] rounded-tr-sm' : 'message-bubble-bot rounded-[2rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-2xl overflow-hidden border-2 border-white shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Cognix Creation" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-3 px-5 py-2.5 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_rgba(37,99,235,0.8)]"></div>
                        <span className="text-[11px] font-bold text-blue-600 uppercase tracking-widest">Checking the web...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 items-center">
                <div className="w-12 h-12 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2.5"/></div>
                <div className="flex gap-2.5">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* THE VIBRANT PILL DOCK */}
      <div className="fixed bottom-0 left-0 right-0 p-8 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Glowing Backdrop */}
            <div className="absolute -inset-1 bg-gradient-to-r from-blue-600/15 to-blue-400/15 rounded-[3.5rem] blur-2xl opacity-100 transition duration-500"></div>

            <div className="relative bg-white/95 dark:bg-slate-900/98 backdrop-blur-3xl border-2 border-blue-100 dark:border-blue-900/40 rounded-[3.5rem] p-3 shadow-premium ring-1 ring-blue-500/10 transition-all">

              {selectedImage && (
                <div className="px-8 py-5 flex items-center gap-5 animate-slide-up border-b border-blue-50 dark:border-blue-900/20 mb-2">
                    <div className="relative w-20 h-20 rounded-2xl overflow-hidden ring-4 ring-blue-500/10 shadow-lg group/img">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button 
                        onClick={() => setSelectedImage(null)} 
                        className="absolute inset-0 bg-blue-600/80 text-white flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity backdrop-blur-sm"
                      >
                        <span className="font-bold text-xs uppercase tracking-widest">Ditch</span>
                      </button>
                    </div>
                    <div className="flex flex-col gap-1">
                      <span className="text-[13px] font-bold text-blue-600 uppercase tracking-widest italic">Image Locked!</span>
                      <span className="text-[11px] font-medium text-slate-400">Ready to discuss this masterpiece.</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-2 pr-2">
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-14 h-14 shrink-0 flex items-center justify-center text-blue-600 bg-blue-50 dark:bg-blue-900/40 hover:bg-blue-100 dark:hover:bg-blue-800 transition-all rounded-full group/btn ml-2"
                      title="Attach Media"
                    >
                      <ImageIcon className="w-6 h-6 transition-transform group-hover/btn:scale-110" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={e => {
                        setInput(e.target.value);
                        e.target.style.height = 'auto';
                        e.target.style.height = Math.min(e.target.scrollHeight, 250) + 'px';
                      }}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Message Cognix..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-4 px-4 text-[17px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[250px] min-h-[56px] leading-relaxed"
                      rows={1}
                    />

                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-14 h-14 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-lg shadow-blue-500/30 hover:bg-blue-500 group/send"
                    >
                      <SendIcon className="w-6 h-6 transition-transform group-hover/send:translate-x-1 group-hover/send:-translate-y-1" />
                    </button>
                  </div>

                  {/* BOTTOM ACTIONS BAR */}
                  <div className="flex flex-wrap items-center justify-between px-8 pb-3 pt-2 border-t border-blue-50/50 dark:border-blue-900/10 mt-2">
                    <div className="flex items-center gap-3">
                        <button 
                          onClick={() => setShowModelMenu(true)}
                          className="flex flex-col items-center px-5 py-2 rounded-2xl bg-blue-50 dark:bg-blue-900/30 text-blue-600 hover:bg-blue-100 transition-all border border-blue-100 dark:border-blue-800/50"
                        >
                          <span className="text-[10px] font-black uppercase tracking-widest">{activeModelData.label}</span>
                          <span className="text-[8px] font-bold opacity-60 uppercase">{activeModelData.desc}</span>
                        </button>
                    </div>

                    <div className="flex items-center gap-5">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-2xl text-[11px] font-bold uppercase transition-all
                          ${isSearchEnabled 
                            ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30 border border-blue-200 dark:border-blue-800' 
                            : 'text-slate-400 hover:text-slate-700 dark:hover:text-white'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-glow' : 'bg-slate-300'}`}></div>
                        Live Search
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-2 text-[11px] font-bold text-slate-400 hover:text-blue-600 transition-all group/ppl"
                      >
                        <UsersIcon className="w-4 h-4 group-hover/ppl:scale-110" />
                        <span>({participants.length}/5)</span>
                      </button>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[11px] text-slate-400 mt-5 font-bold uppercase tracking-[0.2em] opacity-40 italic">Cognix can trip up sometimes—verify the big stuff! ❤️</p>
        </div>
      </div>

      {/* SWIPE UP MODEL POPUP */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[3rem] p-8 shadow-premium animate-slide-up-pop" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-800 rounded-full mx-auto mb-8" />
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-2xl font-black italic tracking-tight">Switch Brain.</h3>
              <button onClick={() => setShowModelMenu(false)} className="text-slate-400 hover:text-blue-600 text-xl font-bold">&times;</button>
            </div>
            <div className="grid grid-cols-1 gap-4">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id}
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }}
                   className={`flex items-center gap-5 p-6 rounded-[2rem] transition-all border-2 text-left group
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800 hover:border-blue-300 dark:hover:border-blue-900/50 bg-white dark:bg-slate-800'}`}
                 >
                   <div className={`w-14 h-14 rounded-2xl ${opt.color} flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform`}>
                      <SparklesIcon className="w-7 h-7" />
                   </div>
                   <div className="flex-1">
                      <p className="text-lg font-black tracking-tight">{opt.label}</p>
                      <p className="text-sm text-slate-400 font-medium">{opt.desc}</p>
                   </div>
                   {model === opt.id && <div className="w-3 h-3 bg-blue-600 rounded-full shadow-[0_0_8px_rgba(37,99,235,0.8)]"></div>}
                 </button>
               ))}
            </div>
            <p className="text-center text-[10px] font-black uppercase tracking-widest text-slate-400 mt-8 mb-4">Select the neural engine for your task</p>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[3rem] p-10 shadow-premium border border-blue-50 dark:border-blue-900/50" onClick={e => e.stopPropagation()}>
            <div className="w-20 h-20 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white shadow-xl mb-8 mx-auto">
              <UsersIcon className="w-10 h-10" />
            </div>
            <h3 className="text-2xl font-black italic text-center mb-3">Invite Squad.</h3>
            <p className="text-slate-500 text-center mb-8 font-medium">Share this neural link with up to 5 people to bring them into the brain session.</p>

            <button 
              onClick={generateShareLink}
              className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              <CopyIcon className="w-5 h-5" />
              {copied ? 'Link Copied!' : 'Copy Share Link'}
            </button>

            <div className="mt-10 pt-8 border-t border-slate-100 dark:border-slate-800">
               <div className="flex items-center justify-between mb-5">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Members</span>
                 <span className="text-[10px] font-black text-blue-600">{participants.length} / 5</span>
               </div>
               <div className="flex flex-wrap gap-2 justify-center">
                  {participants.map((p, i) => (
                    <div key={i} className="px-4 py-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-xl text-[10px] font-black uppercase italic">
                      {p}
                    </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'gemini-3-flash-preview' // Gemini 3.0 Flash
  | 'gemini-3-pro-preview'   // Gemini 3.0 Pro
  | 'gemini-flash-lite-latest' // Flash Lite
  | 'gemini-2.5-flash-image';   // Creative Image

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; 
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, CodeIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Got it! Let me know if you need anything else." }];

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks && isSearchEnabled) {
          const links = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => `\n- [${chunk.web.title}](${chunk.web.uri})`)
            .join('');
          if (links) resParts.push({ text: `\n\n**Friendly Sources:**\n${links}` });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Ouch! Something glitched. Can we try again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    const shareObj = { title: currentChat.title, messages: currentChat.messages, participants: currentChat.participants };
    const encoded = btoa(JSON.stringify(shareObj));
    const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    if (participants.length < 5) onAddParticipant(`Guest ${participants.length + 1}`);
  };

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'Gemini 3.0 Flash', desc: 'Fast & Lightweight', color: 'bg-blue-500' },
    { id: 'gemini-3-pro-preview', label: 'Gemini 3.0 Pro', desc: 'Technical & Creative Power', color: 'bg-indigo-600' },
    { id: 'gemini-flash-lite-latest', label: 'Gemini Lite', desc: 'Efficiency King', color: 'bg-cyan-500' },
    { id: 'gemini-2.5-flash-image', label: 'Creative Image', desc: 'Visual Arts Engine', color: 'bg-pink-500' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500 relative overflow-hidden">
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-48 pb-64 pt-8 scroll-smooth">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center animate-slide-up max-w-xl mx-auto py-10">
             <div className="w-16 h-16 sm:w-20 sm:h-20 mb-8 shadow-premium rounded-3xl bg-blue-600 flex items-center justify-center transition-transform hover:scale-110 duration-500">
                <BotIcon className="w-10 h-10 sm:w-12 sm:h-12" />
             </div>
             <h2 className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white tracking-tight mb-2">Hey bruh! Cognix here.</h2>
             <p className="text-slate-500 dark:text-slate-400 text-base sm:text-lg font-medium leading-relaxed mb-8 max-w-sm">
               Your smart AI sidekick. What's on your mind today?
             </p>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full px-4">
                {[
                  { icon: <SparklesIcon className="w-4 h-4 text-blue-500"/>, label: 'Draft a friendly text' },
                  { icon: <ImageIcon className="w-4 h-4 text-blue-500"/>, label: 'Design a synthwave logo' },
                  { icon: <CodeIcon className="w-4 h-4 text-blue-500"/>, label: 'Debug a React hook' },
                  { icon: <UsersIcon className="w-4 h-4 text-blue-500"/>, label: 'Invite squads to this chat' }
                ].map((hint, i) => (
                  <button 
                    key={i} 
                    onClick={() => hint.label.includes('Invite') ? setShowShareModal(true) : setInput(hint.label)} 
                    className="px-5 py-4 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[13px] font-bold text-slate-600 dark:text-slate-300 hover:border-blue-500 hover:shadow-pill transition-all flex items-center gap-3 text-left group"
                  >
                    <span className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-xl group-hover:scale-110 transition-transform">{hint.icon}</span> 
                    {hint.label}
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 sm:gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-9 h-9 sm:w-11 sm:h-11 shrink-0 rounded-xl flex items-center justify-center shadow-premium transition-transform hover:scale-105 ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 sm:px-6 sm:py-4 text-[14px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-3xl rounded-tr-sm' : 'message-bubble-bot rounded-3xl rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-xl overflow-hidden border-2 border-white shadow-lg bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain" alt="Cognix Visual" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">Checking the net...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 sm:gap-6 items-center">
                <div className="w-9 h-9 sm:w-11 sm:h-11 rounded-xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2"/></div>
                <div className="flex gap-2">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* SLEEKER INPUT DOCK */}
      <div className="fixed bottom-0 left-0 right-0 p-4 sm:p-6 lg:pl-80 z-50 safe-pb pointer-events-none">
        <div className="max-w-3xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Minimal Inner Glow */}
            <div className="absolute -inset-1 bg-blue-500/10 rounded-[2.5rem] blur-xl opacity-100 transition duration-500"></div>

            <div className="relative bg-white/95 dark:bg-slate-900/98 backdrop-blur-3xl border border-blue-100 dark:border-blue-900/40 rounded-[2rem] p-1.5 sm:p-2 shadow-premium ring-1 ring-blue-500/5 transition-all">

              {selectedImage && (
                <div className="px-6 py-3 flex items-center gap-4 animate-slide-up border-b border-blue-50 dark:border-blue-900/20 mb-1">
                    <div className="relative w-14 h-14 rounded-xl overflow-hidden shadow-md group/img">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-blue-600/80 text-white flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity backdrop-blur-sm">
                        <span className="font-bold text-[10px] uppercase">Ditch</span>
                      </button>
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[11px] font-black text-blue-600 uppercase italic">Photo Attached</span>
                      <span className="text-[9px] font-medium text-slate-400">Ready to discuss.</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-1.5 pr-1.5">
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-10 h-10 sm:w-11 sm:h-11 shrink-0 flex items-center justify-center text-blue-600 bg-blue-50 dark:bg-blue-900/40 hover:bg-blue-100 dark:hover:bg-blue-800 transition-all rounded-full group/btn ml-1"
                    >
                      <ImageIcon className="w-5 h-5" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={e => {
                        setInput(e.target.value);
                        e.target.style.height = 'auto';
                        e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
                      }}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Message Cognix..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-3 px-2 text-[15px] sm:text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[200px] min-h-[44px] leading-relaxed"
                      rows={1}
                    />

                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-10 h-10 sm:w-11 sm:h-11 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-md hover:bg-blue-500"
                    >
                      <SendIcon className="w-5 h-5 transition-transform group-hover/send:translate-x-0.5" />
                    </button>
                  </div>

                  {/* BOTTOM ACTIONS BAR - COMPACT */}
                  <div className="flex items-center justify-between px-4 pb-1.5 pt-1 mt-1 border-t border-blue-50 dark:border-blue-900/10">
                    <div className="flex items-center gap-2">
                        <button 
                          onClick={() => setShowModelMenu(true)}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-blue-50 dark:bg-blue-900/30 text-blue-600 hover:bg-blue-100 transition-all border border-blue-100 dark:border-blue-800/50"
                        >
                          <span className="text-[10px] font-black uppercase tracking-tight italic">{activeModelData.label.split(' ').pop()} 3.0</span>
                          <svg className="w-3 h-3 opacity-60" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M18 15l-6-6-6 6" /></svg>
                        </button>
                    </div>

                    <div className="flex items-center gap-4">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all
                          ${isSearchEnabled 
                            ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30 border border-blue-100 dark:border-blue-800' 
                            : 'text-slate-400 hover:text-slate-700'}`}
                      >
                        <div className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-glow' : 'bg-slate-300'}`}></div>
                        Search
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-3.5 h-3.5" />
                        <span>({participants.length}/5)</span>
                      </button>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[9px] text-slate-400 mt-4 font-black uppercase tracking-widest opacity-30 italic">Cognix v9.5 • Private Session</p>
        </div>
      </div>

      {/* SWIPE UP MODEL MENU POPUP */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[2.5rem] p-6 sm:p-8 shadow-premium animate-slide-up-pop" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-800 rounded-full mx-auto mb-6" />
            <div className="flex items-center justify-between mb-6 px-1">
              <h3 className="text-xl font-black italic tracking-tight">Select Engine.</h3>
              <button onClick={() => setShowModelMenu(false)} className="text-slate-400 hover:text-blue-600 text-2xl font-bold">&times;</button>
            </div>
            <div className="grid grid-cols-1 gap-3">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id}
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }}
                   className={`flex items-center gap-4 p-5 rounded-3xl transition-all border-2 text-left group
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800 hover:border-blue-300 bg-white dark:bg-slate-800'}`}
                 >
                   <div className={`w-12 h-12 shrink-0 rounded-2xl ${opt.color} flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-110`}>
                      <SparklesIcon className="w-6 h-6" />
                   </div>
                   <div className="flex-1">
                      <p className="text-base font-black tracking-tight">{opt.label}</p>
                      <p className="text-xs text-slate-400 font-medium">{opt.desc}</p>
                   </div>
                   {model === opt.id && <div className="w-2.5 h-2.5 bg-blue-600 rounded-full shadow-glow"></div>}
                 </button>
               ))}
            </div>
            <p className="text-center text-[9px] font-black uppercase tracking-widest text-slate-400 mt-8">Switching engine updates session intelligence.</p>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.5rem] p-10 shadow-premium border border-blue-50 dark:border-blue-900/50" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-blue-600 rounded-[1.5rem] flex items-center justify-center text-white shadow-xl mb-6 mx-auto">
              <UsersIcon className="w-8 h-8" />
            </div>
            <h3 className="text-2xl font-black italic text-center mb-2">Invite.</h3>
            <p className="text-slate-500 text-center mb-8 font-medium text-sm px-4">Share this link with up to 5 people to join your brain session.</p>

            <button 
              onClick={generateShareLink}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              <CopyIcon className="w-5 h-5" />
              {copied ? 'Copied!' : 'Copy Share Link'}
            </button>

            <div className="mt-10 pt-8 border-t border-slate-100 dark:border-slate-800">
               <div className="flex items-center justify-between mb-4">
                 <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Members</span>
                 <span className="text-[9px] font-black text-blue-600">{participants.length} / 5</span>
               </div>
               <div className="flex flex-wrap gap-2 justify-center">
                  {participants.map((p, i) => (
                    <div key={i} className="px-3 py-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-xl text-[9px] font-black uppercase italic">
                      {p}
                    </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your friendly AI buddy. I talk like a real person—warm, helpful, and down-to-earth. I'm here to help you build, learn, or just vibe with you. Let's keep things chill and productive!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [friends, setFriends] = useState<Friend[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat?.participants || ['You'];

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const decoded = JSON.parse(atob(sharedData));
        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Chat',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared chat", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Chat';
        setChatHistory([{ id: newId, title, messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Chat';
      case 'coding': return 'Lab';
      case 'live': return 'Talk';
      case 'community': return 'Squad';
      default: return 'Cognix';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-14 sm:h-16 flex items-center justify-between px-4 sm:px-6 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-3">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-500 transition-all">
              <MenuIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
            </button>
            <div className="flex items-center gap-2 sm:gap-3">
              <BotIcon className="w-7 h-7 sm:w-8 sm:h-8" />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700 mx-1"></div>
              <span className="text-sm font-bold text-slate-600 dark:text-slate-300 tracking-tight italic uppercase italic">{getModeLabel(mode)}</span>
            </div>

            {activeChatId && mode === 'chat' && (
              <div className="hidden sm:flex items-center -space-x-1.5 ml-3">
                {participants.slice(0, 5).map((p, i) => (
                  <div key={i} title={p} className="w-6 h-6 rounded-full bg-blue-100 dark:bg-blue-900/40 border-2 border-white dark:border-slate-900 flex items-center justify-center text-[9px] font-black text-blue-600 shadow-sm">
                    {p[0]}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-9 h-9 sm:w-10 sm:h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (activeChatId && participants.length < 5) {
                    setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView theme={THEME} />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

