                  <div className="px-6 py-12 text-center border border-dashed border-slate-100 dark:border-slate-800 rounded-3xl opacity-50">
                    <p className="text-[11px] text-slate-400 font-medium">No recent conversations</p>
                  </div>
                ) : (
                  chatHistory.map((chat) => (
                    <div key={chat.id} className="group relative px-1">
                      <button 
                        onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                        className={`w-full text-left px-4 py-3 rounded-xl transition-all flex items-center justify-between
                          ${activeChatId === chat.id && mode === 'chat' 
                            ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400' 
                            : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50/80 dark:hover:bg-slate-800/40'}
                        `}
                      >
                        <span className="text-[12px] truncate w-full font-medium leading-none">{chat.title || 'Untitled Chat'}</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }}
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all"
                      >
                        <TrashIcon className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  ))
                )}
              </div>
           </div>

           {/* Footer System Status */}
           <div className="pt-6 border-t border-slate-100 dark:border-slate-800/60 mt-auto">
              <div className="flex items-center justify-between bg-slate-50 dark:bg-slate-800/40 p-3 rounded-2xl">
                <div className="flex items-center gap-3">
                  <div className="relative">
                    <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]"></div>
                  </div>
                  <span className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">System Ready</span>
                </div>
                <span className="text-[9px] font-mono text-slate-300 dark:text-slate-600 font-bold tracking-tighter">v9.5.0</span>
              </div>
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      // Ensure API_KEY is available to prevent uncaught reference errors
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : model;

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "I ran into a bit of trouble with that. Can we try again?" }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    try {
      const shareObj = { title: currentChat.title, messages: currentChat.messages, participants: currentChat.participants };
      const encoded = btoa(JSON.stringify(shareObj));
      const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
      navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      if (participants.length < 5) onAddParticipant(`Guest ${participants.length + 1}`);
    } catch (err) {
      console.error("Link generation failed", err);
    }
  };

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'Clorea 3.0', desc: 'Expert Neural Engine', color: 'bg-indigo-600' },
    { id: 'gemini-3-flash-preview', label: 'Clora 3.0', desc: 'Instant & Dynamic', color: 'bg-blue-600' },
    { id: 'gemini-flash-lite-latest', label: 'Clora Lite', desc: 'Minimal Resource Mode', color: 'bg-cyan-500' },
    { id: 'gemini-2.5-flash-image', label: 'Clora Art', desc: 'Visual Generation', color: 'bg-pink-500' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500 relative overflow-hidden">

      {/* Messages Container */}
      <div ref={containerRef} className={`flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-48 scroll-smooth ${hasMessages ? 'pb-64 pt-8' : 'flex flex-col items-center justify-center pt-20 pb-40'}`}>
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up transition-all duration-700">
             <div className="w-24 h-24 sm:w-32 sm:h-32 mb-8 shadow-premium rounded-[3rem] bg-blue-600 flex items-center justify-center transition-all hover:scale-105 duration-500 group">
                <BotIcon className="w-16 h-16 sm:w-24 sm:h-24 transition-transform group-hover:rotate-6" />
             </div>
             <h2 className="text-3xl sm:text-4xl font-black text-slate-900 dark:text-white tracking-tighter mb-3 italic text-center">Clora Intelligence</h2>
             <p className="text-slate-500 dark:text-slate-400 text-lg sm:text-xl font-medium leading-relaxed text-center max-w-xs px-4">
               The future of conversation is here. How can I help?
             </p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 sm:gap-8 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 sm:w-12 sm:h-12 shrink-0 rounded-2xl flex items-center justify-center shadow-premium transition-transform hover:scale-110 ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-6 h-6"/> : <BotIcon className="w-full h-full p-2.5"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 sm:px-7 sm:py-4 text-[15px] sm:text-[17px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[2rem] rounded-tr-sm' : 'message-bubble-bot rounded-[2rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-4 rounded-3xl overflow-hidden border-2 border-white dark:border-slate-800 shadow-2xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain" alt="Response Graphic" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Searching World Info...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 sm:gap-6 items-center">
                <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2.5"/></div>
                <div className="flex gap-2.5">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* DYNAMIC INPUT DOCK - SMARTER & MORE RESPONSIVE */}
      <div className={`fixed left-0 right-0 p-4 sm:p-6 lg:pl-80 z-50 safe-pb pointer-events-none transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) ${hasMessages ? 'bottom-0' : 'bottom-1/3 sm:bottom-1/2 translate-y-12 sm:translate-y-20'}`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="relative group">
            <div className="absolute -inset-1 bg-blue-500/10 rounded-[2.5rem] blur-xl opacity-100 transition duration-500"></div>

            <div className="relative bg-white/98 dark:bg-slate-900/98 backdrop-blur-3xl border border-blue-100/50 dark:border-blue-900/40 rounded-[2rem] p-1.5 sm:p-2 shadow-premium transition-all">

              {selectedImage && (
                <div className="px-5 py-3 flex items-center gap-4 animate-slide-up border-b border-blue-50 dark:border-blue-900/20 mb-1">
                    <div className="relative w-12 h-12 rounded-xl overflow-hidden shadow-lg group/img">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-blue-600/80 text-white flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity backdrop-blur-sm">
                        <span className="font-bold text-[9px] uppercase">Ditch</span>
                      </button>
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[10px] font-black text-blue-600 uppercase italic">Media Loaded</span>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/40 transition-all rounded-full group/btn ml-1"
                    >
                      <ImageIcon className="w-5 h-5" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={e => {
                        setInput(e.target.value);
                        e.target.style.height = 'auto';
                        e.target.style.height = Math.min(e.target.scrollHeight, 180) + 'px';
                      }}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Ask Clora anything..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-2.5 px-3 text-[15px] sm:text-[16px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[180px] min-h-[44px] leading-relaxed"
                      rows={1}
                    />

                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-10 h-10 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-md hover:bg-blue-500 mr-1"
                    >
                      <SendIcon className="w-5 h-5 transition-transform group-hover/send:translate-x-0.5" />
                    </button>
                  </div>

                  <div className="flex items-center justify-between px-3 pb-1.5 pt-1 mt-1 border-t border-blue-50/50 dark:border-blue-900/10">
                    <div className="flex items-center gap-1.5">
                        <button 
                          onClick={() => setShowModelMenu(true)}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-blue-50 dark:bg-blue-900/30 text-blue-600 hover:bg-blue-100 transition-all border border-blue-100/50 dark:border-blue-800/30"
                        >
                          <span className="text-[10px] font-black uppercase tracking-tight italic">{activeModelData.label}</span>
                          <svg className="w-3 h-3 opacity-60" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.5"><path d="M18 15l-6-6-6 6" /></svg>
                        </button>
                    </div>

                    <div className="flex items-center gap-4">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all
                          ${isSearchEnabled 
                            ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' 
                            : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-glow' : 'bg-slate-300'}`}></div>
                        Search
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-4 h-4" />
                        <span className="opacity-60">{participants.length}/5</span>
                      </button>
                    </div>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[9px] text-slate-400 mt-4 font-black uppercase tracking-[0.2em] opacity-30 italic">Clora Neural Link v10.0</p>
        </div>
      </div>

      {/* SWIPE UP POPUP MENU */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[3rem] p-6 sm:p-8 shadow-premium animate-slide-up-pop" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-1.5 bg-slate-200 dark:bg-slate-800 rounded-full mx-auto mb-8" />
            <div className="flex items-center justify-between mb-8 px-2">
              <h3 className="text-2xl font-black italic tracking-tighter">Neural Core.</h3>
              <button onClick={() => setShowModelMenu(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400 hover:text-blue-600 transition-all">&times;</button>
            </div>
            <div className="grid grid-cols-1 gap-3">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id}
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }}
                   className={`flex items-center gap-5 p-5 rounded-[2rem] transition-all border-2 text-left group
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800 hover:border-blue-300 bg-white dark:bg-slate-800'}`}
                 >
                   <div className={`w-12 h-12 shrink-0 rounded-2xl ${opt.color} flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-110`}>
                      <SparklesIcon className="w-6 h-6" />
                   </div>
                   <div className="flex-1">
                      <p className="text-lg font-black tracking-tight">{opt.label}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{opt.desc}</p>
                   </div>
                   {model === opt.id && <div className="w-3.5 h-3.5 bg-blue-600 rounded-full shadow-glow"></div>}
                 </button>
               ))}
            </div>
            <p className="text-center text-[9px] font-black uppercase tracking-widest text-slate-400 mt-8">Switch the brain engine for specialized tasks.</p>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.5rem] p-10 shadow-premium border border-blue-50/50 dark:border-blue-900/50" onClick={e => e.stopPropagation()}>
            <div className="w-20 h-20 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white shadow-2xl mb-8 mx-auto">
              <UsersIcon className="w-10 h-10" />
            </div>
            <h3 className="text-3xl font-black italic text-center mb-2 tracking-tighter">Invite.</h3>
            <p className="text-slate-500 text-center mb-8 font-medium text-sm px-2">Collaborate in this session with up to 5 members.</p>

            <button 
              onClick={generateShareLink}
              className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all flex items-center justify-center gap-4"
            >
              <CopyIcon className="w-6 h-6" />
              {copied ? 'Copied!' : 'Copy Share Link'}
            </button>

            <div className="mt-10 pt-8 border-t border-slate-100 dark:border-slate-800">
               <div className="flex items-center justify-between mb-5">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Members</span>
                 <span className="text-[10px] font-black text-blue-600">{participants.length} / 5</span>
               </div>
               <div className="flex flex-wrap gap-2.5 justify-center">
                  {participants.map((p, i) => (
                    <div key={i} className="px-4 py-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-xl text-[9px] font-black uppercase italic shadow-sm">
                      {p}
                    </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-pro-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Clora, your friendly AI companion. I talk like a real person—warm, smart, and down-to-earth. I'm here to help you build, learn, or just chill and brainstorm. Let's make something awesome!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat?.participants || ['You'];

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const decoded = JSON.parse(atob(sharedData));
        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Chat',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared chat", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Session';
        setChatHistory([{ id: newId, title, messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Brain';
      case 'coding': return 'Lab';
      case 'live': return 'Talk';
      case 'community': return 'Squad';
      default: return 'Clora';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-16 flex items-center justify-between px-4 sm:px-10 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-600 transition-all">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="flex items-center gap-3">
              <BotIcon className="w-10 h-10 sm:w-11 sm:h-11" />
              <div className="h-5 w-[1px] bg-slate-200 dark:bg-slate-700 mx-1 sm:mx-2"></div>
              <span className="text-sm sm:text-lg font-black text-slate-900 dark:text-white tracking-tighter italic uppercase">{getModeLabel(mode)}</span>
            </div>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            {activeChatId && mode === 'chat' && (
              <div className="hidden sm:flex items-center -space-x-2 mr-2">
                {participants.slice(0, 5).map((p, i) => (
                  <div key={i} title={p} className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/40 border-2 border-white dark:border-slate-900 flex items-center justify-center text-[10px] font-black text-blue-600 shadow-sm">
                    {p[0]}
                  </div>
                ))}
              </div>
            )}
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-2xl text-slate-400 hover:text-blue-600 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (activeChatId && participants.length < 5) {
                    setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

