import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) containerRef.current.scrollTop = containerRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link interrupted. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    try {
      const shareData = {
        title: currentChat.title,
        messages: currentChat.messages,
        participants: currentChat.participants
      };
      // Robust UTF-8 to Base64 conversion
      const str = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(str)));
      const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
      navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Link generation failed", err);
    }
  };

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'Clorea 3.0', desc: 'Expert Pro Logic', color: 'bg-indigo-600' },
    { id: 'gemini-3-flash-preview', label: 'Clora 3.0', desc: 'Fast Flash Core', color: 'bg-blue-600' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900 transition-colors duration-500 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-48 scroll-smooth transition-all duration-700 ${
          hasMessages ? 'pb-44 pt-8' : 'flex flex-col items-center justify-center pt-10 pb-40'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up transition-all duration-1000">
             <div className="w-20 h-20 sm:w-24 sm:h-24 mb-6 shadow-premium rounded-[2rem] bg-blue-600 flex items-center justify-center transition-all hover:scale-105 duration-500 group shadow-lg">
                <BotIcon className="w-12 h-12 sm:w-16 sm:h-16 transition-transform group-hover:rotate-6" />
             </div>
             <h2 className="text-3xl sm:text-4xl font-black text-slate-900 dark:text-white tracking-tighter mb-2 italic text-center">Clora Intelligence.</h2>
             <p className="text-slate-500 dark:text-slate-400 text-base sm:text-lg font-medium leading-relaxed text-center max-w-xs px-6">
               Ready for your next big idea. Let's build together.
             </p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-md transition-transform hover:scale-110 ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 sm:px-6 sm:py-3.5 text-[14px] sm:text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[1.6rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.6rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-2xl overflow-hidden border-2 border-white dark:border-slate-800 shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain" alt="Visual Link" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Scanning Grid...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 sm:gap-6 items-center">
                <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2"/></div>
                <div className="flex gap-1.5">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* DYNAMIC INPUT DOCK - IMPROVED CENTERED TO BOTTOM TRANSITION */}
      <div className={`fixed left-0 right-0 p-4 sm:p-6 lg:pl-80 z-50 pointer-events-none transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) ${
        hasMessages ? 'bottom-0' : 'bottom-1/3 sm:bottom-1/2 translate-y-20'
      }`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="relative">
            {/* Glow effect */}
            <div className="absolute -inset-1 bg-blue-500/10 rounded-[1.8rem] blur-xl opacity-100 transition duration-500"></div>

            <div className="relative bg-white/98 dark:bg-slate-900/98 backdrop-blur-3xl border border-slate-200/50 dark:border-blue-900/40 rounded-[1.6rem] p-1.5 shadow-premium transition-all">

              {selectedImage && (
                <div className="px-4 py-2 flex items-center gap-3 animate-slide-up border-b border-blue-50 dark:border-blue-900/10 mb-1">
                    <div className="relative w-10 h-10 rounded-xl overflow-hidden shadow-lg">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-red-600/80 text-white flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                        <span className="font-bold text-[10px]">×</span>
                      </button>
                    </div>
                </div>
              )}

              <div className="flex flex-col">
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={() => fileRef.current?.click()}
                      className="w-8 h-8 sm:w-9 sm:h-9 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 transition-all rounded-full"
                    >
                      <ImageIcon className="w-4.5 h-4.5" />
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) {
                          const r = new FileReader();
                          r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                          r.readAsDataURL(f);
                        }
                      }} />
                    </button>

                    <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={e => {
                        setInput(e.target.value);
                        e.target.style.height = 'auto';
                        e.target.style.height = Math.min(e.target.scrollHeight, 150) + 'px';
                      }}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                      placeholder="Ask Clora..."
                      className="flex-1 bg-transparent border-none outline-none resize-none py-2 px-2 text-[14px] sm:text-[15px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-medium max-h-[150px] min-h-[36px] leading-relaxed"
                      rows={1}
                    />

                    <button 
                      onClick={handleSend}
                      disabled={isLoading || (!input.trim() && !selectedImage)}
                      className="w-8 h-8 sm:w-9 sm:h-9 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 active:scale-95 transition-all shadow-md hover:bg-blue-500"
                    >
                      <SendIcon className="w-4 h-4 sm:w-4.5 sm:h-4.5" />
                    </button>
                  </div>

                  <div className="flex items-center justify-between px-2 pb-1 pt-1 mt-0.5 border-t border-slate-50 dark:border-blue-900/10">
                    <div className="flex items-center gap-1.5">
                        <button 
                          onClick={() => setShowModelMenu(true)}
                          className="flex items-center gap-1 px-2 py-1 rounded-xl bg-slate-50 dark:bg-blue-900/20 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all border border-transparent hover:border-blue-100 dark:hover:border-blue-900/30"
                        >
                          <span className="text-[9px] font-black uppercase tracking-tight italic">{activeModelData.label}</span>
                          <svg className="w-2.5 h-2.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                        </button>
                    </div>

                    <div className="flex items-center gap-4">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1 px-2 py-1 rounded-xl text-[9px] font-black uppercase transition-all
                          ${isSearchEnabled ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        <div className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600 animate-pulse' : 'bg-slate-300'}`}></div>
                        Search
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1 text-[9px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-3.5 h-3.5" />
                        <span className="opacity-60">{participants.length}</span>
                      </button>
                    </div>
                  </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* SWIPE UP MODEL POPUP */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[2.5rem] p-6 sm:p-8 shadow-2xl animate-slide-up-pop border-t border-slate-100 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1 bg-slate-200 dark:bg-slate-800 rounded-full mx-auto mb-6" />
            <div className="flex items-center justify-between mb-6 px-1">
              <h3 className="text-xl font-black italic tracking-tighter text-slate-900 dark:text-white">Switch Intelligence.</h3>
              <button onClick={() => setShowModelMenu(false)} className="w-8 h-8 flex items-center justify-center bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400 transition-all">&times;</button>
            </div>
            <div className="grid grid-cols-1 gap-3">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id}
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }}
                   className={`flex items-start gap-4 p-4 rounded-[1.5rem] transition-all border-2 text-left group
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800 bg-white dark:bg-slate-800 hover:border-slate-200'}`}
                 >
                   <div className={`w-10 h-10 shrink-0 rounded-xl ${opt.color} flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-110`}>
                      <SparklesIcon className="w-5 h-5" />
                   </div>
                   <div className="flex-1">
                      <p className="text-base font-black tracking-tight text-slate-900 dark:text-white">{opt.label}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{opt.desc}</p>
                   </div>
                   {model === opt.id && <div className="w-2.5 h-2.5 bg-blue-600 rounded-full shadow-glow self-center"></div>}
                 </button>
               ))}
            </div>
            <p className="text-center text-[9px] font-black uppercase tracking-widest text-slate-400 mt-8 opacity-60">Persistent engine selection for this session.</p>
          </div>
        </div>
      )}

      {/* SHARE MODAL - RE-STYLED */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2rem] p-8 shadow-2xl border border-blue-50/50 dark:border-blue-900/50" onClick={e => e.stopPropagation()}>
            <div className="w-14 h-14 bg-blue-600 rounded-[1.4rem] flex items-center justify-center text-white shadow-2xl mb-6 mx-auto">
              <UsersIcon className="w-7 h-7" />
            </div>
            <h3 className="text-2xl font-black italic text-center mb-1 tracking-tighter text-slate-900 dark:text-white">Collective.</h3>
            <p className="text-slate-500 text-center mb-8 font-medium text-xs px-2">Invite peers to your neural link.</p>

            <button 
              onClick={generateShareLink}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-blue-500/10 active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              <CopyIcon className="w-5 h-5" />
              {copied ? 'Link Copied!' : 'Generate Invite'}
            </button>

            <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800">
               <div className="flex flex-wrap gap-2 justify-center">
                  {participants.map((p, i) => (
                    <div key={i} className="px-3 py-1.5 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-lg text-[8px] font-black uppercase italic border border-slate-100 dark:border-slate-700">
                      {p}
                    </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

