import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link interrupted. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    try {
      const shareData = {
        title: currentChat.title,
        messages: currentChat.messages,
        participants: currentChat.participants
      };
      const str = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(str)));
      const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
      navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Link generation failed", err);
    }
  };

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'CLOREA 3.0', desc: 'Expert Pro Logic', color: 'bg-indigo-600' },
    { id: 'gemini-3-flash-preview', label: 'CLORA 3.0', desc: 'Fast Flash Core', color: 'bg-blue-600' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  const handleAddParticipantLocal = (e: React.FormEvent) => {
    e.preventDefault();
    if (newParticipant.trim()) {
      onAddParticipant(newParticipant.trim());
      setNewParticipant('');
    }
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] transition-colors duration-500 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-48 scroll-smooth transition-all duration-700 ${
          hasMessages ? 'pb-44 pt-8' : 'flex flex-col items-center justify-center min-h-full pb-60'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center">
             <h2 className="text-5xl sm:text-7xl font-black text-slate-900 dark:text-white tracking-tighter mb-6 italic leading-none drop-shadow-sm">What's your plan today?</h2>
             <p className="text-slate-400 dark:text-slate-600 text-[11px] sm:text-sm font-black uppercase tracking-[0.5em] opacity-70">
               Cognix Core Online
             </p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-10">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-md ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 sm:px-6 sm:py-3.5 text-[14px] sm:text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[1.6rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.6rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-2xl overflow-hidden border-2 border-white dark:border-slate-800 shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain" alt="Asset" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest italic">Scanning Network...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 sm:gap-6 items-center">
                <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2"/></div>
                <div className="flex gap-1.5">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* PILL-STYLE INPUT DOCK */}
      <div className={`fixed left-0 right-0 p-4 sm:p-8 lg:pl-80 z-[60] pointer-events-none transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) ${
        hasMessages ? 'bottom-0' : 'bottom-16 sm:bottom-28 translate-y-0'
      }`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="relative group">
            <div className="absolute -inset-1 bg-slate-200/10 dark:bg-blue-900/5 rounded-[2.5rem] blur-2xl opacity-100"></div>

            <div className="relative bg-white dark:bg-slate-900 border border-slate-100 dark:border-white/5 rounded-[2.5rem] p-3 sm:p-5 shadow-premium transition-all">

              {selectedImage && (
                <div className="px-4 py-2 flex items-center gap-3 animate-slide-up border-b border-slate-50 dark:border-slate-800/50 mb-3">
                    <div className="relative w-12 h-12 rounded-xl overflow-hidden shadow-sm border border-slate-100 dark:border-slate-700">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-xl hover:bg-red-700 transition-colors">
                        <span className="text-[10px] font-black">×</span>
                      </button>
                    </div>
                </div>
              )}

              <div className="flex items-center gap-4">
                  <button 
                    onClick={() => fileRef.current?.click()}
                    className="w-12 h-12 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 transition-all rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800"
                  >
                    <ImageIcon className="w-8 h-8" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                  </button>

                  <textarea 
                    ref={textareaRef}
                    value={input}
                    onChange={e => {
                      setInput(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                    }}
                    onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Ask Clora anything..."
                    className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-[16px] sm:text-[18px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-semibold max-h-[120px] min-h-[48px] leading-relaxed"
                    rows={1}
                  />

                  <button 
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !selectedImage)}
                    className="w-12 h-12 shrink-0 bg-slate-50 dark:bg-slate-800/50 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-full flex items-center justify-center disabled:opacity-30 active:scale-95 transition-all border border-slate-100/50 dark:border-white/5"
                  >
                    <SendIcon className="w-6 h-6" />
                  </button>
              </div>

              <div className="flex items-center justify-between mt-3 px-2 sm:px-4">
                  <button 
                    onClick={() => setShowModelMenu(true)}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all group"
                  >
                    <span className="text-[10px] font-black uppercase tracking-tight italic group-hover:underline">{activeModelData.label}</span>
                    <svg className="w-2.5 h-2.5 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                  </button>

                  <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest transition-all
                          ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-300'}`}></div>
                        Search
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-2 text-[10px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-4 h-4" />
                        <span className="opacity-80 font-bold">{participants.length}</span>
                      </button>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[9px] text-slate-300 dark:text-slate-700 mt-6 font-black uppercase tracking-[0.4em] italic pointer-events-none">Cognix Protocol v10.0</p>
        </div>
      </div>

      {/* MODAL & MENU COMPONENTS (SAME AS BEFORE BUT REFINED) */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[2.5rem] p-6 sm:p-10 shadow-2xl animate-slide-up-pop border-t border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1 bg-slate-200 dark:bg-slate-800 rounded-full mx-auto mb-8" />
            <h3 className="text-2xl font-black italic tracking-tighter text-slate-900 dark:text-white uppercase mb-8">Engine Config.</h3>
            <div className="grid grid-cols-1 gap-3">
               {modelOptions.map(opt => (
                 <button key={opt.id} onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} className={`flex items-start gap-5 p-5 rounded-[1.8rem] transition-all border-2 text-left group ${model === opt.id ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' : 'border-slate-50 dark:border-slate-800 bg-white dark:bg-slate-800 hover:border-slate-200'}`}>
                   <div className={`w-12 h-12 shrink-0 rounded-2xl ${opt.color} flex items-center justify-center text-white shadow-lg`}><SparklesIcon className="w-6 h-6" /></div>
                   <div className="flex-1"><p className="text-lg font-black tracking-tight text-slate-900 dark:text-white uppercase italic">{opt.label}</p><p className="text-[11px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest mt-0.5">{opt.desc}</p></div>
                   {model === opt.id && <div className="w-3 h-3 bg-blue-600 rounded-full shadow-glow self-center ring-4 ring-blue-500/10"></div>}
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}

      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.5rem] p-10 shadow-2xl border border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-blue-600 rounded-[1.6rem] flex items-center justify-center text-white shadow-2xl mb-8 mx-auto"><UsersIcon className="w-8 h-8" /></div>
            <h3 className="text-3xl font-black italic text-center mb-1 tracking-tighter text-slate-900 dark:text-white uppercase">Sync Peers.</h3>
            <p className="text-slate-500 dark:text-slate-400 text-center mb-8 font-medium text-sm px-4">Cluster up to 5 nodes in this session.</p>

            <form onSubmit={handleAddParticipantLocal} className="mb-6 flex gap-2">
                <input value={newParticipant} onChange={(e) => setNewParticipant(e.target.value)} placeholder="New peer name..." className="flex-1 bg-slate-50 dark:bg-slate-800 rounded-xl px-4 py-2.5 text-xs font-bold border border-slate-100 dark:border-slate-700 outline-none focus:border-blue-500" />
                <button type="submit" className="bg-blue-600 text-white px-4 rounded-xl text-[10px] font-black uppercase tracking-widest">Add</button>
            </form>

            <button onClick={generateShareLink} className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-4 hover:opacity-90">
              <CopyIcon className="w-5 h-5" /> {copied ? 'Link Copied' : 'Invite Node'}
            </button>

            <div className="mt-8 pt-6 border-t border-slate-50 dark:border-white/5 flex flex-wrap gap-2.5 justify-center">
                {participants.map((p, i) => (
                <div key={i} className="px-4 py-2 bg-slate-50 dark:bg-white/5 text-slate-600 dark:text-slate-300 rounded-xl text-[9px] font-black uppercase italic border border-slate-100 dark:border-slate-800">{p}</div>
                ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-pro-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Clora, your friendly AI companion. I talk like a real person—warm, smart, and down-to-earth. I'm here to help you build, learn, or just chill and brainstorm. Let's make something awesome!");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  // Track participants for a new chat before it's saved to history
  const [tempParticipants, setTempParticipants] = useState<string[]>(['You']);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat ? currentChat.participants : tempParticipants;

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const binary = atob(sharedData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const decoded = JSON.parse(new TextDecoder().decode(bytes));

        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Chat',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared chat", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
    // If switching to an existing chat, clear temp participants
    if (currentChat) setTempParticipants(['You']);
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Session';
        // When first message is sent, merge temp participants into new session
        setChatHistory([{ id: newId, title, messages: next, participants: tempParticipants }, ...chatHistory]);
        setActiveChatId(newId);
        setTempParticipants(['You']);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    setTempParticipants(['You']);
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'Brain';
      case 'coding': return 'Lab';
      case 'live': return 'Talk';
      case 'community': return 'Squad';
      default: return 'Clora';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-14 sm:h-16 flex items-center justify-between px-4 sm:px-10 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-2 sm:gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-600 transition-all">
              <MenuIcon className="w-5 h-5 sm:w-6 sm:h-6"/>
            </button>
            <div className="flex items-center gap-2 sm:gap-3">
              <BotIcon className="w-8 h-8 sm:w-10 sm:h-10 transition-transform active:scale-90 cursor-pointer" onClick={handleNewChat} />
              <div className="h-4 w-[1px] bg-slate-200 dark:bg-slate-700 mx-1 sm:mx-2"></div>
              <span className="text-[13px] sm:text-base font-black text-slate-900 dark:text-white tracking-tighter italic uppercase">{getModeLabel(mode)}</span>
            </div>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-9 h-9 sm:w-10 sm:h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-2xl text-slate-400 hover:text-blue-600 transition-all active:scale-95 shadow-sm"
            >
              <UserIcon className="w-4.5 h-4.5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (participants.length < 5) {
                    if (activeChatId) {
                      setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                    } else {
                      setTempParticipants(prev => [...prev, name]);
                    }
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

