import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      const history = messages.slice(-12).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link interrupted. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const generateShareLink = () => {
    if (!currentChat) return;
    try {
      const shareData = {
        title: currentChat.title,
        messages: currentChat.messages,
        participants: currentChat.participants
      };
      const str = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(str)));
      const url = `${window.location.origin}${window.location.pathname}?share=${encoded}`;
      navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Link generation failed", err);
    }
  };

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'CLOREA 3.0', desc: 'Expert Pro Logic', color: 'bg-indigo-600' },
    { id: 'gemini-3-flash-preview', label: 'CLORA 3.0', desc: 'Fast Flash Core', color: 'bg-blue-600' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  const handleAddParticipantLocal = (e: React.FormEvent) => {
    e.preventDefault();
    if (newParticipant.trim()) {
      onAddParticipant(newParticipant.trim());
      setNewParticipant('');
    }
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] transition-colors duration-500 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-8 md:px-16 lg:px-32 xl:px-48 scroll-smooth transition-all duration-700 ${
          hasMessages ? 'pb-44 pt-8' : 'flex flex-col items-center justify-center min-h-full pb-60 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center">
             <h2 className="text-5xl sm:text-7xl font-black text-slate-900 dark:text-white tracking-tighter mb-6 italic leading-none drop-shadow-xl select-none">What's your plan today?</h2>
             <p className="text-slate-400 dark:text-slate-600 text-[11px] sm:text-sm font-black uppercase tracking-[0.5em] opacity-80 select-none">
               Clora Core is online
             </p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-10 w-full">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-2xl flex items-center justify-center shadow-md ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4 sm:w-5 sm:h-5"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 sm:px-6 sm:py-3.5 text-[14px] sm:text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[1.6rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.6rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-2xl overflow-hidden border-2 border-white dark:border-slate-800 shadow-xl bg-white dark:bg-slate-800">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain" alt="Asset" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/10 rounded-full border border-blue-100 dark:border-blue-800/30 mt-1">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest italic">Scanning Network...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-4 sm:gap-6 items-center">
                <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2"/></div>
                <div className="flex gap-1.5">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* PILL-STYLE INPUT DOCK MATCHING SCREENSHOT */}
      <div className={`fixed left-0 right-0 p-4 sm:p-8 lg:pl-80 z-[60] pointer-events-none transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) ${
        hasMessages ? 'bottom-0' : 'bottom-16 sm:bottom-28 translate-y-0'
      }`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="relative group">
            {/* Soft Glow */}
            <div className="absolute -inset-1 bg-blue-500/5 dark:bg-blue-900/5 rounded-[3rem] blur-2xl opacity-100 pointer-events-none"></div>

            <div className="relative bg-white dark:bg-slate-900 border border-slate-100 dark:border-white/5 rounded-[2.8rem] p-3 sm:p-5 shadow-premium transition-all">

              {selectedImage && (
                <div className="px-4 py-2 flex items-center gap-3 animate-slide-up border-b border-slate-50 dark:border-slate-800/50 mb-3">
                    <div className="relative w-12 h-12 rounded-xl overflow-hidden shadow-sm border border-slate-100 dark:border-slate-700">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-xl hover:bg-red-700 transition-colors">
                        <span className="text-[10px] font-black">×</span>
                      </button>
                    </div>
                </div>
              )}

              {/* Main Input Field Row */}
              <div className="flex items-center gap-3 sm:gap-4 px-1">
                  <button 
                    onClick={() => fileRef.current?.click()}
                    className="w-11 h-11 sm:w-12 sm:h-12 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 transition-all rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-800"
                    title="Attach Media"
                  >
                    <ImageIcon className="w-7 h-7 sm:w-8 sm:h-8" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                  </button>

                  <textarea 
                    ref={textareaRef}
                    value={input}
                    onChange={e => {
                      setInput(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                    }}
                    onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Ask Clora anything..."
                    className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-[16px] sm:text-[18px] text-slate-800 dark:text-slate-100 placeholder-slate-300 font-bold max-h-[120px] min-h-[48px] leading-relaxed"
                    rows={1}
                  />

                  <button 
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !selectedImage)}
                    className="w-11 h-11 sm:w-12 sm:h-12 shrink-0 bg-slate-50 dark:bg-slate-800/80 text-slate-300 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-full flex items-center justify-center disabled:opacity-20 active:scale-90 transition-all border border-slate-100/50 dark:border-white/5"
                  >
                    <SendIcon className="w-5 h-5 sm:w-6 sm:h-6" />
                  </button>
              </div>

              {/* Toolbar Sub-Row */}
              <div className="flex items-center justify-between mt-3 px-3 sm:px-5">
                  <button 
                    onClick={() => setShowModelMenu(true)}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all group"
                  >
                    <span className="text-[10px] font-black uppercase tracking-tight italic group-hover:underline">{activeModelData.label}</span>
                    <svg className="w-2 h-2 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                  </button>

                  <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all
                          ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        <span className="opacity-60">•</span> SEARCH
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-2 text-[10px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-4 h-4" />
                        <span className="opacity-80 font-bold">{participants.length}</span>
                      </button>
                  </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* SWIPE UP ENGINE POPUP */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[100] flex items-end justify-center p-4 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[3rem] p-6 sm:p-10 shadow-2xl animate-slide-up-pop border-t border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1 bg-slate-100 dark:bg-slate-800 rounded-full mx-auto mb-10" />
            <h3 className="text-2xl font-black italic tracking-tighter text-slate-900 dark:text-white uppercase mb-8 px-2">Engine Pulse.</h3>
            <div className="grid grid-cols-1 gap-3">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id} 
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                   className={`flex items-start gap-5 p-6 rounded-[2rem] transition-all border-2 text-left group
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800 bg-white dark:bg-slate-800 hover:border-slate-200 dark:hover:border-slate-700'}`}
                 >
                   <div className={`w-12 h-12 shrink-0 rounded-2xl ${opt.color} flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-105`}><SparklesIcon className="w-6 h-6" /></div>
                   <div className="flex-1">
                      <p className="text-lg font-black tracking-tight text-slate-900 dark:text-white uppercase italic">{opt.label}</p>
                      <p className="text-[11px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest mt-1">{opt.desc}</p>
                   </div>
                   {model === opt.id && <div className="w-3 h-3 bg-blue-600 rounded-full shadow-glow self-center ring-4 ring-blue-500/10"></div>}
                 </button>
               ))}
            </div>
            <p className="text-center text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mt-12 opacity-40">Persistence cluster session active.</p>
          </div>
        </div>
      )}

      {/* SYNC PEERS (SHARE) MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.8rem] p-10 shadow-2xl border border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-blue-600 rounded-[1.8rem] flex items-center justify-center text-white shadow-2xl mb-8 mx-auto transition-transform hover:rotate-6"><UsersIcon className="w-8 h-8" /></div>
            <h3 className="text-3xl font-black italic text-center mb-2 tracking-tighter text-slate-900 dark:text-white uppercase">Sync Peers.</h3>
            <p className="text-slate-500 dark:text-slate-400 text-center mb-8 font-medium text-sm px-4">Assemble up to 5 nodes in this session.</p>

            <form onSubmit={handleAddParticipantLocal} className="mb-6 flex gap-2">
                <input 
                  value={newParticipant} 
                  onChange={(e) => setNewParticipant(e.target.value)} 
                  placeholder="Peer identity..." 
                  className="flex-1 bg-slate-50 dark:bg-slate-800 rounded-xl px-5 py-3 text-xs font-bold border border-slate-100 dark:border-slate-700 outline-none focus:border-blue-500 transition-all placeholder-slate-300" 
                />
                <button type="submit" className="bg-blue-600 text-white px-5 rounded-xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all">Add</button>
            </form>

            <button 
              onClick={generateShareLink} 
              className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4.5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-4 hover:opacity-90 active:scale-[0.98] transition-all"
            >
              <CopyIcon className="w-5 h-5" /> {copied ? 'Link Copied' : 'Invite Node'}
            </button>

            <div className="mt-8 pt-8 border-t border-slate-50 dark:border-white/5">
                <div className="flex flex-wrap gap-2.5 justify-center">
                    {participants.map((p, i) => (
                    <div key={i} className="px-4 py-2 bg-slate-50 dark:bg-white/5 text-slate-600 dark:text-slate-300 rounded-xl text-[9px] font-black uppercase italic border border-slate-100 dark:border-slate-800 shadow-sm">
                      {p}
                    </div>
                    ))}
                </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

