        { id: 'math', label: 'Logic Node', icon: <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 00-1 1v1H8a1 1 0 000 2h1v1a1 1 0 002 0V6h1a1 1 0 100-2h-1V3a1 1 0 00-1-1zM4 11a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1z"/></svg>, desc: 'Complex reasoning' },
        { id: 'debug', label: 'Code Debugger', icon: <CodeIcon className="w-4 h-4"/>, desc: 'Fix programming errors' },
        { id: 'story', label: 'Story Architect', icon: <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M19,2L14,6.5V17.5L19,13V2M6.5,5C4.55,5 2.45,5.4 1,6.5V21C2.45,19.9 4.55,19.5 6.5,19.5C8.45,19.5 10.55,19.9 12,21C13.45,19.9 15.55,19.5 17.5,19.5C19.45,19.5 21.55,19.9 23,21V6.5C21.55,5.4 19.45,5 17.5,5C15.55,5 13.45,5.4 12,6.5C10.55,5.4 8.45,5 6.5,5Z" /></svg>, desc: 'Creative writing engine' },
        { id: 'tone', label: 'Style Shift', icon: <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M7.5,2C5.57,2 4,3.57 4,5.5V14.5C4,16.43 5.57,18 7.5,18H16.5C18.43,18 20,16.43 20,14.5V5.5C20,3.57 18.43,2 16.5,2H7.5M7.5,4H16.5C17.33,4 18,4.67 18,5.5V14.5C18,15.33 17.33,16 16.5,16H7.5C6.67,16 6,15.33 6,14.5V5.5C6,4.67 6.67,4 7.5,4M8,7V9H16V7H8M8,11V13H13V11H8Z" /></svg>, desc: 'Transform writing tone' },
        { id: 'data', label: 'Data Pulse', icon: <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M16,6L18.29,8.29L13.41,13.17L9.41,9.17L2,16.59L3.41,18L9.41,12L13.41,16L19.71,9.71L22,12V6H16Z" /></svg>, desc: 'Analyze raw information' },
        { id: 'explain', label: 'Explain-it', icon: <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M12,17L7,12H10V8H14V12H17L12,17Z" /></svg>, desc: 'Simplify complex ideas' }
    ];

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-6 sm:p-12 animate-fade-in custom-scrollbar">
            <div className="max-w-5xl mx-auto space-y-12">
