                    <h2 className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter italic leading-none mb-3">Lab.</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-medium text-lg">Specialized tools for high-precision intelligence tasks.</p>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {tools.map(tool => (
