import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { FriendsView } from './components/FriendsView';
import { MemoryView } from './components/MemoryView';
import { AboutUs } from './components/AboutUs';
import { CodingView } from './components/CodingView';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, AccentColor, ThemeColors, ModelType, Friend } from './types';

const THEME: ThemeColors = {
    primary: 'bg-blue-600',
    primaryHover: 'hover:bg-blue-700',
    text: 'text-blue-600',
    textDark: 'text-blue-100',
    bgSoft: 'bg-blue-50',
    darkBgSoft: 'dark:bg-blue-900/40',
    border: 'border-blue-200 dark:border-blue-800',
    ring: 'focus:ring-blue-500',
    gradient: 'bg-gradient-to-r from-blue-600 to-blue-500'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-pro-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your elite AI companion. I provide high-fidelity intelligence with a warm, human-centric approach. Whether you're building software, architecting ideas, or exploring the future, I'm your dedicated partner. Let's create something extraordinary.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [tempParticipants, setTempParticipants] = useState<string[]>(['You']);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const participants = currentChat ? currentChat.participants : tempParticipants;

  useEffect(() => {
    const saved = localStorage.getItem('cognix_v8_history');
    if (saved) setChatHistory(JSON.parse(saved));

    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        const binary = atob(sharedData);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const decoded = JSON.parse(new TextDecoder().decode(bytes));

        const newId = 'shared-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Session',
          messages: decoded.messages || [],
          participants: [...(decoded.participants || []), 'Guest Node']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Failed to load shared session", e);
      }
    }

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
    if (currentChat) setTempParticipants(['You']);
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) + (titleText.length > 40 ? '...' : '') : 'New Session';
        setChatHistory([{ id: newId, title, messages: next, participants: tempParticipants }, ...chatHistory]);
        setActiveChatId(newId);
        setTempParticipants(['You']);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    setTempParticipants(['You']);
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  const getModeLabel = (m: Mode) => {
    switch(m) {
      case 'chat': return 'CORE';
      case 'coding': return 'LAB';
      case 'live': return 'LIVE';
      case 'community': return 'SYNC';
      default: return 'COGNIX';
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-14 sm:h-18 flex items-center justify-between px-4 sm:px-12 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border-b border-slate-100 dark:border-slate-800/50">
          <div className="flex items-center gap-3 sm:gap-6">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-blue-600 transition-all">
              <MenuIcon className="w-5 h-5 sm:w-7 sm:h-7"/>
            </button>
            <div className="flex items-center gap-2 sm:gap-4">
              <BotIcon className="w-9 h-9 sm:w-11 sm:h-11 transition-transform active:scale-90 cursor-pointer shadow-xl rounded-full" onClick={handleNewChat} />
              <div className="h-5 w-[1px] bg-slate-200 dark:bg-slate-800 mx-1 sm:mx-3"></div>
              <span className="text-[14px] sm:text-lg font-black text-slate-900 dark:text-white tracking-tighter italic uppercase">{getModeLabel(mode)}</span>
            </div>
          </div>

          <div className="flex items-center gap-4 sm:gap-8">
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 sm:w-12 sm:h-12 flex items-center justify-center bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-2xl text-slate-400 hover:text-blue-600 transition-all active:scale-95 shadow-sm border border-slate-100 dark:border-white/5"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={participants}
                onAddParticipant={(name) => {
                  if (participants.length < 5) {
                    if (activeChatId) {
                      setChatHistory(prev => prev.map(c => c.id === activeChatId ? { ...c, participants: [...c.participants, name] } : c));
                    } else {
                      setTempParticipants(prev => [...prev, name]);
                    }
                  }
                }}
                currentChat={currentChat}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'coding' && <CodingView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        uiStyle="modern" setUiStyle={() => {}}
        accentColor="blue" setAccentColor={() => {}}
        fontSize="normal" setFontSize={() => {}}
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'gemini-3-pro-preview'      // Cognix Pro
  | 'gemini-3-flash-preview'    // Cognix Rápido
  | 'gemini-flash-lite-latest'  // Cognix Lite
  | 'gemini-2.5-flash-image';   // Cognix Creative

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; 
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingStep, setLoadingStep] = useState<0 | 1 | 2>(0); 
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading, loadingStep]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);
    setLoadingStep(1); 

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      // Simulation of dual-core thinking
      await new Promise(r => setTimeout(r, 600));
      setLoadingStep(2); 
      await new Promise(r => setTimeout(r, 500));

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Uplink failure. Please re-engage." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
      setLoadingStep(0);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'PRO 3.0', desc: 'Expert Logic', color: 'bg-indigo-600' },
    { id: 'gemini-3-flash-preview', label: 'RÁPIDO', desc: 'Hyper-Fast', color: 'bg-blue-600' },
    { id: 'gemini-flash-lite-latest', label: 'LITE 1.0', desc: 'Efficient', color: 'bg-slate-700' },
    { id: 'gemini-2.5-flash-image', label: 'CREATIVE', desc: 'Gen-Image', color: 'bg-emerald-600' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  const handleAddParticipantLocal = (e: React.FormEvent) => {
    e.preventDefault();
    if (newParticipant.trim()) {
      onAddParticipant(newParticipant.trim());
      setNewParticipant('');
    }
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] transition-all duration-300 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-12">
             <h2 className="text-4xl sm:text-7xl font-black text-slate-900 dark:text-white tracking-[-0.05em] mb-4 italic leading-tight drop-shadow-xl transition-all">What's your plan today?</h2>
             <div className="flex items-center gap-3 mt-4 opacity-40">
                <div className="h-[1px] w-6 bg-blue-500"></div>
                <p className="text-slate-400 dark:text-slate-500 text-[10px] font-black uppercase tracking-[0.5em] italic">
                  Cognix Systems Active
                </p>
                <div className="h-[1px] w-6 bg-blue-500"></div>
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8 w-full">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-7 h-7 sm:w-10 sm:h-10 shrink-0 rounded-xl flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5 sm:p-2"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[88%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-2.5 sm:px-6 sm:py-3.5 text-[15px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'message-bubble-user rounded-[1.6rem] rounded-tr-sm' : 'message-bubble-bot rounded-[1.6rem] rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-3 rounded-2xl overflow-hidden border border-white/10 shadow-lg bg-black/5">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[350px] w-full object-contain" alt="Visual Asset" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-3 py-1 bg-blue-50/50 dark:bg-blue-900/10 rounded-full border border-blue-100/50 dark:border-blue-800/20 mt-1">
                        <div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest italic">Syncing global data...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex flex-col gap-3 animate-slide-up">
                <div className="flex gap-4 items-center">
                  <div className="w-8 h-8 rounded-xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-2"/></div>
                  <div className="flex gap-1.5">
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                  </div>
                </div>
                <div className="ml-12 px-3 py-1.5 rounded-xl bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-white/5 w-fit">
                    <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] flex items-center gap-2">
                        <span className={`w-1.5 h-1.5 rounded-full transition-all ${loadingStep >= 1 ? 'bg-blue-500 shadow-glow' : 'bg-slate-200 dark:bg-slate-700'}`}></span>
                        RÁPIDO ANALYSIS
                        <span className="opacity-10">/</span>
                        <span className={`w-1.5 h-1.5 rounded-full transition-all ${loadingStep >= 2 ? 'bg-indigo-500 shadow-glow' : 'bg-slate-200 dark:bg-slate-700'}`}></span>
                        PRO SYNTHESIS
                    </p>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* COMPACT INPUT DOCK */}
      <div className={`fixed left-0 right-0 p-3 sm:p-6 lg:pl-[280px] z-[60] pointer-events-none transition-all duration-700 ease-out ${
        hasMessages ? 'bottom-0' : 'bottom-12 sm:bottom-24 translate-y-0'
      }`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative group">
            <div className="absolute -inset-1 bg-blue-500/5 dark:bg-blue-900/10 rounded-[2.5rem] blur-2xl opacity-0 group-focus-within:opacity-100 transition-opacity"></div>

            <div className="relative bg-white dark:bg-[#0d111c] border border-slate-100 dark:border-white/10 rounded-[2.2rem] p-2.5 sm:p-4 shadow-xl">

              {selectedImage && (
                <div className="px-3 py-1.5 flex items-center gap-3 animate-slide-up border-b border-slate-50 dark:border-slate-800/50 mb-2">
                    <div className="relative w-12 h-12 rounded-xl overflow-hidden shadow-sm border border-slate-100 dark:border-slate-700">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-xl">
                        <span className="text-[10px] font-black">×</span>
                      </button>
                    </div>
                    <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Image Loaded</span>
                </div>
              )}

              <div className="flex items-center gap-2 sm:gap-3">
                  <button 
                    onClick={() => fileRef.current?.click()}
                    className="w-10 h-10 sm:w-12 sm:h-12 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 transition-all rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800"
                  >
                    <ImageIcon className="w-6 h-6 sm:w-8 sm:h-8" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                  </button>

                  <textarea 
                    ref={textareaRef}
                    value={input}
                    onChange={e => {
                      setInput(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                    }}
                    onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Ask Cognix anything..."
                    className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] sm:text-[17px] text-slate-800 dark:text-slate-100 placeholder-slate-400 dark:placeholder-slate-700 font-semibold max-h-[120px] min-h-[44px] leading-relaxed scrollbar-hide"
                    rows={1}
                  />

                  <button 
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !selectedImage)}
                    className="w-10 h-10 sm:w-12 sm:h-12 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-md shadow-blue-500/20 disabled:opacity-20 active:scale-90 transition-all"
                  >
                    <SendIcon className="w-5 h-5 sm:w-6 sm:h-6" />
                  </button>
              </div>

              <div className="flex items-center justify-between mt-2 px-2 sm:px-4">
                  <button 
                    onClick={() => setShowModelMenu(true)}
                    className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all group"
                  >
                    <span className="text-[9px] font-black uppercase tracking-tight italic">{activeModelData.label}</span>
                    <svg className="w-2 h-2 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                  </button>

                  <div className="flex items-center gap-5">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest transition-all
                          ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400 hover:text-slate-500'}`}
                      >
                        <span className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600 shadow-glow animate-pulse' : 'bg-slate-300 dark:bg-slate-700'}`}></span> SEARCH
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1.5 text-[9px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-3.5 h-3.5" />
                        <span className="opacity-80 uppercase">{participants.length} Active</span>
                      </button>
                  </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[8px] text-slate-300 dark:text-slate-800 mt-5 font-black uppercase tracking-[0.4em] italic pointer-events-none opacity-40">Cognix Hyper-Logic Hub • v10.2</p>
        </div>
      </div>

      {/* PROFESSIONAL MODEL SELECTOR (MOBILE OPTIMIZED) */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[100] flex items-end justify-center p-0 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-lg rounded-t-[2.5rem] p-6 sm:p-10 shadow-2xl animate-slide-up-pop border-t border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1 bg-slate-100 dark:bg-slate-800 rounded-full mx-auto mb-8" />

            <div className="flex items-center gap-3 mb-8 px-2">
                <SparklesIcon className="w-6 h-6 text-blue-600" />
                <h3 className="text-xl font-black italic tracking-tighter text-slate-900 dark:text-white uppercase">Engine Selection.</h3>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id} 
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                   className={`flex items-start gap-4 p-4 rounded-2xl transition-all border-2 text-left group relative
                     ${model === opt.id 
                       ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-900/20' 
                       : 'border-slate-50 dark:border-slate-800/40 bg-white dark:bg-slate-900/50 hover:border-slate-200'}`}
                 >
                   <div className={`w-10 h-10 shrink-0 rounded-xl ${opt.color} flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-105`}>
                        <SparklesIcon className="w-5 h-5" />
                   </div>
                   <div className="flex-1 overflow-hidden">
                      <p className="text-[13px] font-black tracking-tight text-slate-900 dark:text-white uppercase italic truncate">{opt.label}</p>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest mt-0.5 truncate">{opt.desc}</p>
                   </div>
                   {model === opt.id && (
                       <div className="absolute right-3 top-3">
                           <div className="w-2 h-2 bg-blue-600 rounded-full shadow-glow"></div>
                       </div>
                   )}
                 </button>
               ))}
            </div>

            <p className="text-center text-[9px] font-black uppercase tracking-[0.2em] text-slate-300 dark:text-slate-700 mt-10 opacity-60 italic">Core switching protocol active.</p>
          </div>
        </div>
      )}

      {/* INVITE MODAL (MOBILE OPTIMIZED) */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-2xl mb-8 mx-auto"><UsersIcon className="w-8 h-8" /></div>
            <h3 className="text-2xl font-black italic text-center mb-2 tracking-tighter text-slate-900 dark:text-white uppercase leading-none">Assemble Nodes.</h3>
            <p className="text-slate-400 text-center mb-8 font-bold text-[10px] uppercase tracking-widest opacity-70">Expand your collective node.</p>

            <form onSubmit={handleAddParticipantLocal} className="mb-6 flex gap-2">
                <input 
                  value={newParticipant} 
                  onChange={(e) => setNewParticipant(e.target.value)} 
                  placeholder="ID Peer..." 
                  className="flex-1 bg-slate-50 dark:bg-slate-800/50 rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest border border-slate-100 dark:border-slate-800 outline-none focus:border-blue-500 transition-all placeholder-slate-300" 
                />
                <button type="submit" className="bg-blue-600 text-white px-5 rounded-xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all">Add</button>
            </form>

            <button 
              onClick={() => {
                if (!currentChat) return;
                const shareData = { title: currentChat.title, messages: currentChat.messages, participants: currentChat.participants };
                const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(shareData))));
                navigator.clipboard.writeText(`${window.location.origin}${window.location.pathname}?share=${encoded}`);
                setCopied(true);
                setTimeout(() => setCopied(false), 2000);
              }} 
              className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl flex items-center justify-center gap-3 active:scale-[0.98] transition-all"
            >
              <CopyIcon className="w-4 h-4" /> {copied ? 'COPIED' : 'HANDSHAKE LINK'}
            </button>

            <div className="mt-8 pt-8 border-t border-slate-100 dark:border-white/5 flex flex-wrap gap-2 justify-center">
                {participants.map((p, i) => (
                <div key={i} className="px-3 py-1.5 bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400 rounded-xl text-[9px] font-black uppercase italic border border-slate-100 dark:border-slate-800">
                  {p}
                </div>
                ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, SparklesIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Uplink failure. Please re-engage." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'Gemini 3.0 Flash', desc: 'INSTANT REASONING' },
    { id: 'gemini-3-pro-preview', label: 'CognixV2', desc: 'OPTIMIZED WORKFLOW' },
    { id: 'gemini-flash-lite-latest', label: 'Flash Lite', desc: 'MAXIMUM EFFICIENCY' },
    { id: 'gemini-2.5-flash-image', label: 'CoreaRv1', desc: 'CREATIVE INTELLIGENCE' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  const handleAddParticipantLocal = (e: React.FormEvent) => {
    e.preventDefault();
    if (newParticipant.trim()) {
      onAddParticipant(newParticipant.trim());
      setNewParticipant('');
    }
  };

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] transition-all duration-300 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-12">
             <h2 className="text-3xl sm:text-5xl md:text-6xl font-black text-slate-900 dark:text-white tracking-tight mb-3 leading-tight drop-shadow-sm transition-all">What's your plan today?</h2>
             <div className="flex items-center gap-3 mt-4 opacity-40">
                <p className="text-slate-400 dark:text-slate-500 text-[10px] font-black uppercase tracking-[0.4em] italic">
                  Cognix Terminal Active
                </p>
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-6 w-full">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-7 h-7 sm:w-8 sm:h-8 shrink-0 rounded-lg flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1 sm:p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-2 text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-blue-600 text-white rounded-2xl rounded-tr-sm' : 'bg-slate-50 dark:bg-slate-800/50 text-slate-900 dark:text-slate-200 border border-slate-100 dark:border-slate-800/50 rounded-2xl rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-2 rounded-xl overflow-hidden border border-white/10 shadow-md">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[300px] w-full object-contain" alt="Asset" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-2.5 py-1 bg-blue-50/50 dark:bg-blue-900/10 rounded-full mt-1">
                        <div className="w-1 h-1 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[8px] font-black text-blue-600 uppercase tracking-widest italic">Syncing nodes...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex flex-col gap-2 animate-slide-up">
                <div className="flex gap-3 items-center">
                  <div className="w-7 h-7 rounded-lg bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-1.5"/></div>
                  <div className="flex gap-1">
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                     <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                  </div>
                </div>
                <div className="ml-10 px-3 py-1 rounded-lg bg-slate-50/50 dark:bg-slate-800/30 border border-slate-100 dark:border-white/5 w-fit">
                    <p className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">
                        {activeModelData.label} Thinking...
                    </p>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* COMPACT INPUT DOCK */}
      <div className={`fixed left-0 right-0 p-3 sm:p-5 lg:pl-[280px] z-[60] pointer-events-none transition-all duration-500 ${
        hasMessages ? 'bottom-0' : 'bottom-8 sm:bottom-16 translate-y-0'
      }`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative group">
            <div className="relative bg-white dark:bg-[#0d111c] border border-slate-100 dark:border-white/10 rounded-[2rem] p-2 sm:p-3 shadow-lg">

              {selectedImage && (
                <div className="px-3 py-1 flex items-center gap-2 animate-slide-up border-b border-slate-50 dark:border-slate-800/50 mb-2">
                    <div className="relative w-10 h-10 rounded-lg overflow-hidden border border-slate-100 dark:border-slate-700">
                      <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                      <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-4 h-4 flex items-center justify-center rounded-bl-lg">
                        <span className="text-[8px] font-black">×</span>
                      </button>
                    </div>
                </div>
              )}

              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => fileRef.current?.click()}
                    className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 transition-all rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800"
                  >
                    <ImageIcon className="w-6 h-6" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                  </button>

                  <textarea 
                    ref={textareaRef}
                    value={input}
                    onChange={e => {
                      setInput(e.target.value);
                      e.target.style.height = 'auto';
                      e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                    }}
                    onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Ask Cognix anything..."
                    className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] text-slate-800 dark:text-slate-100 placeholder-slate-400 dark:placeholder-slate-700 font-semibold max-h-[120px] min-h-[40px] leading-relaxed scrollbar-hide"
                    rows={1}
                  />

                  <button 
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !selectedImage)}
                    className="w-10 h-10 shrink-0 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-md disabled:opacity-20 active:scale-90 transition-all"
                  >
                    <SendIcon className="w-5 h-5" />
                  </button>
              </div>

              <div className="flex items-center justify-between mt-1 px-2">
                  <button 
                    onClick={() => setShowModelMenu(true)}
                    className="flex items-center gap-1.5 px-2 py-1 rounded-lg bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all"
                  >
                    <span className="text-[8px] font-black uppercase tracking-tight italic">{activeModelData.label}</span>
                    <svg className="w-2 h-2" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                  </button>

                  <div className="flex items-center gap-4">
                      <button 
                        onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                        className={`flex items-center gap-1 text-[8px] font-black uppercase tracking-widest transition-all
                          ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}
                      >
                        <span className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-300'}`}></span> SEARCH
                      </button>

                      <button 
                        onClick={() => setShowShareModal(true)}
                        className="flex items-center gap-1.5 text-[8px] font-black text-slate-400 hover:text-blue-600 transition-all"
                      >
                        <UsersIcon className="w-3 h-3" />
                        <span className="opacity-80 uppercase">{participants.length} Active</span>
                      </button>
                  </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* VERTICAL LIST MODEL SELECTOR (IMAGE MATCH) */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-sm z-[100] flex items-end justify-center p-0 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-lg rounded-t-[2rem] p-6 shadow-2xl animate-slide-up-pop border-t border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-10 h-1 bg-slate-100 dark:bg-slate-800 rounded-full mx-auto mb-6" />

            <div className="space-y-1">
               {modelOptions.map(opt => (
                 <button 
                   key={opt.id} 
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                   className={`w-full flex flex-col items-start gap-1 p-4 rounded-xl transition-all text-left group
                     ${model === opt.id ? 'bg-slate-50 dark:bg-slate-900/50' : 'hover:bg-slate-50/50 dark:hover:bg-slate-900/30'}`}
                 >
                    <p className={`text-[15px] font-black tracking-tight uppercase leading-none ${model === opt.id ? 'text-blue-600' : 'text-slate-700 dark:text-slate-300'}`}>
                        {opt.label}
                    </p>
                    <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest opacity-60">
                        {opt.desc}
                    </p>
                 </button>
               ))}
            </div>

            <p className="text-center text-[8px] font-black uppercase tracking-[0.2em] text-slate-300 dark:text-slate-700 mt-8 opacity-40">System Core Switch</p>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-sm rounded-[2rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-14 h-14 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl mb-6 mx-auto"><UsersIcon className="w-7 h-7" /></div>
            <h3 className="text-xl font-black italic text-center mb-1 tracking-tight text-slate-900 dark:text-white uppercase leading-none">Collaborate.</h3>
            <p className="text-slate-400 text-center mb-6 font-bold text-[9px] uppercase tracking-widest opacity-70">Expand your local node cluster.</p>

            <form onSubmit={handleAddParticipantLocal} className="mb-6 flex gap-2">
                <input 
                  value={newParticipant} 
                  onChange={(e) => setNewParticipant(e.target.value)} 
                  placeholder="ID Peer..." 
                  className="flex-1 bg-slate-50 dark:bg-slate-800/50 rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest border border-slate-100 dark:border-slate-800 outline-none focus:border-blue-500 transition-all placeholder-slate-300" 
                />
                <button type="submit" className="bg-blue-600 text-white px-5 rounded-xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all">Add</button>
            </form>

            <button 
              onClick={() => {
                if (!currentChat) return;
                const shareData = { title: currentChat.title, messages: currentChat.messages, participants: currentChat.participants };
                const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(shareData))));
                navigator.clipboard.writeText(`${window.location.origin}${window.location.pathname}?share=${encoded}`);
                setCopied(true);
                setTimeout(() => setCopied(false), 2000);
              }} 
              className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg flex items-center justify-center gap-3 active:scale-[0.98] transition-all"
            >
              <CopyIcon className="w-4 h-4" /> {copied ? 'COPIED' : 'INVITE LINK'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SparklesIcon, CodeIcon, CopyIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'prompt' | 'summary' | 'math' | 'debug' | 'story' | 'email' | 'translate' | 'seo'>('prompt');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);

    const runTool = async () => {
        if (!input.trim()) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            switch(activeTool) {
                case 'prompt': instruction = "Refine this prompt for AI engineering excellence. Output ONLY the refined prompt."; break;
                case 'summary': instruction = "Summarize this document into 5 high-precision bullet points."; break;
                case 'math': instruction = "Solve this logic or math problem step-by-step with clear reasoning."; break;
                case 'debug': instruction = "Identify the cause of this error and suggest the exact code fix."; break;
                case 'story': instruction = "Transform this idea into a compelling narrative outline or short creative story segment."; break;
                case 'email': instruction = "Draft a professional, clear, and impactful email based on the following context."; break;
                case 'translate': instruction = "Translate the following text into clear, fluent English, preserving the original tone."; break;
                case 'seo': instruction = "Optimize the following text for SEO, suggesting 5 high-impact keywords and refining readability."; break;
            }

            const response = await ai.models.generateContent({
                model: model,
                contents: `${instruction}\n\nINPUT: "${input}"`,
            });
            setResult(response.text || '');
        } catch (e) {
            setResult('Neural link failed. Please verify input and retry.');
        } finally {
            setLoading(false);
        }
    };

    const tools = [
        { id: 'prompt', label: 'Prompt Studio', desc: 'REFINER' },
        { id: 'summary', label: 'Summarizer', desc: 'CONDENSER' },
        { id: 'math', label: 'Logic Node', desc: 'REASONING' },
        { id: 'debug', label: 'Debugger', desc: 'CODE FIX' },
        { id: 'story', label: 'Architect', desc: 'WRITING' },
        { id: 'email', label: 'Email Drafter', desc: 'PROFESSIONAL' },
        { id: 'translate', label: 'Translator', desc: 'MULTILINGUAL' },
        { id: 'seo', label: 'SEO Pulse', desc: 'OPTIMIZER' }
    ];

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-4xl mx-auto space-y-10">
                <header>
                    <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight uppercase italic leading-none mb-2">Lab.</h2>
                    <p className="text-slate-500 dark:text-slate-400 font-medium text-sm">Specialized neural nodes for high-precision tasks.</p>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-blue-600 bg-blue-50/20 dark:bg-blue-900/10' 
                                    : 'bg-slate-50 dark:bg-slate-900 border-transparent hover:border-slate-200 dark:hover:border-slate-800'}
                            `}
                        >
                            <p className={`text-[12px] font-black uppercase tracking-tight ${activeTool === tool.id ? 'text-blue-600' : 'text-slate-900 dark:text-slate-200'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest opacity-60">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className="space-y-6">
                    <div className="p-6 rounded-[1.5rem] border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-sm space-y-4">
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder={`Inject content for ${activeTool} analysis...`}
                            className="w-full p-4 h-40 rounded-xl bg-slate-50 dark:bg-slate-950 border-none outline-none text-slate-800 dark:text-slate-200 transition-all text-sm leading-relaxed font-medium placeholder-slate-300"
                        />
                        <button 
                            onClick={runTool}
                            disabled={loading || !input.trim()}
                            className={`w-full py-3 rounded-xl font-black text-[10px] uppercase tracking-widest text-white transition-all active:scale-95 bg-blue-600 hover:bg-blue-700 disabled:opacity-20`}
                        >
                            {loading ? 'Synthesizing...' : `Execute ${activeTool}`}
                        </button>
                    </div>

                    {result && (
                        <div className="p-6 rounded-[1.5rem] bg-blue-50/20 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-800/30 animate-fade-in relative">
                            <div className="flex items-center justify-between mb-4">
                                <span className="text-[8px] font-black uppercase tracking-[0.2em] text-blue-600">Sync Complete</span>
                                <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg shadow-sm text-slate-400 hover:text-blue-500 transition-colors">
                                    <CopyIcon className="w-3.5 h-3.5" />
                                </button>
                            </div>
                            <div className="prose dark:prose-invert max-w-none text-slate-800 dark:text-slate-200 font-medium leading-relaxed text-[14px]">
                                {result.split('\n').map((line, i) => <p key={i}>{line}</p>)}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImg = /draw|image|create|generate/i.test(trimmedInput);
      const target = isImg ? 'gemini-2.5-flash-image' : (model === 'gemini-2.5-flash-image' ? 'gemini-3-flash-preview' : model);

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: target,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction,
          tools: isSearchEnabled && !isImg ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "Done!" }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Sync failed. Retry required." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'Gemini 3.0 Flash', desc: 'INSTANT REASONING' },
    { id: 'gemini-3-pro-preview', label: 'CognixV2', desc: 'OPTIMIZED WORKFLOW' },
    { id: 'gemini-3-flash-preview', label: 'CloraN1', desc: 'SYSTEM OPERATIONS' },
    { id: 'gemini-3-pro-preview', label: 'CoreaRv1', desc: 'CREATIVE INTELLIGENCE' },
    { id: 'gemini-flash-lite-latest', label: 'Flash Lite', desc: 'MAXIMUM EFFICIENCY' },
    { id: 'gemini-2.5-flash-image', label: 'Neural Visualizer', desc: 'CREATIVE IMAGE ENGINE' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] transition-all duration-300 relative overflow-hidden">

      {/* Messages Container */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-10">
             <h2 className="text-3xl sm:text-5xl font-black text-slate-900 dark:text-white tracking-tight mb-3 leading-tight transition-all">What's your plan today?</h2>
             <div className="flex items-center gap-2 mt-2 opacity-30">
                <p className="text-[10px] font-black uppercase tracking-[0.4em]">Cognix Active</p>
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-6 w-full">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-3 sm:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-7 h-7 sm:w-8 sm:h-8 shrink-0 rounded-lg flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1 sm:p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-2.5 text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-blue-600 text-white rounded-2xl rounded-tr-sm' : 'bg-slate-50 dark:bg-slate-800/50 text-slate-900 dark:text-slate-200 border border-slate-100 dark:border-slate-800/50 rounded-2xl rounded-tl-sm shadow-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-2 rounded-xl overflow-hidden border border-white/10 shadow-md">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[300px] w-full object-contain" alt="Asset" />
                        </div>
                      )}
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-2.5 py-1 bg-blue-50/50 dark:bg-blue-900/10 rounded-full mt-1">
                        <div className="w-1 h-1 bg-blue-600 rounded-full animate-pulse"></div>
                        <span className="text-[8px] font-black text-blue-600 uppercase tracking-widest italic">Searching...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-3 items-center animate-slide-up">
                <div className="w-7 h-7 rounded-lg bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-center"><BotIcon className="w-full h-full p-1.5"/></div>
                <div className="flex gap-1">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* COMPACT INPUT DOCK */}
      <div className={`fixed left-0 right-0 p-3 sm:p-5 lg:pl-[280px] z-[60] pointer-events-none transition-all duration-500 ${
        hasMessages ? 'bottom-0' : 'bottom-8 sm:bottom-16'
      }`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-100 dark:border-white/10 rounded-[2rem] p-2 sm:p-3 shadow-lg">

            {selectedImage && (
              <div className="px-3 py-1 flex items-center gap-2 border-b border-slate-50 dark:border-slate-800/50 mb-2">
                  <div className="relative w-10 h-10 rounded-lg overflow-hidden border border-slate-100 dark:border-slate-700">
                    <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                    <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-4 h-4 flex items-center justify-center rounded-bl-lg text-[8px] font-black">×</button>
                  </div>
              </div>
            )}

            <div className="flex items-center gap-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-600 rounded-xl transition-all">
                  <ImageIcon className="w-6 h-6" />
                  <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) {
                      const r = new FileReader();
                      r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                      r.readAsDataURL(f);
                    }
                  }} />
                </button>

                <textarea 
                  ref={textareaRef}
                  value={input}
                  onChange={e => {
                    setInput(e.target.value);
                    e.target.style.height = 'auto';
                    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                  }}
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Ask Cognix anything..."
                  className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] text-slate-800 dark:text-slate-100 placeholder-slate-400 font-semibold max-h-[120px] min-h-[40px] scrollbar-hide"
                  rows={1}
                />

                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-md disabled:opacity-20 active:scale-95"
                >
                  <SendIcon className="w-5 h-5" />
                </button>
            </div>

            <div className="flex items-center justify-between mt-1 px-2">
                <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-1.5 px-2 py-1 rounded-lg bg-slate-50 dark:bg-white/5 text-slate-500 dark:text-slate-400">
                  <span className="text-[9px] font-black uppercase tracking-tight">{activeModelData.label}</span>
                  <svg className="w-2 h-2" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                </button>
                <div className="flex items-center gap-4">
                    <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1 text-[8px] font-black uppercase tracking-widest ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}>
                      <span className={`w-1 h-1 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-300'}`}></span> SEARCH
                    </button>
                    <button onClick={() => setShowShareModal(true)} className="flex items-center gap-1.5 text-[8px] font-black text-slate-400">
                      <UsersIcon className="w-3 h-3" />
                      <span className="uppercase">{participants.length} Node</span>
                    </button>
                </div>
            </div>
          </div>
        </div>
      </div>

      {/* REFINED VERTICAL LIST MODEL SELECTOR */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-[320px] rounded-t-[2.5rem] sm:rounded-[2.5rem] p-6 shadow-2xl animate-slide-up-pop border-t sm:border border-slate-100 dark:border-white/5" onClick={e => e.stopPropagation()}>
            <div className="w-10 h-1 bg-slate-100 dark:bg-slate-800 rounded-full mx-auto mb-6 sm:hidden" />

            <div className="space-y-1">
               {modelOptions.map((opt, idx) => (
                 <button 
                   key={`${opt.id}-${idx}`} 
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                   className={`w-full flex flex-col items-start gap-1 p-4 rounded-2xl transition-all text-left group
                     ${model === opt.id && activeModelData.label === opt.label ? 'bg-slate-50 dark:bg-slate-900/50' : 'hover:bg-slate-50/50 dark:hover:bg-slate-900/30'}`}
                 >
                    <p className={`text-[16px] font-bold tracking-tight leading-none ${model === opt.id && activeModelData.label === opt.label ? 'text-blue-600' : 'text-slate-800 dark:text-slate-200'}`}>
                        {opt.label}
                    </p>
                    <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest opacity-80">
                        {opt.desc}
                    </p>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}

      {/* MINIMAL SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-sm rounded-[2rem] p-8 shadow-2xl" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-black text-center mb-6 uppercase tracking-tight">Sync Peer</h3>
            <form onSubmit={(e) => { e.preventDefault(); if(newParticipant.trim()){ onAddParticipant(newParticipant.trim()); setNewParticipant(''); } }} className="flex gap-2">
                <input value={newParticipant} onChange={(e) => setNewParticipant(e.target.value)} placeholder="Node ID..." className="flex-1 bg-slate-50 dark:bg-slate-800/50 rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest border border-slate-100 dark:border-slate-800 outline-none focus:border-blue-500 transition-all" />
                <button type="submit" className="bg-blue-600 text-white px-5 rounded-xl text-[10px] font-black uppercase active:scale-95">Add</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export type Mode = 'chat' | 'live' | 'friends' | 'toolbox' | 'memory' | 'community' | 'coding' | 'about';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';
export type ModelType = 
  | 'gemini-3-pro-preview'      // CognixV2 / CoreaRv1
  | 'gemini-3-flash-preview'    // Gemini 3.0 Flash / CloraN1
  | 'gemini-flash-lite-latest'  // Flash Lite
  | 'gemini-2.5-flash-image';   // Neural Visualizer

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; 
}

import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SparklesIcon, CodeIcon, CopyIcon, ImageIcon, BotIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'runner'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const fileRef = useRef<HTMLInputElement>(null);

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        setResult('');
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            let targetModel = model;

            switch(activeTool) {
                case 'summarizer': 
                    instruction = "Summarize the following content into clear, high-impact bullet points."; 
                    break;
                case 'scanner': 
                    instruction = "Analyze this image and provide a professional, detailed breakdown of its contents and context."; 
                    targetModel = 'gemini-3-flash-preview'; // Flash is great for vision
                    break;
                case 'writer': 
                    instruction = "Act as a professional content writer. Write a comprehensive, engaging article or post based on the following brief."; 
                    break;
                case 'enhancer': 
                    instruction = "Transform this basic AI prompt into a high-fidelity, engineered prompt for maximum output quality. Output ONLY the enhanced prompt."; 
                    break;
                case 'runner': 
                    instruction = "Generate a single-file runnable HTML/Tailwind CSS web snippet based on the following logic or description. Start with <!DOCTYPE html>. No commentary."; 
                    break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModel,
                contents: [{ parts }],
            });
            setResult(response.text || '');
        } catch (e) {
            setResult('Process Interrupted. Check network or input and try again.');
        } finally {
            setLoading(false);
        }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'DOC CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION ANALYSIS' },
        { id: 'writer', label: 'Content Writer', desc: 'CREATIVE ENGINE' },
        { id: 'enhancer', label: 'Prompt Enhancer', desc: 'PROMPT ENGINEERING' },
        { id: 'runner', label: 'Code Runner', desc: 'LIVE EXECUTION' }
    ];

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-4xl mx-auto space-y-10">
                <header>
                    <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight uppercase italic leading-none mb-2">Cognix Lab.</h2>
                    <p className="text-slate-400 dark:text-slate-500 font-bold text-[10px] uppercase tracking-widest">Specialized Nodes for Professional Workflows</p>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); setSelectedImage(null); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-blue-600 bg-blue-50/20 dark:bg-blue-900/10' 
                                    : 'bg-slate-50 dark:bg-slate-900 border-transparent hover:border-slate-200 dark:hover:border-slate-800'}
                            `}
                        >
                            <p className={`text-[13px] font-bold tracking-tight leading-none ${activeTool === tool.id ? 'text-blue-600' : 'text-slate-800 dark:text-slate-200'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest opacity-60">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className="space-y-6">
