                      <span className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-black dark:bg-white' : 'bg-slate-300 dark:bg-slate-700'}`}></span> SEARCH
                    </button>
                    <button onClick={() => setShowShareModal(true)} className="flex items-center gap-1.5 text-[9px] font-bold text-slate-500 hover:text-black dark:hover:text-white transition-colors">
                      <UsersIcon className="w-3.5 h-3.5" />
                      <span className="uppercase">{participants.length} Active</span>
                    </button>
                </div>
            </div>
