        </div>
      </div>

      {/* REFINED VERTICAL LIST MODEL SELECTOR */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-[320px] rounded-t-[2.5rem] sm:rounded-3xl p-6 shadow-2xl animate-slide-up-pop border-t sm:border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
