                     ${model === opt.id && activeModelData.label === opt.label ? 'bg-slate-100 dark:bg-slate-800 text-black dark:text-white' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40 text-slate-700 dark:text-slate-300'}`}
                 >
                    <p className="text-[16px] font-bold tracking-tight leading-none">
                        {opt.label}
