      )}

      {/* SHARE MODAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowShareModal(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-center mb-6 uppercase tracking-tight text-black dark:text-white">Collaborate</h3>
            <form onSubmit={(e) => { e.preventDefault(); if(newParticipant.trim()){ onAddParticipant(newParticipant.trim()); setNewParticipant(''); } }} className="flex gap-2">
                <input value={newParticipant} onChange={(e) => setNewParticipant(e.target.value)} placeholder="Node ID..." className="flex-1 bg-slate-50 dark:bg-slate-900 rounded-xl px-4 py-3 text-[12px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-800 outline-none focus:border-black dark:focus:border-white transition-all placeholder-slate-400" />
                <button type="submit" className="bg-black dark:bg-white text-white dark:text-black px-5 rounded-xl text-[11px] font-bold uppercase active:scale-95 transition-all">Add</button>
            </form>
