import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [newParticipant, setNewParticipant] = useState('');

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    // Bot placeholder starts empty but marks that it's thinking
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");

      const ai = new GoogleGenAI({ apiKey });
      const isImgRequest = /draw|image|create image|generate image/i.test(trimmedInput);

      // Determine model and configuration based on current selection
      let targetModel = model;
      let config: any = { systemInstruction };

      // Performance differentiation
      if (model === 'gemini-3-pro-preview') {
        // High reasoning config for Pro models
        config.thinkingConfig = { thinkingBudget: 32768 };
      } else if (model === 'gemini-flash-lite-latest') {
        // Efficiency config
        config.temperature = 0.4;
      }

      // Route image generation requests
      if (isImgRequest) {
        targetModel = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          ...config,
          tools: isSearchEnabled && !isImgRequest ? [{ googleSearch: {} }] : []
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      console.error(e);
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Connection error. Please try again." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'Gemini 3.0 Flash', desc: 'INSTANT REASONING' },
    { id: 'gemini-3-pro-preview', label: 'CognixV2', desc: 'OPTIMIZED WORKFLOW' },
    { id: 'gemini-3-flash-preview', label: 'CloraN1', desc: 'SYSTEM OPERATIONS' },
    { id: 'gemini-3-pro-preview', label: 'CoreaRv1', desc: 'CREATIVE INTELLIGENCE' },
    { id: 'gemini-flash-lite-latest', label: 'Flash Lite', desc: 'MAXIMUM EFFICIENCY' },
    // Neural Visualizer removed from selectable models as requested. 
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden">

      {/* Messages */}
      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-10">
             <h2 className="text-3xl sm:text-5xl font-bold text-black dark:text-white tracking-tight mb-2 leading-tight">What's your plan today?</h2>
             <div className="flex items-center gap-2 mt-2">
                <p className="text-[11px] font-bold uppercase tracking-widest text-slate-800 dark:text-slate-400">Cognix Intelligence Active</p>
             </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8 w-full">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-3 sm:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-9 sm:h-9 shrink-0 rounded-lg flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-black border-black text-white' : 'bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-3 text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-black text-white rounded-2xl rounded-tr-sm' : 'bg-slate-100 dark:bg-slate-800/80 text-black dark:text-white border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm'}`}>
                      {p.inlineData && (
                        <div className="mb-2 rounded-xl overflow-hidden border border-slate-300 dark:border-slate-700 shadow-md">
                          <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[350px] w-full object-contain" alt="Asset" />
                        </div>
                      )}
                      {p.text ? (
                        <div className="whitespace-pre-wrap">{p.text}</div>
                      ) : (
                        // If it's the latest model message and it's empty, show loading inside the bubble
                        idx === messages.length - 1 && isLoading && m.role === 'model' && (
                          <div className="flex gap-1 py-1">
                            <div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce [animation-duration:0.6s]"></div>
                            <div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.2s]"></div>
                            <div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce [animation-duration:0.6s] [animation-delay:0.4s]"></div>
                          </div>
                        )
                      )}
                    </div>
                  ))}
                  {m.isSearching && (
                    <div className="flex items-center gap-2 px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-full mt-1 border border-slate-200 dark:border-slate-700">
                        <div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-bold text-black dark:text-white uppercase tracking-widest">Searching...</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Input */}
      <div className={`fixed left-0 right-0 p-3 sm:p-5 lg:pl-[280px] z-[60] pointer-events-none transition-all duration-500 ${
        hasMessages ? 'bottom-0' : 'bottom-8 sm:bottom-16'
      }`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-300 dark:border-slate-700 rounded-[2rem] p-2 sm:p-3 shadow-2xl">

            {selectedImage && (
              <div className="px-3 py-1 flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 mb-2">
                  <div className="relative w-12 h-12 rounded-lg overflow-hidden border border-slate-300 dark:border-slate-600">
                    <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                    <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold">×</button>
                  </div>
              </div>
            )}

            <div className="flex items-center gap-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white rounded-xl transition-all">
                  <ImageIcon className="w-6 h-6" />
                  <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) {
                      const r = new FileReader();
                      r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                      r.readAsDataURL(f);
                    }
                  }} />
                </button>

                <textarea 
                  ref={textareaRef}
                  value={input}
