                  <svg className="w-2.5 h-2.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M18 15l-6-6-6 6" /></svg>
                </button>
                <div className="flex items-center gap-5">
                    <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1 text-[9px] font-bold uppercase tracking-widest ${isSearchEnabled ? 'text-black dark:text-white' : 'text-slate-600 dark:text-slate-500'}`}>
                      <span className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-black dark:bg-white' : 'bg-slate-400 dark:bg-slate-600'}`}></span> SEARCH
                    </button>
                    <button onClick={() => setShowShareModal(true)} className="flex items-center gap-1.5 text-[9px] font-bold text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white">
                      <UsersIcon className="w-3.5 h-3.5" />
                      <span className="uppercase">{participants.length} Node</span>
                    </button>
                </div>
            </div>
          </div>
        </div>
      </div>

      {/* Model Selector */}
      {showModelMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-[320px] rounded-t-[2.5rem] sm:rounded-3xl p-6 shadow-2xl animate-slide-up-pop border-t sm:border border-slate-300 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="w-10 h-1 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-6 sm:hidden" />
            <div className="space-y-1">
               {modelOptions.map((opt, idx) => (
                 <button 
                   key={`${opt.id}-${idx}`} 
                   onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                   className={`w-full flex flex-col items-start gap-1 p-4 rounded-2xl transition-all text-left group
                     ${model === opt.id && activeModelData.label === opt.label ? 'bg-slate-100 dark:bg-slate-800 text-black dark:text-white font-bold' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40 text-slate-800 dark:text-slate-300'}`}
                 >
                    <p className="text-[16px] font-bold tracking-tight leading-none">{opt.label}</p>
                    <p className="text-[10px] font-bold uppercase tracking-widest text-slate-600 dark:text-slate-500">{opt.desc}</p>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

