import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { CodeIcon, CopyIcon, ImageIcon, SparklesIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'dev'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const fileRef = useRef<HTMLInputElement>(null);

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        if (activeTool !== 'dev') setResult('');
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            let targetModel = model;

            switch(activeTool) {
                case 'summarizer': instruction = "Summarize the following content into clear, high-impact bullet points."; break;
                case 'scanner': instruction = "Analyze this image and provide a professional, detailed breakdown of its contents and context."; targetModel = 'gemini-3-flash-preview'; break;
                case 'writer': instruction = "Act as a professional content writer. Write a comprehensive, engaging article or post based on the following brief."; break;
                case 'enhancer': instruction = "Transform this basic AI prompt into a high-fidelity, engineered prompt for maximum output quality. Output ONLY the enhanced prompt."; break;
                case 'dev': instruction = "ACT AS A SENIOR FRONTEND ENGINEER. Build a high-fidelity, single-file responsive website using Tailwind CSS and standard JS. OUTPUT: Raw HTML only. Start with <!DOCTYPE html>. No commentary."; break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModel,
                contents: [{ parts }],
            });
            setResult(response.text || '');
        } catch (e) {
            setResult('Process interrupted. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'DOC CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION ANALYSIS' },
        { id: 'writer', label: 'Content Writer', desc: 'CREATIVE ENGINE' },
        { id: 'enhancer', label: 'Prompt Enhancer', desc: 'PROMPT ENGINEERING' },
        { id: 'dev', label: 'Dev Studio', desc: 'UI ARCHITECT' }
    ];

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-6xl mx-auto space-y-10">
                <header>
                    <h2 className="text-3xl font-bold text-black dark:text-white tracking-tight uppercase leading-none mb-2">Cognix Lab</h2>
                    <p className="text-black dark:text-slate-400 font-bold text-[11px] uppercase tracking-widest">Specialized Nodes for Professional Workflows</p>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); setSelectedImage(null); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-black bg-slate-50 dark:bg-slate-800 shadow-sm' 
                                    : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-slate-300'}
                            `}
                        >
                            <p className={`text-[13px] font-bold tracking-tight leading-none ${activeTool === tool.id ? 'text-black dark:text-white' : 'text-slate-800 dark:text-slate-300'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-black dark:text-slate-500 font-bold uppercase tracking-widest opacity-80">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className={`grid grid-cols-1 ${activeTool === 'dev' && result ? 'lg:grid-cols-2' : ''} gap-8`}>
                    <div className="space-y-6">
                        <div className="p-6 rounded-[1.5rem] border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm space-y-4">
                            {activeTool === 'scanner' && (
                                <div className="mb-4">
                                    <button 
                                        onClick={() => fileRef.current?.click()}
                                        className="w-full py-8 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-2xl flex flex-col items-center justify-center gap-3 hover:border-black dark:hover:border-white transition-all group"
                                    >
                                        {selectedImage ? (
                                            <div className="relative w-24 h-24 rounded-xl overflow-hidden shadow-lg border border-slate-300">
                                                <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" alt="To scan" />
                                            </div>
                                        ) : (
                                            <>
                                                <ImageIcon className="w-8 h-8 text-slate-600" />
                                                <span className="text-[10px] font-bold text-black dark:text-slate-400 uppercase tracking-widest">Inject Image Asset</span>
                                            </>
                                        )}
                                        <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                                            const f = e.target.files?.[0];
                                            if (f) {
                                                const r = new FileReader();
                                                r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                                                r.readAsDataURL(f);
                                            }
                                        }} />
                                    </button>
                                </div>
                            )}

                            <textarea 
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                placeholder={activeTool === 'dev' ? "Describe UI requirements..." : `Provide input context...`}
                                className="w-full p-4 h-40 rounded-xl bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 outline-none text-black dark:text-white text-sm font-medium placeholder-slate-500"
                            />

                            <button 
                                onClick={runTool}
                                disabled={loading || (!input.trim() && !selectedImage)}
                                className="w-full py-4 rounded-xl font-bold text-[11px] uppercase tracking-widest text-white bg-black dark:bg-white dark:text-black hover:opacity-90 disabled:opacity-20 active:scale-95 transition-all flex items-center justify-center gap-3 shadow-md"
                            >
                                {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white dark:border-black/30 dark:border-t-black rounded-full animate-spin"></div> : null}
                                {loading ? 'Synthesizing Node...' : `Execute ${activeTool === 'dev' ? 'UI Architect' : activeTool}`}
                            </button>
                        </div>

                        {result && activeTool !== 'dev' && (
                            <div className="p-6 rounded-[1.5rem] bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 animate-fade-in relative shadow-inner overflow-hidden">
                                <div className="flex items-center justify-between mb-6">
                                    <span className="text-[9px] font-bold uppercase tracking-widest text-black dark:text-white px-2 py-1 bg-white dark:bg-black rounded border border-slate-300 dark:border-slate-700">Output Node</span>
                                    <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg shadow-sm text-slate-700 hover:text-black dark:hover:text-white border border-slate-200 dark:border-slate-700 transition-colors">
                                        <CopyIcon className="w-3.5 h-3.5" />
                                    </button>
                                </div>
                                <div className="max-w-none text-black dark:text-white font-medium leading-loose text-[15px]">
                                    {result.split('\n').map((line, i) => line.trim() ? <p key={i} className="mb-3">{line}</p> : <br key={i}/>)}
                                </div>
                            </div>
                        )}
                    </div>

                    {result && activeTool === 'dev' && (
                        <div className="space-y-4 animate-fade-in h-[600px] flex flex-col">
                            <div className="flex items-center justify-between px-2">
                                <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-black dark:text-white">Live Preview</span>
                                <div className="flex gap-2">
                                    <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-300 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white">
                                        <CopyIcon className="w-3.5 h-3.5" />
                                    </button>
                                </div>
                            </div>
                            <div className="flex-1 rounded-3xl overflow-hidden border border-slate-300 dark:border-slate-700 bg-white shadow-2xl">
                                <iframe srcDoc={result} className="w-full h-full border-none" />
                            </div>
                        </div>
                    )}
                </div>
            </div>
            <p className="text-center py-10 text-[10px] font-bold text-black dark:text-white uppercase tracking-[0.4em]">Persistent Intelligence Layer 1.1</p>
        </div>
    );
};

