                            <button onClick={() => navigator.clipboard.writeText(result)} className="absolute top-4 right-4 p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 transition-all active:scale-90"><CopyIcon className="w-4 h-4" /></button>
                            <div className="max-w-none text-black dark:text-white font-medium leading-relaxed text-sm whitespace-pre-wrap">{result}</div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black dark:bg-white',
    primaryHover: 'hover:opacity-90',
    text: 'text-black dark:text-white',
    textDark: 'text-white dark:text-black',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200 dark:border-slate-800',
    ring: 'focus:ring-black dark:focus:ring-white',
    gradient: 'bg-black dark:bg-white'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-pro-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your elite AI companion by Shashwat Ranjan Jha. I provide high-fidelity intelligence focusing on precise reasoning, creative content, and architectural coding.");
  const [deploymentHtml, setDeploymentHtml] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedVault = localStorage.getItem('nexzi_vault');
    if (savedVault) setMemories(JSON.parse(savedVault));

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const params = new URLSearchParams(window.location.search);

    // Handle Shared Sessions
    const handshake = params.get('handshake');
    if (handshake) {
      try {
        const decoded = JSON.parse(atob(handshake));
        const newId = 'session-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Joined Session',
          messages: decoded.messages || [],
          participants: ['You', 'Founder Node']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
      } catch (e) { console.error("Invalid handshake", e); }
    }

    // Handle Deployed UI Assets
    const deployment = params.get('deployment');
    if (deployment) {
      try {
        const decoded = decodeURIComponent(escape(atob(deployment)));
        setDeploymentHtml(decoded);
      } catch (e) { console.error("Deployment corrupt", e); }
    }

    // Clean URL
    if (handshake || deployment) {
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => {
    localStorage.setItem('nexzi_vault', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) : 'New Pulse';
        setChatHistory([{ id: newId, title: title || 'New Pulse', messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      {deploymentHtml ? (
        <div className="fixed inset-0 z-[1000] bg-white dark:bg-black">
          <div className="absolute top-4 right-4 z-[1001]">
            <button onClick={() => setDeploymentHtml(null)} className="px-4 py-2 bg-black text-white dark:bg-white dark:text-black rounded-xl font-bold text-xs uppercase">Close Preview</button>
          </div>
          <iframe srcDoc={deploymentHtml} className="w-full h-full border-none" />
        </div>
      ) : null}

      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className={`flex-1 flex flex-col h-full relative overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-0' : ''}`}>
        <header className="h-14 sm:h-18 flex items-center justify-between px-4 sm:px-12 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-3 sm:gap-6">
            <button onClick={() => {
              if (window.innerWidth < 1024) setIsSidebarOpen(true);
              else setIsSidebarCollapsed(!isSidebarCollapsed);
            }} className="p-2 -ml-2 text-black dark:text-white transition-all hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="flex items-center gap-2 sm:gap-4">
              <BotIcon className="w-8 h-8 sm:w-10 sm:h-10 cursor-pointer" onClick={handleNewChat} />
              <div className="h-5 w-[1px] bg-slate-300 dark:bg-slate-700 mx-1 sm:mx-2"></div>
              <div className="flex flex-col">
                <span className="text-[14px] sm:text-lg font-bold text-black dark:text-white tracking-tight uppercase leading-none">{mode.toUpperCase()}</span>
                <span className="text-[8px] font-bold text-slate-500 uppercase hidden sm:block">Nexus v11</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
            <button 
              onClick={() => setMode(mode === 'live' ? 'chat' : 'live')}
              className={`w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center rounded-xl transition-all shadow-sm border ${mode === 'live' ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-slate-100 dark:bg-slate-800 text-black dark:text-white hover:opacity-80'}`}
              title="Live Talk"
            >
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center bg-slate-100 dark:bg-slate-800 rounded-xl text-black dark:text-white hover:opacity-80 transition-all shadow-sm border border-slate-200 dark:border-slate-700"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, CopyIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed 
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const generateShareLink = () => {
    const data = {
      title: currentChat?.title || 'Shared Session',
      messages: messages.slice(-20) 
    };
    try {
        const b64 = btoa(JSON.stringify(data));
        const url = `${window.location.origin}${window.location.pathname}?handshake=${b64}`;
        navigator.clipboard.writeText(url);
        setCopiedLink(true);
        setTimeout(() => setCopiedLink(false), 2000);
    } catch(e) { console.error("Sharing failed", e); }
  };

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });
      const isImgRequest = /draw|image|create image|generate image/i.test(trimmedInput);

      let targetModel = model;
      let finalInstruction = systemInstruction + " IMPORTANT: DO NOT USE BOLD OR ITALIC MARKDOWN (no ** or ***). Use plain text ONLY. Avoid '*' symbols completely in your output formatting.";

      let config: any = { systemInstruction: finalInstruction };

      if (model === 'gemini-3-pro-preview') {
        config.thinkingConfig = { thinkingBudget: 32768 };
        config.systemInstruction += " You are Clora, a high-fidelity reasoning node. Your intelligence is profound but requires more processing cycles.";
      } else if (model === 'gemini-3-flash-preview') {
        config.systemInstruction += " You are CognixV2, a lightning-fast pulse node. Be rapid, fun, and use emojis.";
      }

      if (isImgRequest) targetModel = 'gemini-2.5-flash-image';

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { ...config, tools: isSearchEnabled && !isImgRequest ? [{ googleSearch: {} }] : [] }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link lost. Recovering..." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages]);

  const modelOptions = [
    { id: 'gemini-3-flash-preview', label: 'CognixV2', desc: 'FAST PULSE' },
    { id: 'gemini-3-pro-preview', label: 'Clora', desc: 'HIGH FIDELITY' },
    { id: 'gemini-flash-lite-latest', label: 'Lite Node', desc: 'MAX EFFICIENCY' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-10">
             <h2 className="text-3xl sm:text-5xl font-bold text-black dark:text-white tracking-tight mb-2 leading-tight">Uplink established.</h2>
             <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Created by Shashwat Ranjan Jha</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8 w-full">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-3 sm:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-9 sm:h-9 shrink-0 rounded-lg flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-black border-black text-white' : 'bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-3 text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-black text-white rounded-2xl rounded-tr-sm' : 'bg-slate-100 dark:bg-slate-800/80 text-black dark:text-white border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[350px] w-full object-contain mb-2 rounded-xl" alt="Asset" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1 py-1"><div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce delay-100"></div><div className="w-1.5 h-1.5 bg-black dark:bg-white rounded-full animate-bounce delay-200"></div></div>)}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-3 sm:p-5 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-20' : 'lg:pl-[280px]'} ${hasMessages ? 'bottom-0' : 'bottom-8 sm:bottom-16'}`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-300 dark:border-slate-700 rounded-[2rem] p-2 sm:p-3 shadow-2xl">
            {selectedImage && <div className="px-3 py-1 flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 mb-2"><div className="relative w-12 h-12 rounded-lg overflow-hidden border border-slate-300 dark:border-slate-600"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold">×</button></div></div>}
            <div className="flex items-center gap-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white rounded-xl transition-all"><ImageIcon className="w-6 h-6" /><input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} /></button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Ask Cognix..." className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[16px] text-black dark:text-white placeholder-slate-500 font-medium max-h-[120px] min-h-[40px]" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-10 h-10 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-95"><SendIcon className="w-5 h-5" /></button>
            </div>
            <div className="flex items-center justify-between mt-1 px-3">
                <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-1.5 py-1 text-slate-800 dark:text-slate-200 font-bold text-[10px] uppercase tracking-tight">{activeModelData.label} ▾</button>
                <div className="flex items-center gap-4">
                    <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1 text-[9px] font-bold uppercase tracking-widest ${isSearchEnabled ? 'text-blue-600' : 'text-slate-500'}`}><span className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-400'}`}></span> SEARCH</button>
                    <button onClick={generateShareLink} className={`flex items-center gap-1.5 text-[9px] font-bold transition-all ${copiedLink ? 'text-green-500' : 'text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white'}`}>
                      <UsersIcon className="w-3.5 h-3.5" />
                      <span className="uppercase">{copiedLink ? 'LINK COPIED' : 'INVITE FRIEND'}</span>
                    </button>
                </div>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0b0f1a] w-full max-w-[320px] rounded-t-[2.5rem] sm:rounded-3xl p-6 shadow-2xl animate-slide-up-pop border-t sm:border border-slate-300 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="space-y-1">
               {modelOptions.map((opt) => (
                 <button key={opt.id} onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} className={`w-full flex flex-col items-start gap-1 p-4 rounded-2xl transition-all text-left ${model === opt.id ? 'bg-slate-100 dark:bg-slate-800 text-black dark:text-white font-bold' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40 text-slate-800 dark:text-slate-300'}`}>
                    <p className="text-[16px] font-bold tracking-tight leading-none">{opt.label}</p>
                    <p className="text-[10px] font-bold uppercase tracking-widest text-slate-600 dark:text-slate-500">{opt.desc}</p>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { CodeIcon, CopyIcon, ImageIcon, SparklesIcon, SendIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'dev'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');
    const [publishedUrl, setPublishedUrl] = useState<string | null>(null);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const [devLogs, setDevLogs] = useState<string[]>([]);
    const fileRef = useRef<HTMLInputElement>(null);

    const logActivity = (msg: string) => {
        setDevLogs(prev => [...prev.slice(-4), msg]);
    };

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        if (activeTool !== 'dev') setResult('');
        setPublishedUrl(null);
        setDevLogs([]);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            let targetModel = model;

            if (activeTool === 'dev') {
                logActivity("Initializing Neural Architecture...");
                setTimeout(() => logActivity("Analyzing UI Requirements..."), 1000);
                setTimeout(() => logActivity("Drafting Component Hierarchy..."), 2000);
                setTimeout(() => logActivity("Injecting Tailwind Stylings..."), 3500);
                setTimeout(() => logActivity("Optimizing Responsive Layout..."), 5000);
            }

            switch(activeTool) {
                case 'summarizer': instruction = "Summarize the following into elite bullet points."; break;
                case 'scanner': instruction = "Analyze this image in high detail."; targetModel = 'gemini-3-flash-preview'; break;
                case 'writer': instruction = "Write professional engaging content."; break;
                case 'enhancer': instruction = "Engineer a high-fidelity prompt from this input."; break;
                case 'dev': instruction = "ACT AS A SENIOR FRONTEND ENGINEER. Build a modern, mobile-responsive single-file landing page using Tailwind CSS. OUTPUT RAW HTML ONLY starting with <!DOCTYPE html>. No commentary."; break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModel,
                contents: [{ parts }],
            });

            if (activeTool === 'dev') logActivity("Synthesis Complete. Assembler Finalized.");
            setResult(response.text || '');
        } catch (e) {
            setResult('Uplink failed. Try again.');
        } finally {
            setLoading(false);
        }
    };

    const handlePublish = () => {
        if (!result) return;
        try {
            const b64 = btoa(unescape(encodeURIComponent(result)));
            const url = `${window.location.origin}${window.location.pathname}?deployment=${b64}`;
            setPublishedUrl(url);
        } catch(e) { console.error("Publish failed", e); }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION' },
        { id: 'writer', label: 'Writer', desc: 'CONTENT' },
        { id: 'enhancer', label: 'Enhancer', desc: 'PROMPT' },
        { id: 'dev', label: 'Dev Studio', desc: 'UI ARCHITECT' }
    ];

    if (activeTool === 'dev') {
        return (
            <div className="h-full bg-white dark:bg-[#020617] flex flex-col animate-fade-in overflow-hidden">
                <header className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <button onClick={() => setActiveTool('summarizer')} className="text-xs font-bold text-slate-500 hover:text-black dark:hover:text-white uppercase tracking-widest transition-colors">← Back to Lab</button>
                        <h2 className="text-sm font-bold tracking-tight uppercase px-3 py-1 bg-black text-white dark:bg-white dark:text-black rounded-lg">Dev Studio Node</h2>
                    </div>
                    {result && (
                        <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                            <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'preview' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                            <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'code' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>See Code</button>
                        </div>
                    )}
                </header>

                <div className="flex-1 flex overflow-hidden">
                    <div className="w-full sm:w-[400px] border-r border-slate-100 dark:border-slate-800 flex flex-col p-6 space-y-4">
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Describe your UI vision..."
                            className="flex-1 p-4 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm font-medium outline-none resize-none focus:border-black dark:focus:border-white transition-all"
                        />

                        {loading && devLogs.length > 0 && (
                            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden">
                                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-2">Activity Feed</p>
                                <div className="space-y-1">
                                    {devLogs.map((log, i) => (
                                        <p key={i} className={`text-[10px] font-mono ${i === devLogs.length - 1 ? 'text-blue-500 font-bold' : 'text-slate-500 opacity-60'}`}>{`> ${log}`}</p>
                                    ))}
                                </div>
                            </div>
                        )}

                        <button 
                            onClick={runTool}
                            disabled={loading || !input.trim()}
                            className="w-full py-4 bg-black dark:bg-white text-white dark:text-black rounded-2xl font-bold text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 disabled:opacity-30 transition-all"
                        >
                            {loading ? 'Synthesizing...' : 'Build UI Asset'}
                        </button>
                    </div>

                    <div className="flex-1 bg-slate-50 dark:bg-[#01040a] relative flex flex-col overflow-hidden">
                        {!result ? (
                            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 opacity-50">
                                <CodeIcon className="w-12 h-12 mb-4" />
                                <p className="text-xs font-bold uppercase tracking-widest">Architectural Node Ready</p>
                            </div>
                        ) : viewMode === 'preview' ? (
                            <div className="flex-1 flex flex-col">
                                <div className="flex items-center justify-between px-6 py-2 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Live Workspace</span>
                                    <button onClick={handlePublish} className="text-[10px] font-bold text-blue-600 hover:text-blue-700 uppercase tracking-widest transition-colors">Publish Deployment</button>
                                </div>
                                {publishedUrl && (
                                    <div className="p-3 bg-blue-50 dark:bg-blue-900/20 border-b border-blue-200 dark:border-blue-800 flex items-center justify-between gap-4 animate-slide-up">
                                        <p className="text-[9px] font-mono truncate text-blue-800 dark:text-blue-300">DEPLOYED: {publishedUrl}</p>
                                        <button onClick={() => { navigator.clipboard.writeText(publishedUrl); setPublishedUrl(null); }} className="px-3 py-1 bg-blue-600 text-white rounded-lg text-[9px] font-bold uppercase hover:bg-blue-700 transition-colors">Copy Link</button>
                                    </div>
                                )}
                                <iframe srcDoc={result} className="flex-1 w-full border-none bg-white" title="UI Preview" />
                            </div>
                        ) : (
                            <div className="flex-1 p-6 overflow-hidden flex flex-col">
                                <div className="flex justify-between mb-4">
                                     <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Raw Source</span>
                                     <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:scale-105 transition-all active:scale-95"><CopyIcon className="w-4 h-4"/></button>
                                </div>
                                <pre className="flex-1 p-6 bg-slate-900 text-slate-100 rounded-2xl text-xs overflow-auto custom-scrollbar font-mono leading-relaxed">
                                    {result}
                                </pre>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-6xl mx-auto space-y-10 pb-20">
                <header>
                    <h2 className="text-3xl font-bold text-black dark:text-white tracking-tight uppercase leading-none mb-2">Cognix Lab</h2>
                    <p className="text-black dark:text-slate-400 font-bold text-[11px] uppercase tracking-widest">Professional Creation Node</p>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); setSelectedImage(null); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-black bg-slate-50 dark:bg-slate-800 shadow-sm' 
                                    : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-slate-300'}
                            `}
                        >
                            <p className={`text-[13px] font-bold tracking-tight leading-none ${activeTool === tool.id ? 'text-black dark:text-white' : 'text-slate-800 dark:text-slate-300'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-black dark:text-slate-500 font-bold uppercase tracking-widest opacity-80">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className="max-w-xl mx-auto space-y-6">
                    <div className="p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-sm space-y-4 transition-all focus-within:border-black dark:focus-within:border-white">
                        {activeTool === 'scanner' && (
                            <div className="mb-4">
                                <button onClick={() => fileRef.current?.click()} className="w-full py-8 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl flex flex-col items-center justify-center gap-3 transition-all group hover:bg-slate-50 dark:hover:bg-slate-950">
                                    {selectedImage ? <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-20 h-20 rounded-xl object-cover shadow-lg border-2 border-white dark:border-slate-700" alt="Scan Asset" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                                    <span className="text-[9px] font-bold uppercase tracking-widest">Inject Asset</span>
                                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        if (f) {
                                            const r = new FileReader();
                                            r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                                            r.readAsDataURL(f);
                                        }
                                    }} />
                                </button>
                            </div>
                        )}
                        <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="Provide context..." className="w-full p-4 h-32 rounded-2xl bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 outline-none text-black dark:text-white text-sm font-medium focus:border-black dark:focus:border-white transition-all resize-none" />
                        <button onClick={runTool} disabled={loading || (!input.trim() && !selectedImage)} className="w-full py-4 rounded-2xl font-bold text-[10px] uppercase tracking-[0.3em] text-white bg-black dark:bg-white dark:text-black hover:opacity-90 disabled:opacity-20 active:scale-95 transition-all shadow-md">
                            {loading ? 'Synthesizing...' : `Execute ${activeTool.toUpperCase()}`}
                        </button>
                    </div>
                    {result && (
                        <div className="p-8 rounded-[2.5rem] bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 animate-slide-up relative shadow-sm overflow-hidden">
                            <button onClick={() => navigator.clipboard.writeText(result)} className="absolute top-4 right-4 p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 transition-all active:scale-90 hover:text-blue-600"><CopyIcon className="w-4 h-4" /></button>
                            <div className="max-w-none text-black dark:text-white font-medium leading-relaxed text-sm whitespace-pre-wrap">{result}</div>
                        </div>
                    )}
                </div>
            </div>
            <p className="text-center py-10 text-[10px] font-bold text-slate-400 uppercase tracking-[0.4em] select-none">Persistent Intelligence Layer 11.0</p>
        </div>
    );
};

