import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, SparklesIcon, BoltIcon, BrainIcon, GraduationCapIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const generateShareLink = () => {
    const data = {
      title: currentChat?.title || 'Shared Pulse',
      messages: messages.slice(-15) 
    };
    try {
        const b64 = btoa(unescape(encodeURIComponent(JSON.stringify(data))));
        const url = `${window.location.origin}${window.location.pathname}?handshake=${b64}`;
        navigator.clipboard.writeText(url);
        setCopiedLink(true);
        setTimeout(() => setCopiedLink(false), 2000);
    } catch(e) { console.error("Link generation failed", e); }
  };

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCRITICAL CONTEXT FROM YOUR MEMORY VAULT (Remember these details about the user):\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      // Strictly enforce no bolding/asterisks via prompt
      let finalInstruction = systemInstruction + vaultContext + 
        "\n\nSTRICT FORMATTING RULE: Do not use Markdown asterisks (*) for bolding or lists. Use plain text, hyphens (-), or CAPS for emphasis. NEVER respond with '***' or '**' syntax. If you want to bold something, just write it normally or in ALL CAPS.";

      let targetModel = model;
      let config: any = { systemInstruction: finalInstruction };

      // Model Persona Mapping
      if (model === 'gemini-3-pro-preview') {
        // "Clora" / "Think Deeper" / "Study"
        config.thinkingConfig = { thinkingBudget: 24000 };
        config.systemInstruction += " You are Clora, the elite High-Fidelity node. You take your time to process deeply.";
      } else {
        // "CognixV2" / "Quick Response"
        config.systemInstruction += " You are CognixV2, the Fast Pulse node. Be lightning quick and engaging.";
        targetModel = 'gemini-3-flash-preview';
      }

      // Special drawing detection
      if (/draw|image|generate|create image/i.test(trimmedInput)) {
        targetModel = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { ...config, tools: isSearchEnabled ? [{ googleSearch: {} }] : [] }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural uplink interrupted. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'Smart', desc: 'Thinks deeply or quickly based on task', icon: <SparklesIcon className="w-5 h-5"/>, tag: 'Clora Pro' },
    { id: 'gemini-3-flash-preview', label: 'Quick response', desc: 'Best for everyday conversation', icon: <BoltIcon className="w-5 h-5"/>, tag: 'CognixV2' },
    { id: 'gemini-3-pro-preview-deeper', label: 'Think deeper', desc: 'Better for more complex topics', icon: <BrainIcon className="w-5 h-5"/> },
    { id: 'gemini-3-pro-preview-study', label: 'Study and learn', desc: 'Quizzes, guided learning, and more', icon: <GraduationCapIcon className="w-5 h-5"/> }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-12 md:px-24 lg:px-48 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-40 pt-6' : 'flex flex-col items-center justify-center min-h-[90dvh] pb-64 px-6'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none mb-10">
             <h2 className="text-3xl sm:text-5xl font-bold text-black dark:text-white tracking-tight mb-2 leading-tight">Elite Uplink Active.</h2>
             <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Nexzi Neural Interface</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8 w-full">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-3 sm:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-8 h-8 sm:w-9 sm:h-9 shrink-0 rounded-lg flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-black border-black text-white' : 'bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-3 text-[15px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-black text-white rounded-2xl rounded-tr-sm' : 'bg-slate-100 dark:bg-slate-800/80 text-black dark:text-white border border-slate-200 dark:border-slate-700 rounded-2xl rounded-tl-sm'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[350px] w-full object-contain mb-2 rounded-xl shadow-md" alt="Neural Asset" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1 py-2"><div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-100"></div><div className="w-1.5 h-1.5 bg-blue-600 rounded-full animate-bounce delay-200"></div></div>)}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-3 sm:p-5 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-20' : 'lg:pl-[280px]'} ${hasMessages ? 'bottom-0' : 'bottom-8 sm:bottom-16'}`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-300 dark:border-slate-700 rounded-[2.2rem] p-2 sm:p-3 shadow-2xl">
            {selectedImage && <div className="px-3 py-1 flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 mb-2"><div className="relative w-12 h-12 rounded-lg overflow-hidden border border-slate-300 dark:border-slate-600"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold">×</button></div></div>}
            <div className="flex items-center gap-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-500 hover:text-black dark:hover:text-white rounded-xl transition-all"><ImageIcon className="w-6 h-6" /><input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} /></button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Message Cognix..." className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[16px] text-black dark:text-white placeholder-slate-400 font-medium max-h-[120px] min-h-[40px]" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-10 h-10 bg-black dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-95 transition-all"><SendIcon className="w-5 h-5" /></button>
            </div>
            <div className="flex items-center justify-between mt-1 px-3">
                <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-1.5 py-1 text-slate-900 dark:text-slate-100 font-bold text-[11px] uppercase tracking-tight hover:opacity-70 transition-all">{activeModelData.label} ▾</button>
                <div className="flex items-center gap-4">
                    <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1 text-[9px] font-bold uppercase tracking-widest transition-colors ${isSearchEnabled ? 'text-blue-600' : 'text-slate-400'}`}><span className={`w-1.5 h-1.5 rounded-full ${isSearchEnabled ? 'bg-blue-600' : 'bg-slate-400'}`}></span> SEARCH</button>
                    <button onClick={generateShareLink} className={`flex items-center gap-1.5 text-[9px] font-bold transition-all ${copiedLink ? 'text-green-500' : 'text-slate-500 hover:text-black dark:hover:text-white'}`}>
                      <UsersIcon className="w-3.5 h-3.5" />
                      <span className="uppercase">{copiedLink ? 'LINK COPIED' : 'ADD FRIEND'}</span>
                    </button>
                </div>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#111827] w-full max-w-[360px] rounded-t-[2.5rem] sm:rounded-3xl p-3 shadow-2xl animate-slide-up-pop border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="space-y-1">
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-4 p-4 rounded-2xl transition-all text-left group ${model === opt.id ? 'bg-slate-100 dark:bg-slate-800' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`p-2 rounded-xl transition-all ${model === opt.id ? 'text-blue-600 bg-blue-100 dark:bg-blue-900/30' : 'text-slate-400 dark:text-slate-500 group-hover:text-slate-900 dark:group-hover:text-white'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-0.5">
                        <span className={`text-[15px] font-bold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-700 dark:text-slate-300'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-1.5 py-0.5 rounded text-[8px] font-black uppercase tracking-widest bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400">{opt.tag}</span>}
                      </div>
                      <p className="text-[11px] font-medium text-slate-500 dark:text-slate-400 leading-tight">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black dark:bg-white',
    primaryHover: 'hover:opacity-90',
    text: 'text-black dark:text-white',
    textDark: 'text-white dark:text-black',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200 dark:border-slate-800',
    ring: 'focus:ring-black dark:focus:ring-white',
    gradient: 'bg-black dark:bg-white'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('gemini-3-flash-preview');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your elite AI companion. I focus on precision and creative intelligence.");
  const [deploymentHtml, setDeploymentHtml] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedVault = localStorage.getItem('nexzi_vault');
    if (savedVault) setMemories(JSON.parse(savedVault));

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const params = new URLSearchParams(window.location.search);

    // Handle Shared Sessions (Handshake)
    const handshake = params.get('handshake');
    if (handshake) {
      try {
        const decodedStr = decodeURIComponent(escape(atob(handshake)));
        const decoded = JSON.parse(decodedStr);
        const newId = 'friend-session-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Session',
          messages: decoded.messages || [],
          participants: ['You', 'Founder Node']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        setMode('chat');
      } catch (e) { console.error("Neural handshake corrupted", e); }
    }

    // Handle Deployed UI Assets
    const deployment = params.get('deployment');
    if (deployment) {
      try {
        const decoded = decodeURIComponent(escape(atob(deployment)));
        setDeploymentHtml(decoded);
      } catch (e) { console.error("Deployment corrupted", e); }
    }

    if (handshake || deployment) {
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => {
    localStorage.setItem('nexzi_vault', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) : 'New Pulse';
        setChatHistory([{ id: newId, title: title || 'New Pulse', messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-300 overflow-hidden font-sans">
      {deploymentHtml ? (
        <div className="fixed inset-0 z-[1000] bg-white dark:bg-black">
          <div className="absolute top-4 right-4 z-[1001]">
            <button onClick={() => setDeploymentHtml(null)} className="px-6 py-2.5 bg-black text-white dark:bg-white dark:text-black rounded-full font-black text-[10px] uppercase shadow-2xl">Close Asset</button>
          </div>
          <iframe srcDoc={deploymentHtml} className="w-full h-full border-none" />
        </div>
      ) : null}

      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className={`flex-1 flex flex-col h-full relative overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-0' : ''}`}>
        <header className="h-14 sm:h-18 flex items-center justify-between px-4 sm:px-12 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-3 sm:gap-6">
            <button onClick={() => {
              if (window.innerWidth < 1024) setIsSidebarOpen(true);
              else setIsSidebarCollapsed(!isSidebarCollapsed);
            }} className="p-2 -ml-2 text-black dark:text-white transition-all hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="flex items-center gap-2 sm:gap-4">
              <BotIcon className="w-8 h-8 sm:w-10 sm:h-10 cursor-pointer" onClick={handleNewChat} />
              <div className="h-5 w-[1px] bg-slate-300 dark:bg-slate-700 mx-1 sm:mx-2"></div>
              <div className="flex flex-col">
                <span className="text-[14px] sm:text-lg font-bold text-black dark:text-white tracking-tight uppercase leading-none">{mode.toUpperCase()}</span>
                <span className="text-[8px] font-bold text-slate-500 uppercase hidden sm:block">Nexus 11.0</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
            <button 
              onClick={() => setMode(mode === 'live' ? 'chat' : 'live')}
              className={`w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center rounded-2xl transition-all shadow-sm border ${mode === 'live' ? 'bg-black text-white dark:bg-white dark:text-black border-black dark:border-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:text-black dark:hover:text-white'}`}
              title="Voice Uplink"
            >
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-500 hover:text-black dark:hover:text-white transition-all shadow-sm border border-slate-200 dark:border-slate-700"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, SparklesIcon, BoltIcon, BrainIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const generateShareLink = () => {
    const data = {
      title: currentChat?.title || 'Shared Pulse',
      messages: messages.slice(-15) 
    };
    try {
        // Encoding with support for Unicode
        const b64 = btoa(unescape(encodeURIComponent(JSON.stringify(data))));
        const url = `${window.location.origin}${window.location.pathname}?handshake=${b64}`;
        navigator.clipboard.writeText(url);
        setCopiedLink(true);
        setTimeout(() => setCopiedLink(false), 2000);
    } catch(e) { console.error("Link generation failed", e); }
  };

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCRITICAL CONTEXT FROM YOUR MEMORY VAULT (Remember these details about the user):\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      // Strictly enforce no bolding/asterisks via prompt
      let finalInstruction = systemInstruction + vaultContext + 
        "\n\nSTRICT FORMATTING RULE: Do not use Markdown asterisks (*) for bolding or lists. Use plain text, hyphens (-), or CAPS for emphasis. NEVER respond with '***' or '**' syntax. If you want to bold something, just write it normally or in ALL CAPS. Keep responses clean and star-free.";

      let targetModel = model;
      let config: any = { systemInstruction: finalInstruction };

      // Model Persona Mapping
      if (model === 'gemini-3-pro-preview') {
        config.thinkingConfig = { thinkingBudget: 24000 };
        config.systemInstruction += " You are Clora, the high-fidelity node using Gemini 3 Pro. You provide deep, analytical reasoning.";
      } else if (model === 'gemini-3-flash-preview') {
        config.systemInstruction += " You are CognixV2, the fast pulse node using Gemini 3 Flash. Be rapid, fun, and concise.";
      } else if (model === 'gemini-flash-lite-latest') {
        config.systemInstruction += " You are the Lite Node using Gemini Flash Lite. Focus on extreme efficiency and directness.";
      }

      // Special drawing detection - Gemini 2.5 Flash Image is used for free tier image generation
      if (/draw|image|generate|create image/i.test(trimmedInput)) {
        targetModel = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModel,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { ...config, tools: isSearchEnabled ? [{ googleSearch: {} }] : [] }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural uplink interrupted. Please check your connection or try again." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', desc: 'Deep analytical reasoning for complex logic', icon: <SparklesIcon className="w-5 h-5"/>, tag: 'High Fidelity' },
    { id: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', desc: 'Instant responses for everyday creative tasks', icon: <BoltIcon className="w-5 h-5"/>, tag: 'Fast Pulse' },
    { id: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', desc: 'Ultra-efficient processing for quick data tasks', icon: <BrainIcon className="w-5 h-5"/>, tag: 'Lite Node' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[1];

  return (
